import bisect

def solve(nums, k):
    counts = {}
    for num in nums:
        counts[num] = counts.get(num, 0) + 1

    sorted_items = sorted(counts.items())
    cumulative_counts = [0] * (len(nums) + 1)
    for i in range(len(nums)):
        cumulative_counts[i + 1] = cumulative_counts[i] + sorted_items[i][1]

    target_index = bisect.bisect_left(cumulative_counts, len(nums) - k + 1)
    items_until_target = sorted_items[:target_index]
    numbers = [item for item, count in items_until_target]
    numbers.sort()
    first_occurrence = bisect.bisect_left(numbers, numbers[target_index - 1])
    if first_occurrence == 0:
        return numbers[target_index - 1]
    return numbers[first_occurrence - 1]

def solve_original(nums, k):
