import heapq

def solve(nums, k):
    return heapq.nsmallest(k, nums)[-1]

def heappush(heap, item):
    heap.append(item)
    heapq._heapify_max(heap)

def heappop(heap):
    return heapq._heappop_max(heap)

class MaxBinaryHeap:
    def __init__(self):
        self.heap = []

    def push(self, item):
        heappush(self.heap, item)

    def pop(self):
        return heappop(self.heap)

    def __len__(self):
        return len(self.heap)

class MinBinaryHeap:
    def __init__(self):
        self.heap = []

    def push(self, item):
        heappush(self.heap, -item)

    def pop(self):
        return -heappop(self.heap)

    def __len__(self):
        return len(self.heap)

class Heap:
    def __init__(self):
        self.max_heap = MaxBinaryHeap()
        self.min_heap = MinBinaryHeap()

    def push(self, num):
        if self.max_heap:
            if num < self.max_heap.peek():
                self.min_heap.push(num)
                self.sift_up(self.min_heap, self.min_heap.index(num))
            elif num > self.max_heap.peek():
                self.max_heap.push(num)
                self.sift_down(self.max_heap, self.max_heap.index(num))
            else:
                self.max_heap.push(num)
        else:
            self.max_heap.push(num)

    def pop(self):
        if not self.max_heap or (self.min_heap and self.min_heap.peek() < self.max_heap.peek()):
            return self.min_heap.pop()
        else:
            return self.max_heap.pop()

    def __len__(self):
        return len(self.max_heap) + len(self.min_heap)

class Counter:
    def __init__(self):
        self.heap = Heap()

    def count(self, num):
        for _ in range(10):
            self.heap.push(num)

    def kth_smallest(self, k):
        while len(self.heap) < k:
            self.heap.push(self.heap.pop() if self.heap.max_heap.peek() > self.heap.min_heap.peek() else self.heap.min_heap.pop())
        return self.heap.pop()

    def k_smallest(self, k):
        while len(self.heap) > k:
            if self.heap.max_heap.peek() > self.heap.min_heap.peek():
                self.heap.pop()
            else:
                self.heap.pop()
        return self.heap.peek()

def solve(nums, k):
    counter = Counter()
    for num in nums:
        counter.count(num)
    return counter.kth_smallest(k - 1) if k < len(nums) else counter.k_smallest(len(nums) - k + 1)
