def merge(regions):
    to_merge = []
    for region, count in regions:
        i = 0
        while i < len(to_merge):
            curr_region, curr_count = to_merge[i]
            if curr_region == region and curr_count < count:
                to_merge[i] = (region, count)
                return to_merge
            if curr_region > region:
                to_merge.insert(i, (region, count))
                return to_merge
            i += 1
        to_merge.append((region, count))
        return to_merge

def merge_sort(regions):
    if len(regions) < 2:
        return regions
    mid = len(regions) // 2
    left_half = merge_sort(regions[:mid])
    right_half = merge_sort(regions[mid:])
    return merge([left_half, right_half])

def helper(nums):
    counts = {}
    for num in nums:
        counts[num] = counts.get(num, 0) + 1
    return merge_sort(list(counts.items()))

def solve(nums, k):
    regions = helper(nums)
    counts = {}
    for num, count in regions:
        counts[num] = counts.get(num, 0) + count
    sorted_counts = sorted(counts.items(), key=lambda x: x[1])
    for i, (_, count) in enumerate(sorted_counts):
        if i + 1 >= k:
            return list(counts.keys())[i-k+1]
