import heapq

def solve(nums, k):
    def quickselect(nums, k):
        if len(nums) == 1:
            return nums[0]
        pivot = random.choice(nums)
        left = [x for x in nums if x < pivot]
        middle = [x for x in nums if x == pivot]
        right = [x for x in nums if x > pivot]
        i = bisect.bisect_left(len(left), k)
        if i < len(left):
            return quickselect(left, k)
        elif i < len(left) + len(middle):
            return middle[0]
        return quickselect(right, k - len(left) - len(middle))

    return quickselect(nums, k)

def compare_and_slice(nums1, nums2):
    for chunk in zip_longest(nums1, nums2):
        if chunk[0] < chunk[1]:
            return nums1
        elif chunk[0] > chunk[1]:
            return nums2
    return nums1

def chunked_sort(nums, k):
    chunks = [nums[i:i+k] for i in range(0, len(nums), k)]
    for i in range(0, len(chunks), 2):
        chunks[i] = sorted(chunks[i])
        if i + 1 < len(chunks):
            chunks[i+1] = sorted(chunks[i+1], reverse=True)
    for i in range(len(chunks) - 1, 0, -1):
        chunks[i-1] = combine(chunk for chunk in zipLongest(*chunks[i-1:i]))
    if len(chunks) == 1:
        return chunks[0]
    return chunks[0][:k]

def combine(chunks):
    sorted_chunk = sorted(chunks)
    heapq.heapify(sorted_chunk)
    new_chunk = []
    while len(new_chunk) != len(chunks[0]):
        new_chunk.append(heapq.heappop(sorted_chunk))
    return new_chunk

def merge_sorted_lists(left, right):
    result = []
    while left and right:
        if left[0] < right[0]:
            result.append(left.pop(0))
        else:
            result.append(right.pop(0))
    result.extend(left)
    result.extend(right)
    return result

