import random

def solve(nums, k):
    def quickselect(arr, k):
        if len(arr) == 1:
            return arr[0]
        pivot = random.choice(arr)
        left = [x for x in arr if x < pivot]
        middle = [x for x in arr if x == pivot]
        right = [x for x in arr if x > pivot]
        if k <= len(left):
            return quickselect(left, k)
        elif k <= len(left) + len(middle):
            return middle[0]
        else:
            return quickselect(right, k - len(left) - len(middle))

    return quickselect(nums, k)

def partition(a, l, r):
    i = (l - 1)  # index of smaller element
    pivot = a[r]
    for j in range(l, r):
        if a[j] <= pivot:
            i += 1
            a[i], a[j] = a[j], a[i]
    a[i + 1], a[r] = a[r], a[i + 1]
    return i + 1

def quickselect(a, k):
    if len(a) == 1:
        return a[0]
    l, r = 0, len(a) - 1
    while True:
        pivot_index = partition(a, l, r)
        if k == pivot_index + 1:
            return a[pivot_index]
        elif k < pivot_index + 1:
            r = pivot_index - 1
        else:
            k -= pivot_index + 1
            l = pivot_index + 1
