import heapq
import bisect

def solve(nums, k):
    counts = {}
    for num in nums:
        counts[num] = counts.get(num, 0) + 1
    sorted_nums = sorted(counts.keys())
    lst = [0] * (len(sorted_nums) + 1)
    for num, count in counts.items():
        idx = bisect.bisect_left(sorted_nums, num)
        lst[idx] += count
    max_heap = []
    for i in range(1, len(lst)):
        if lst[i] > 0:
            heapq.heappush(max_heap, (-lst[i], sorted_nums[i-1]))
    for _ in range(k):
        val = heapq.heappop(max_heap)
        lst[sorted_nums.index(val[1])] -= 1
        if lst[sorted_nums.index(val[1])] == 0:
            del lst[sorted_nums.index(val[1])]
            sorted_nums.pop(sorted_nums.index(val[1]))
        heapq.heappush(max_heap, val)
    return val[1]
