    for num, freq in count.items():
        sorted_count[num] = (freq, sorted_count[num])

    q = [(sorted_count[num][0], num) for num in sorted_count]
    heapq.heapify(q)

    while k > 1:
        freq, num = heapq.heappop(q)
        freq -= 1
        if freq:
            heapq.heappush(q, (freq, num))
        k -= 1

    return q[0][1]

