    if min_heap:
        heapq.heapify(nums)
        for i in range(len(nums) - k):
            heapq.heappop(nums)
    else:
        for i in range(k):
            _minheapify(nums, len(nums) - 1 - i, False)
        for i in range(len(nums) - k):
            _maxheapify(nums, len(nums) - 1 - i, False)
    return nums[-1] if min_heap else nums[0]
