def quickselect(nums, k):
    if len(nums) == 1:
        return nums[0]
    pivot = nums[len(nums) // 2]
    left = [x for x in nums if x < pivot]
    middle = [x for x in nums if x == pivot]
    right = [x for x in nums if x > pivot]
    if k <= len(left):
        return quickselect(left, k)
    elif k <= len(left) + len(middle):
        return middle[0]
    else:
        return quickselect(right, k - len(left) - len(middle))

def partition(nums, low, high):
    i = (low - 1)
    pivot = nums[high]
    for j in range(low, high):
        if nums[j] < pivot:
            i += 1
            nums[i], nums[j] = nums[j], nums[i]
    nums[i + 1], nums[high] = nums[high], nums[i + 1]
    return (i + 1)

def randomized_quickselect(nums, k):
    if len(nums) == 1:
        return nums[0]
    pivot_index = partition(nums, 0, len(nums) - 1)
    pivot_index = (random.randint(0, len(nums) - 1)) if (pivot_index == 0) else pivot_index
    if k <= pivot_index:
        return randomized_quickselect(nums[:pivot_index], k)
    elif k > pivot_index:
        return randomized_quickselect(nums[pivot_index + 1:], k - pivot_index - 1)

def quickselect_helper(nums, k):
    nums.sort()
    m = len(nums) // 2
    if k == len(nums):
        return nums[m]
    elif k < m:
        return quickselect_helper(nums[:m], k)
    else:
        return quickselect_helper(nums[m+1:], k - m-1)

def solve(nums, k):
