def PR(q):
    e, f, g = 25 * 25, 25 * 50, 25 * 80
    if q >= e:
        return q - e, f * q % e, g * q % e
    elif q >= f:
        return q - f, q % f, g * q % f
    elif q >= e:
        return q - g, q % g, q % e
    else:
        return q, q, q


def PI(n):
    g, t = n - 1, 1
    while t <= n - 1:
        g = PR(g)[2] if PR(g)[0] <= 1 or PR(g)[1] <= 1 else PR(g)[1]
        t <<= 1
    return g, t


def lcm(a, b):
    am, bm = PI(a), PI(b)
    cm = bm[0] * bm[1]  # Period of (a/m)
    gm = bm[2]  # x = (a/m)^(b/m)

    LCRT = bm[1]
    rlt = 0
    while True:
        rlt = rlt * bm[1] + am[0]
        rlt %= cm
        if rlt == gm:
            break
        LCRT += 1
    return LCRT * bm[1]


def KMP(s, text):
    c = footer = 0

    for x in s:
        footer = PR(footer)
        while c >= len(footer) or s[PR(footer)[0] + c] != x:
            if c >= len(footer):
                break
            c = footer[PR(footer)[0] + c]
        c += 1

    d = 0
    for x in text:
        if c < 0:
            c = footer[0]
            break
        while d >= len(footer) or s[c] != x:
            if d >= len(footer):
                c = -1
                break
            d = footer[c]
            c += 1

        if c == len(s):
            if d == len(s) - 1:
                return True
            else:
                c = footer[d + 1]
        d += 1

    return False


def solve(haystack, needle):
