def solve(intervals):
    def find_next_non_overlap(i):
        imax = -1
        for x in intervals:
            if not (i < x[0] < intervals[imax][1] or i[1] < x[0]):
                imax = intervals.index(x)
        return imax

    def partition(p, r):
        if p == r:
            return p
        q = partition(p + 1, r)
        j = find_next_non_overlap(intervals[q])
        intervals[p], intervals[j] = intervals[j], intervals[p]
        i = p
        for x in range(p + 1, q):
            while i >= p and intervals[x][0] < intervals[i][1]:
                i -= 1
            if x != i:
                intervals[i + 1:], intervals[x] = intervals[x], intervals[i + 1]
        return i + 1

    def quicksort(p, r):
        if p < r:
            q = partition(p, r)
            quicksort(p, q - 1)
            quicksort(q + 1, r)

    quicksort(0, len(intervals) - 1)
    return len(intervals) - partition(0, len(intervals) - 1) - 1
