class UnionFind:
    def __init__(self, size):
        self.parent = list(range(size))

    def find(self, a):
        acopy = a
        while a != self.parent[a]:
            a = self.parent[a]
        while acopy != a:
            self.parent[acopy], acopy = a, self.parent[acopy]
        return a

    def union(self, a, b):
        self.parent[self.find(b)] = self.find(a)


def solve(intervals):
    events = sorted((start, 1, i) for i, (start, end) in enumerate(intervals)) + sorted((end, -1, i) for i, (start, end) in enumerate(intervals))
    uf = UnionFind(len(intervals) + 1)

    for start, delta, _ in events:
        end = start
        while True:
            j = uf.find(len(intervals) * 2)
            if j < len(intervals) * 2:
                min_brand = uf.find(j - len(intervals))
                if events[min_brand][0] == uf.parent[j]:
                    uf.parent[j] += delta
                    j = len(intervals) * 2
                else:
                    uf.union(min_brand, j)
            j = uf.find(len(intervals) * 2 + 1)
            if j < len(intervals) * 2 + 2:
                min_brand = uf.find(j - len(intervals) - 1)
                if events[min_brand][0] ==uf.parent[j]:
                    uf.parent[j] += delta
                    j = len(intervals) * 2 + 2
                else:
                    uf.union(min_brand, j)
            change = events[uf.find(len(intervals) * 2)][1] + events[uf.find(len(intervals) * 2 + 1)][1]
            j = uf.find(len(intervals) * 2)
            if uf.parent[j] + delta >= end:
                if events[uf.find(len(intervals) * 2)][0] < end or j != len(intervals) * 2:
                    return len(intervals) - sum(1 for j in uf.parent if j < len(intervals))
                end = uf.parent[j] + delta
            uf.parent[j] += delta
            j = uf.find(len(intervals) * 2 + 1)
            if uf.parent[j] + delta >= end:
                if events[uf.find(len(intervals) * 2 + 1)][0] < end or j != len(intervals) * 2 + 1:
                    return len(intervals) - sum(1 for j in uf.parent if j < len(intervals))
                end = uf.parent[j] + delta
            uf.parent[j] += delta
