        last = -1
        count, found = 0, False
        for i in range(len(grs)):
            if grs[i][1] < last:
                turtle.append(count)
                count, found = 0, False
            if i == 0 or grs[i][0] > pre:
                count += grs[i][1] - grs[i][0] + 1
                pre = grs[i][1]
                if found:
                    turtle.append(count)
                count, found = 0, True
            else:
