                last = pre
                pre = grs[i][1]
                if found:
                    turtle.append(count)
                count, found = 0, True

    intervals.sort()
    grs = [(i[1]-i[0]-1, i[0]) for i in intervals]
    grs.sort(reverse=True)
    pre, turtle = -1, []
    find_footprints(grs, pre, turtle)
