def multiply_matrices(a, b, modulo):
    c = [[0, 0], [0, 0]]
    c[0][0] = (a[0][0] * b[0][0] + a[0][1] * b[1][0]) % modulo
    c[0][1] = (a[0][0] * b[0][1] + a[0][1] * b[1][1]) % modulo
    c[1][0] = (a[1][0] * b[0][0] + a[1][1] * b[1][0]) % modulo
    c[1][1] = (a[1][0] * b[0][1] + a[1][1] * b[1][1]) % modulo
    return c

def power(matrix, n, modulo):
    if n == 0 or n == 1:
        return
    if n % 2 == 0:
        half_pow = power(matrix, n // 2, modulo)
        result = multiply_matrices(half_pow, half_pow, modulo)
    else:
        half_pow = power(matrix, n // 2, modulo)
        half_pow = multiply_matrices(half_pow, half_pow, modulo)
        result = multiply_matrices(half_pow, matrix, modulo)
    return result

def inverse(matrix, modulo):
    result = power(matrix, modulo - 2, modulo)
    return result

def fib_matrix(n):
    if n == 0:
        return [[1, 1], [1, 0]]
    elif n == 1:
        return [[1, 1], [0, 1]]
    else:
        F = fib_matrix(n // 2)
        matrix = multiply_matrices(F, F, 10**9 + 7)
        if n % 2 == 1:
            return multiply_matrices(matrix, [[1, 1], [1, 0]], 10**9 + 7)
        else:
            return matrix

def fast_solve(n):
    matrix = fib_matrix(n)
    F_1 = matrix[0][0] % 10**9
    F_2 = matrix[0][1] % 10**9
    return F_1
