from collections import defaultdict, deque

def construct_graph(n, prerequisites):
    graph = [[] for _ in range(n)]
    indegree = [0] * n
    for u, v in prerequisites:
        graph[v].append(u)
        indegree[u] += 1
    return graph, indegree

def topological_sort(graph, indegree):
    queue = deque([i for i in range(len(indegree)) if indegree[i] == 0])
    visit = set()
    result = []
    while queue:
        u = queue.popleft()
        visit.add(u)
        result.append(u)
        for v in graph[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                queue.append(v)
    return result if len(visit) == len(indegree) else []

def solve(n, prerequisites):
    if n == 0:
        return []

    graph, indegree = construct_graph(n, prerequisites)
    return topological_sort(graph, indegree)
