    major = freqs[k-1]
    return [num for num, freq in Counter(nums).items() if freq == major]

def helper_freqs(nums):
    counter = Counter(nums)
    return sorted(counter.values(), reverse=True)

def helper_major(freqs, k):
    return freqs[k-1]

def is_subset(major, freqs):
    for freq in freqs[k:]:
        if major >= freq:
            return False
    return True

def helper_same_len(major, freqs):
    return len([freq for freq in freqs if freq == major]) == k

def helper_check_condition(major, freqs):
    return is_subset(major, freqs) and helper_same_len(major, freqs)

def modified_binary_search(left, right, freqs, k):
    while left < right:
        mid = (left + right) // 2
        if helper_check_condition(helper_major(freqs, mid), helper_freqs(nums)):
            right = mid
        else:
            left = mid + 1
    return left

def helper_binary_search(min_val, max_val, freqs, k):
    return modified_binary_search(min_val, max_val, freqs, k)

def find_major(val1, val2):
    if val1 > val2:
        return val1
    else:
        return val2

def helper_operation(nums):
    return [max(0, num) for num in nums]

def main(nums, k):
    freqs = Counter(nums)
    min_val, max_val = min(freqs.values()), max(freqs.values())
    freqs = helper_operation(list(freqs.values()))
    if min_val > freqs[k-1]:
        return []
    if freqs[-1] == freqs[-2]:
        major = freqs[-1]
        return [num for num in nums if freqs[num] == major]
    while max_val > freqs[k-1] and freqs[k-1] < freqs[k]:
        val2 = find_major(max_val, freqs[k-1])
        if max_val <= val2 <= freqs[k-1]:
            right = freqs.index(max_val)
            return [num for num, freq in freqs.items() if freq == val2]
        min_val = freqs[k-1]
        left = freqs.index(min_val)
        major = helper_binary_search(left, right, freqs, k)
        if freqs[major] == val2:
            return [num for num, freq in freqs.items() if freq == val2]
        if max_val == freqs[-1]:
            return []
        val2 = find_major(max_val, freqs[-1])
        if max_val <= val2 <= freqs[k-1]:
            right = freqs.index(max_val)
            return [num for num, freq in freqs.items() if freq == val2]
        max_val = helper_binary_search(left, right, freqs, k)
    while freqs[k] != freqs[k-1]:
        val2 = find_major(freqs[k-1], freqs[k])
        right = freqs.index(freqs[k])
        left = freqs.index(freqs[k-1])
        major = helper_binary_search(left, right, freqs, k)
        if freqs[major] == val2:
