        count1, candidate = 0, None
        for x in nums:
            if count1 == 0:
                candidate = x
                count1 = 1
            elif candidate == x:
                count1 += 1
            else:
                count1 -= 1
        return candidate

    def majority_element(nums):
        candidate = get_majority_candidate(nums)
        count = sum(1 for x in nums if x == candidate)
        return candidate, count

    def majority_element_count(nums):
        candidate, count = majority_element(nums)
        assert count > len(nums) // 2
        return count

    n = len(nums)
    inf = 2 ** n
    f = [inf] * (n + 1)
    g = [inf] * (n + 1)
    f[0] = -inf
    for x in nums:
