        left, right = 0, len(arr)
        while left < right:
            mid = (left + right) // 2
            if arr[mid] < val:
                left = mid + 1
            else:
                right = mid
        return left

    length = len(nums)

    dp = [1] * length

    for i in range(1, length):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    max_val = max(dp)

    history = [[] for _ in range(max_val + 1)]
    history[1] = [i for i in range(length) if dp[i] == 1]

    for i in range(2, max_val + 1):
        history[i] = []
        for prev in range(i - 1, -1, -1):
            for pick in history[prev]:
                if nums[i - 1] > nums[pick] and dp[pick] + 1 == i:
                    history[i].append(i - 1)

    res = 0

    def backtrack(val, index):
        nonlocal res
        res = max(res, binary_search(history[val], index))
        for i in history[val]:
            backtrack(val - 1, i)

    for i in range(length):
        backtrack(dp[i], i)

    return res + 1
