        if n < 0:
            return float('-inf')
        elif n == 0:
            return 0
        res = float('-inf')
        for i in range(len(sub)):
            if nums[sub[-1]] > nums[i]:
                res = max(res, dp(subpop(i)))
        subpush(res + 1)
        return res + 1

    class binary_indexed_tree:
        def __init__(self, size):
            self.size = size
            self.data = [0] * size

        def query(self, n):
            res = 0
            while n > 0:
                res = max(res, self.data[n - 1])
                n -= n & -n
            return res

        def sub(self, n, x):
            while n <= self.size:
                self.data[n - 1] = max(self.data[n - 1], x)
                n += n & -n

        def subpop(self, m):
            if m == 0:
                return m
            l = 0
            r = len(sub - 1)
            while l < r:
                m = (l + r) >> 1
                if sub[m] >= m:
                    r = m
                else:
                    l = m + 1
            return dp(l)

        def subpush(self, m):
            if m == 0:
                return
            l = 0
            r = len(sub - 1)
            while l < r:
                m = (l + r + 1) >> 1
                if sub[m] < m:
                    l = m
                else:
                    r = m - 1
            sub[l] = m

    n = len(nums)
    sub = [n] * n
    bit = binary_indexed_tree(n + 1)
    for i in range(n - 1, -1, -1):
        sub[i] = i
        bit.sub(i + 1, dp(i))
    return bit.query(n)
