    def lengthOfLIS(i, memo):
        if i < 0:
            return 0
        if i >= len(nums):
            return 0
        if (i, -1) in memo:
            return memo[(i, -1)]
        ans = 1 + lengthOfLIS(i - 1, memo)
        for j in range(i - 1, -1, -1):
            if nums[i] > nums[j]:
                ans = max(ans, 1 + lengthOfLIS(j - 1, memo))
        memo[(i, -1)] = ans
        return ans

    maxSubsequenceLength = 0
    memo = {}
    for i in range(len(nums)):
        maxSubsequenceLength = max(maxSubsequenceLength, lengthOfLIS(i + 1, memo))
    return maxSubsequenceLength
