def lengthOfLIS(nums):
    n = len(nums)
    if n == 0:
        return 0

    def binary_search(arr, val):
        left, right = 0, len(arr) - 1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] == val:
                return mid
            elif arr[mid] < val:
                left = mid + 1
            else:
                right = mid - 1
        return left

    dp = [nums[0]]
    for i in range(1, n):
        if nums[i] > dp[-1]:
            dp.append(nums[i])
        else:
            idx = binary_search(dp, nums[i])
            dp[idx] = nums[i]

    return len(dp)

def solve(nums):
    return lengthOfLIS(nums)
