def solve(nums, k):
    if k == 1:
        return min(nums)
    elif k == len(nums):
        return max(nums)

    lo, hi = min(nums), max(nums)
    assert lo <= hi
    while True:
        mid = (lo + hi + 1) // 2  # use (lo+hi+1)//2 instead of lo+hi>>1 to prevent overflow
        nums, min_mid, max_mid = find_nums(nums, mid)
        if k <= len([num for num in nums if num < mid]):
            hi = mid - 1
        else:
            lo = mid
        if hi < lo:
            return mid
