def solve(nums, k):
    '''Returns the k-th smallest value in nums'''
    def modify(pairs):
        prev, count = pairs[0], 1
        for v, c in pairs[1:]:
            if v == prev:
                count += 1
            else:
                yield prev, count
                prev, count = v, 1
        yield prev, count

    # Count occurrences of each value
    pairs = [(v, nums.count(v)) for v in set(nums)]

    # Sort by value then by count, in descending order
    pairs.sort()
    pairs.sort(key=lambda x: (-x[0], -x[1]))

    # Yield the k-th smallest value
    for i, (x, y) in enumerate(modify(pairs)):
        if i == k - 1:
            return x
