def quicksort(nums, lo, hi):
    low, high = lo, hi
    while low < high:
        pivot = nums[(lo + hi) // 2]
        i = lo
        j = hi
        while i <= j:
            while nums[i] < pivot:
                i += 1
            while nums[j] > pivot:
                j -= 1
            if i <= j:
                nums[i], nums[j] = nums[j], nums[i]
                i += 1
                j -= 1
        if j < lo:
            quicksort(nums, lo, j)
            lo = j + 1
        elif low < i:
            quicksort(nums, i, high)
            high = i - 1
    return nums

def quicksort_range(nums, lo, hi):
    quicksort(nums, lo, hi)
