def rabin_karp(haystack, needle):
    def rolling_hash(s):
        result = 0
        for c in s:
            result = 32 * result + ord(c) - ord('a') + 1
        return result

    def match_length(hsh, n, h):
        if len(hsh) < n:
            return -1
        for i in range(len(hsh) - n + 1):
            if hsh[i:i+n] == [pow(32, j, int(pow(32, n+1) - 1)) for j in range(n)]:
                return i
        return -1

    h = len(haystack)
    n = len(needle)
    if n > h:
        return -1
    if n == 0:
        return 0

    needle_hash = rolling_hash(needle)
    haystack_hash = rolling_hash(haystack[:n])
    powers = []
    pow_ = 1
    for _ in range(n):
        powers.append(pow_)
        pow_ *= 32

    for i in range(h - n):
        if haystack_hash == needle_hash:
            if haystack[i:i+n] == needle:
                return i
        if i < h - n:
            haystack_hash = (pow_(n-1) * (ord(haystack[i+n]) - ord('a') + 1) + haystack_hash)%int(pow(32,n+1)-1)
    return -1

def solve(haystack, needle):
