    return res

def ithdigitexp(n, exp, num_digits):
    if exp == 0:
        return 1
    res = 10 ** (exp - 1) * ithdigitexp(n, exp - 1, num_digits)
    mult = powmod(n, num_digits - 1, 10 ** 9)
    for _ in range(exp - 1):
        res = (res * mult) % 10 ** 9
    return res

def ithdigitchapter(n, num_digits, tablesize):
    return (n * ithdigitexp(10, tablesize, num_digits)) % 10 ** 9

def ithdigitindex(n, num_digits, tablesize):
    table = [0] * tablesize
    for i in range(1, num_digits):
        table[i+1] = (powmod(10, i, 10 ** 9) + table[i+1]) % 10 ** 9
    low, high = 0, num_digits
    while high - low > 1:
        mid = (low + high) // 2
        res = ithdigitchapter(i - 1, i, tablesize) + ithdigitindex(i - 1, i, tablesize) + i * ithdigitexp(10, 9, i)
        if res == n:
            high = mid
        elif res < n:
            high = mid
        else:
            low = mid
    return low + 1

def ithfibonacci(n):
    table = [0] * 47
    table[1] = 1
    for i in range(2, 47):
        table[i] = (table[i - 1] + table[i - 2]) % 10 ** 9
    index = ithdigitindex(n, 47, 47)
    return ithdigitchapter(index - 1, 47, 47) + ithdigitindex(index - 1, 47, 47) + table[index]
