class Graph:
    def __init__(self, n):
        self.n = n
        self.g = [[] for _ in range(n)]
        self.in_degree = [0] * n

    def add_edge(self, a, b):
        self.g[a].append(b)
        self.in_degree[b] += 1

def solve(n, prerequisites):
    graph = Graph(n)
    for a, b in prerequisites:
        graph.add_edge(b, a)

    queue = deque([i for i in range(n) if graph.in_degree[i] == 0])
    result = []
    while queue:
        vertex = queue.popleft()
        result.append(vertex)
        for neighbor in graph.g[vertex]:
            graph.in_degree[neighbor] -= 1
            if graph.in_degree[neighbor] == 0:
                queue.append(neighbor)

    return result if len(result) == n else []
