from collections import defaultdict, deque

def solve(n, prerequisites):
    graph = defaultdict(list)
    indegree = [0] * n

    for a, b in prerequisites:
        graph[b].append(a)
        indegree[a] += 1

    queue = deque()
    for i in range(n):
        if indegree[i] == 0:
            queue.append(i)

    order, shift = [], 0
    while queue:
        size = len(queue)
        for _ in range(size):
            node = queue.popleft()
            order.append((node + shift, graph[node]))
        for _, edges in order[-1][1]:
            indegree[edges] -= 1
            if indegree[edges] == 0:
                queue.append(edges)
        shift += 1

    return order if len(order) == n else []
