def solve(nums, target):
    def binary_search(nums, condition, complement):
        left, right = 0, len(nums) - 1
        while left <= right:
            mid = (left + right) // 2
            if condition(mid):
                right = mid - 1
            else:
                left = mid + 1
        return complement(left, right)

    def first_occurrence(left, right):
        if nums[left] == target:
            if left == 0 or nums[left - 1] != target:
                return left
            else:
                return first_occurrence(left - 1, right - 1)
        else:
            return -1

    def last_occurrence(left, right):
        if nums[right] == target:
            if right == len(nums) - 1 or nums[right + 1] != target:
                return right
            else:
                return last_occurrence(left + 1, right)
        else:
            return -1

    first = binary_search(nums, lambda mid: nums[mid] < target, first_occurrence)
    last = binary_search(nums, lambda mid: nums[mid] > target, last_occurrence)

    if first == -1:
        return [-1, -1]
    else:
        return [first, last]
