import heapq

class MinHeap:
    def __init__(self, nums):
        self.heap = []
        for num in nums:
            self._add(num)

    def _add(self, num):
        prev_count = self.heap.count(num)
        heapq.heappush(self.heap, (num, -prev_count))
        self.heap.sort(key=lambda x: (x[0], -x[1]))

    def top_k(self, k):
        return (heapq.nsmallest(k, [num for num, _ in self.heap]), k)

class Solution:
    def solve(self, nums, k):
        return self.top_k(k)[0][-1] if self.top_k(k)[1] >= k else None

def solve(nums, k):
    min_heap = MinHeap(nums)
    return Solution().solve(nums, k)
