        heapify(nums, n, largest)


def heapify_and_pop(nums, k):
    n = len(nums)
    heap = nums.copy()

    for i in range(n // 2 - 1, -1, -1):
        heapify(heap, n, i)

    for _ in range(n - k):
        heap[0] = heap[-1]
        heap.pop()
        heapify(heap, len(heap), 0)

    return heap[0]


