    left = [x for i, x in enumerate(pub) if i < mid and x < pub[mid]]
    right = [x for i, x in enumerate(pub) if i > mid and x > pub[mid]]
    return get_medians(left, lo, mid-1) + [pub[mid]] + get_medians(right, mid+1, hi)

