        left, middle, right = [], [], []
        for x in nums[lo:hi+1]:
            if x < pivot:
                left.append(x)
            elif x == pivot:
                middle.append(x)
            else:
                right.append(x)
        return lo + len(left), middle, lo + len(left) + len(middle), right

    def quickselect(lo, hi):
        if lo == hi:
            return nums[lo]
        l, m, _, r = partition(lo, hi)
        if k == l + 1:
            return nums[l]
        elif k <= l + len(m):
            return min(m)
        elif k > l + len(m):
            return min(quickselect(l+1 + len(m), hi), *r)

    return quickselect(0, len(nums)-1)
