def solve(haystack: str, needle: str) -> int:
    """
    Return the index of the first position at which the string `needle` occurs as a contiguous substring of the string `haystack`.
    If `needle` is not a substring of `haystack`, return -1.
    """

    def match(i: int, j: int) -> bool:
        """
        True if the substrings `haystack[:i+len(needle)]` and `needle` are the same.
        """
        return all(haystack[k] == needle[k] for k in range(i, j + i))

    n = len(needle)
    if n > len(haystack):
        return -1
    for i in range(len(haystack) - n + 1):
        if match(i, n - 1):
            return i
    return -1
