        mismatched = n - 1
        while mismatched < n and haystack[offset + mismatched] == needle[mismatched]:
            mismatched += 1
        if mismatched == n:
            return offset
        offset += max(1, find_matching_prefix(needle, mismatched - shifts[ord(needle[mismatched]) - ord('a')]))
    return -1
