def solve(nums):
    def merge(A, left, mid, right):
        i = left
        j = mid
        temp = []
        while i <= mid and j <= right:
            if A[i] <= A[j]:
                temp.append(A[i])
                i += 1
            else:
                temp.append(A[j])
                repeated = A[j]
                start = left
                while start <= mid and A[start] == repeated:
                    start += 1
                start -= 1
                end = mid
                while end >= j and A[end] == repeated:
                    end -= 1
                return repeated, left, end
            if i > mid:
                temp.append(A[j])
                j += 1
            if j > right:
                temp.append(A[i])
                i += 1
        while i <= mid:
            temp.append(A[i])
            i += 1
        while j <= right:
            temp.append(A[j])
            j += 1
        A[left:right + 1] = temp

    def sort(A, left, right):
        if left >= right:
            return A
        mid = left + (right - left) // 2
        sort(A, left, mid)
        sort(A, mid + 1, right)
        merge(A, left, mid, right)

    sort(nums, 0, len(nums) - 1)
    for i in range(len(nums) - 1):
        if nums[i] == nums[i + 1]:
            return nums[i]
