            max_element = 0
            max_count = 0
            current_count = 0
            for i in range(1, len(nums)):
                if nums[i] == nums[short_p]:
                    current_count += 1
                else:
                    current_count = 0

                if current_count > max_count:
                    max_element = nums[i]
                    max_count = current_count

            return max_element
    return 0
