from collections import deque

def solve(n, edges):
    parent = list(range(n))
    rank = [0] * n
    count = n

    def find(i):
        if parent[i] != i:
            parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        pi, pj = find(i), find(j)
        if rank[pi] < rank[pj]:
            pi, pj = pj, pi
        parent[pj] = pi
        if rank[pi] == rank[pj]:
            rank[pi] += 1
        nonlocal count
        count -= 1

    edges = set(edges)
    for u, v in edges:
        union(u, v)

    seen = set()
    for i in range(n):
        if find(i) not in seen:
            queue = deque([find(i)])
            while queue:
                component_root = queue.popleft()
                seen.add(component_root)
                for u, v in edges:
                    if find(u) == component_root and find(v) not in seen:
                        queue.append(find(v))

    return len(seen)
