def solve(n, edges):
    parent = list(range(n))
    centroid_freq = [0] * n

    for u, v in edges:
        if find(parent, u) != find(parent, v):
            union(parent, u, v)

    queue = deque()
    for u in range(n):
        if centroid_freq[find(parent, u)] == 0:
            queue.append(u)
            while queue:
                node = queue.popleft()
                centroid_freq[find(parent, node)] -= 1
                for v, freq in neighbors(node, edges).items():
                    if find(parent, node) != find(parent, v):
                        centroid_freq[find(parent, v)] -= freq
                        if freq > 0:
                            queue.append(v)

    return n - sum(1 for freq in centroid_freq if freq > 0)

def find(parent, x):
    while x != parent[x]:
        x = parent[x]
    return x

def union(parent, x, y):
    parent[find(parent, y)] = find(parent, x)

def neighbors(node, edges):
    neighbors_freq = {}
    for u, v in edges:
        if u == node:
            neighbors_freq[v] = neighbors_freq.get(v, 0) + 1
        elif v == node:
            neighbors_freq[u] = neighbors_freq.get(u, 0) + 1
    return neighbors_freq
