class DisjointSet:
    def __init__(self, n):
        '''Initialize a disjoint-set data structure with a given number of elements.'''
        self.root = [i for i in range(n)]
        self.rank = [0] * n

    def find(self, x):
        '''Find the representative of the set that x belongs to.'''
        if x == self.root[x]:
            return x
        self.root[x] = self.find(self.root[x])
        return self.root[x]

    def union(self, x, y):
        '''Merge two given sets into a single set.'''
        x_root = self.find(x)
        y_root = self.find(y)
        if x_root == y_root:
            return
        if self.rank[x_root] < self.rank[y_root]:
            self.root[x_root] = y_root
        elif self.rank[x_root] > self.rank[y_root]:
            self.root[y_root] = x_root
        else:
            self.root[y_root] = x_root
            self.rank[x_root] += 1

def solve(n, edges):
    '''Calculate the number of connected components in an undirected graph.'''
    dsu = DisjointSet(n)
    for u, v in edges:
        dsu.union(u, v)
    return len(set(dsu.find(i) for i in range(n)))
