def label_propagation(n, edges):
    adj_list = [[] for _ in range(n)]
    color = list(range(n))

    def get_neighbors(u):
        return adj_list[u]

    def update_colors():
        new_colors = [-1 for _ in range(n)]
        stack = [i for i, c in enumerate(color) if c == -1]

        while stack:
            u = stack.pop()
            for v in get_neighbors(u):
                if color[v] != -1:
                    if color[u] == -1 or color[u] != color[v]:
                        new_colors[u] = color[v]
                        stack.append(u)
                else:
                    new_colors[u] = color[v]

        color = new_colors
        stack = [i for i, c in enumerate(color) if c == -1]

    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    for u in range(n):
        get_neighbors(u)

    updated = True
    while updated:
        updated = False
        for u, v in edges:
            if color[u] != color[v]:
                updated = True
                color[u] = color[v]

        update_colors()

    return len(set(color))
