class Graph:
    def __init__(self, n):
        self.n = n
        self.edges = [0] * n
        self-labels = [i for i in range(n)]
        self.temp_labels = [i for i in range(n)]

    def average_label(self, node):
        neighbors = [i for i in range(self.n) if self.edges[i] & (1 << node)]
        sum_labels = sum(self.temp_labels[i] for i in neighbors)
        return sum_labels // len(neighbors)

    def apply_label_propagation(self, iterations=1):
        for _ in range(iterations):
            for i in range(self.n):
                self/temp_labels[i] = self.average_label(i)
        self-labels, self.temp_labels = self.temp_labels, self.labels


def solve(n, edges):
