        graph.edges[u] |= (1 << v)
        graph.edges[v] |= (1 << u)
    for i in range(n):
        if not graph.edges[i]:
            graph.labels[i] = i
    graph.apply_label_propagation()
    connected_components = sum(1 for i in range(n) if graph.labels[i] == i)
