def helper(intervals, end:int, dp):
    """
    DFS helper function to process an Intervals list up to a given end point.
    """
    if len(intervals) == 0 or end < intervals[0][0]:
        return len(intervals)

    remove = len(intervals) + 1
    if len(intervals) > 0 and intervals[0][1] <= end:
        point = end + 1

        for interval in intervals:
            if interval[1] < point:
                point = interval[1]
            if interval[0] >= point:
                remove = min(remove, helper(intervals[1:], interval[1], dp))

    dp[(end, 0)] = remove
    dp[(end, 1)] = 0 if intervals[0][1] > end else dp[(end, 0)]

    return remove

def solve(intervals):
