    end = max(i[1] for i in intervals)

    # Filter intervals that end before or at start and start after end and also find the maximum end and minimum start.
    intervals = [i for i in intervals if start <= i[0] and i[1] <= end]

    # Sort intervals by end.
    intervals.sort(key=lambda x: x[1])

    # Do binary search to minimize work
    left, right = start, end
    while left < right:
        mid = (left + right + 1) // 2
        if helper(intervals, mid, dp) != len(intervals):
            left = mid
        else:
            right = mid - 1

    return dp[(left, 0)]
