            sl = [(getMemosel(j, 0) if canCover(intervals[j], (start, intervals[i][0])) else getMemosel(j, 1), j) for j in range(i + 1, len(intervals))]
            sl.sort(key=lambda x: x[0], reverse=True)
            for j, _ in sl:
                res[0] = min(res[0], getMemosel(j, 0) + 1)
                break
        memo[i][cover] = res
        return res

    intervals.sort(key=lambda x: x[0])
    memo = {(i, cover): [float('inf')] * 2 for i in range(len(intervals)) for cover in range(2)}
    res1 = [getMemosel(0, 1) if canCover((intervals[0][0], intervals[0][1]), (intervals[1][0], intervals[1][1])) else getMemosel(0, 0)][1]
    for i in range(2, len(intervals)):
        can_cover = canCover(intervals[i-1], intervals[i])
        res1 = min(res1, getMemosel(i-1, 1 if can_cover else 0)[1 - int(can_cover)] + 1)
