        for j in range(i + 1, len(intervals)):
            if not (intervals[i][1] < intervals[j][0] or intervals[j][1] < intervals[i][0]):
                union(parent, rank, i + 1, j + 1)

    parent_set = set()
    for i in range(1, size):
        parent_set.add(find_parent(parent, i))

