class UnionFind:
    def __init__(self, size):
        self.parent = list(range(size))
        self.rank = [0]*size

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        root_x = self.find(x)
        root_y = self.find(y)
        if root_x != root_y:
            if self.rank[root_x] > self.rank[root_y]:
                self.parent[root_y] = root_x
            else:
                self.parent[root_x] = root_y
                if self.rank[root_x] == self.rank[root_y]:
                    self.rank[root_y] += 1


def solve(intervals):
    points = set()
    for i, (start, end) in enumerate(intervals):
        points.add((start, i))
        points.add((end, -i))

    points = sorted(points)
    uf = UnionFind(len(intervals))

    count, value, conflict_count = 0, 0, 0
    for point, label in points:
        if label < 0:
            if value > point:
                conflict_count = 0
                uf.parent[-label] = -label
            else:
                conflict_count += 1
        else:
            value = max(value, point)
            if conflict_count and uf.find(label) != uf.find(intervals[label][1]):
                count += 1
                uf.union(label, intervals[label][1])
                conflict_count -= 1

    return count
