def find_graph_order(graph):
    n = len(graph)
    insort_order = [-1] * n
    degrees = [0] * n
    for i in range(n):
        for j in graph[i]:
            degrees[i] += 1
    queue = [i for i in range(n) if degrees[i] == 0]
    index = 0
    while queue:
        current = queue.pop(0)
        if insort_order[current] == -1:
            insort_order[current] = index
            i = 0
            while i < n:
                index += 1
                if degrees[i] > 0 and insort_order[i] == -1 and graph[i].count(current) == 1:
                    degrees[i] -= 1
                    if degrees[i] == 0:
                        queue.append(i)
                i += 1
    dangling_nodes = [i for i in range(n) if insort_order[i] == -1]
    return insort_order, dangling_nodes, degrees

def solve(intervals):
    graph = [[] for _ in range(len(intervals))]
    for i in range(len(intervals)):
        start_i, end_i = intervals[i]
        for j in range(i + 1, len(intervals)):
            start_j, end_j = intervals[j]
            if start_i < end_j and start_j < end_i:
                graph[i].append(j)
    order, dangling_nodes, degree = find_graph_order(graph)
    overlap = 0
    for i in order:
        if i in dangling_nodes:
            overlap += 1
    return len(intervals) - (len(order) - overlap)
