def left_right_multiply(M1, M2):
    rowsM1 = len(M1)
    colsM2 = len(M2[0])
    assert len(M1[0]) == colsM2, 'Dimensions do not match for left-right multiply'
    result = [[0 for _ in range(colsM2)] for _ in range(rowsM1)]
    for i in range(rowsM1):
        for j in range(colsM2):
            for k in range(len(M1[0])):
                result[i][j] += M1[i][k] * M2[k][j]
    return result

def right_left_multiply(M2, M1):
    colsM2 = len(M2[0])
    assert len(M2) == len(M1), 'Dimensions do not match for right-left multiply'
    result = [[0 for _ in range(len(M1[0]))] for _ in range(colsM2)]
    for i in range(colsM2):
        for j in range(len(M1[0])):
            for k in range(len(M2)):
                result[i][j] += M2[i][k] * M1[k][j]
    return result

