        removed = [v]
        in_degree_reset = []
        for i in range(n):
            if i != v:
                in_degree_reset.append((i, indeg[i]))
        in_degree_reset.sort(key=lambda x: x[1])
        for x, i in in_degree_reset:
            if i == 0 and x not in removed:
                return [x] + remove_vertex(x)
        return removed

