        for i in range(n):
            if available[i] == 0:
                in_degree[i] -= 1
                heappush(queue, i)
            elif available[i] == 2:
                available[i] = 1

        ind = next((i for i in range(n) if available[i] == 1), None)
        if ind is not None:
            heappush(queue, ind)

        if len(queue) != n:
            leak.add(heappop(queue))

        if len(queue) != n:
            break

    order = []
    for i in range(n):
        if available[i] != 0:
            return []

        if i in leak:
