from collections import defaultdict, deque

def solve(n, prerequisites):
    graph = defaultdict(list)
    indegree = [0] * n
    for a, b in prerequisites:
        graph[b].append(a)
        indegree[a] += 1

    que = deque([i for i in range(n) if indegree[i] == 0])
    order = []
    while que:
        v = que.popleft()
        order.append(v)
        for u in graph[v]:
            indegree[u] -= 1
            if indegree[u] == 0:
                que.append(u)

    return [x for x in order if len(graph[x]) > 0]

def longest_path(graph):
    n = len(graph)
    dp = [[-1, 0] for _ in range(n)]
    for i in range(n):
        if dp[i][0] == -1:
            que = deque([i])
            maxdepth = 0
            while que:
                v = que.popleft()
                if dp[v][0] == -1:
                    dp[v][0] = maxdepth
                    dp[v][1] = sum(1 for u in graph[v] if dp[u][0] != -1)
                if dp[v][1]:
                    maxdepth += 1
                    for u in graph[v]:
                        if dp[u][0] == -1:
                            que.append(u)
                else:
                    maxdepth = max(maxdepth, dp[v][0] + 1)
                    for u in graph[v]:
                        if dp[u][0] != -1:
                            maxdepth = max(maxdepth, dp[u][0] + 1)
    maxid = max((dp[i][0] + dp[i][1] for i in range(n)), default=-1)
    result = []
    for i in range(n):
        if dp[i][0] + dp[i][1] == maxid:
            result.append(i)
    return result

def toposort(n, graph):
    if not graph:
        return [x for x in range(n)]
    order = solve(n, graph)
    if not order:
        return []
    for i in range(n):
        if i in order:
            order.remove(i)
            return [i] + toposort(n, {{j for j in graph[i]} - {i} for i in graph})
    return []

def solve(n, prerequisites):
    graph = defaultdict(set)
    for a, b in prerequisites:
        graph[b].add(a)
    forward = toposort(n, graph)
    if not forward:
        return []
    backward = toposort(n, {u for u, vs in graph.items() for v in vs} | {i: {j for j in graph[i]}  for i in range(n)})
    if not backward:
        return []
    forward.reverse()
    graph = defaultdict(set)
    for v in forward:
        for u in backward:
            if v < u:
                graph[u].add(v)
    return longest_path(graph)
