class TopSort:
    def __init__(self, n):
        self.n = n
        self.graph = defaultdict(list)
        self.in_degree = [0] * n
        self.top_sort = []

    def add_edge(self, a, b):
        self.graph[b].append(a)
        self.in_degree[a] += 1

    def solve(self):
        queue = deque([i for i in range(self.n) if self.in_degree[i] == 0])

        while queue:
            node = queue.popleft()
            self.top_sort.append(node)

            for neighbor in self.graph[node]:
                self.in_degree[neighbor] -= 1
                if self.in_degree[neighbor] == 0:
                    queue.append(neighbor)

        return self.top_sort if len(self.top_sort) == self.n else []

def solve(n, prerequisites):
    top_sort = TopSort(n)

    for a, b in prerequisites:
        top_sort.add_edge(b, a)

    return top_sort.solve()
