def swap(intervals, i, j, end_index):
    intervals[i], intervals[j] = intervals[j], intervals[i]
    # To ensure the swapped interval stays in its correct merged group, we rebump its next index
    if j < end_index:
        rebump_next(intervals, j)
    rebump_next(intervals, i)

def rebump_next(intervals, i):
    j = i + 1
    while j < len(intervals) and intervals[j][0] <= intervals[i][1]:
        swap(intervals, i + 1, j, i + 1)
        i += 1
