        else:
            tree.merges.append(node)
        return tree

    def search(self, tree, intervals):
        if not tree:
            return intervals
        to_merge = []
        for i in tree.merges:
            to_merge.append([i.start, i.end])
        new_intervals = self.search(tree.left, intervals + to_merge)
        to_merge = []
        for i in tree.merges:
            new_end = max(new_intervals[-1][1], i.end) if new_intervals else i.end
            to_merge.append([i.start, new_end])
        new_intervals.pop()
        new_intervals.extend(to_merge)
        new_intervals.sort(key=lambda x: x[0])
        return self.shift(new_intervals)

    def shift(self, intervals):
        new_intervals = []
        start, end = intervals[0]
        for i in intervals[1:]:
            if i[0] <= end:
                end = max(end, i[1])
            else:
                new_intervals.append([start, end])
                start = i[0]
                end = i[1]
        if start <= end:
            new_intervals.append([start, end])
        return new_intervals

