class Interval:
    def __init__(self, start, end):
        self.start = start
        self.end = end

    def __eq__(self, other):
        return self.start == other.start and self.end == other.end

    def __lt__(self, other):
        return self.start < other.start

class IntervalTree:
    def __init__(self):
        self.root = None

    def insert(self, node, interval):
        if node is None:
            self.root = IntervalNode(interval)
        elif interval.start < node.interval.end:
            if interval.end > node.interval.end:
                node.right = IntervalNode(interval)
            self.insert(node.right, interval)
        else:
            if interval.start < node.interval.start:
                node.left = IntervalNode(interval)
            self.insert(node.left, interval)

    def search(self, node, interval):
        if node is None:
            return None
        if interval.end < node.interval.start:
            return self.search(node.left, interval)
        if interval.start > node.interval.end:
            return self.search(node.right, interval)
        return node

    def findOverlapping(self, interval):
        overlapping = []
        stack = [self.root]
        while stack:
            node = stack.pop()
            if interval.start <= node.interval.end and interval.end >= node.interval.start:
                overlapping.append(node.interval)
                stack.append(node.left)
                stack.append(node.right)
        return overlapping

def solve(intervals):
