    start = intervals[0][0]
    end = tree.findOverlapping(Interval(0, start))[0].end
    merged = [[start, end]]
    for interval in intervals[1:]:
        overlapping = tree.findOverlapping(Interval(end + 1, interval[1]))
        if overlapping:
            corresponding_start = overlapping[0].start
            if end < corresponding_start:
                end = overlapping[0].end
