    def __init__(self, start, end):
        self.start = start
        self.end = end
        self.left = None
        self.right = None

class IntervalTree:
    def __init__(self, intervals):
        self.root = None
        self.build(intervals)

    def build(self, intervals):
        if not intervals:
            return
        self.root = self._build(0, len(intervals) - 1, intervals)

    def _build(self, low, high, intervals):
        if low == high:
            return Node(intervals[low][0], intervals[low][1])
        mid = (low + high) // 2
        node = Node(intervals[mid][0], intervals[mid][1])
        node.left = self._build(low, mid - 1, intervals)
        node.right = self._build(mid + 1, high, intervals)
        return node

    def _query(self, node, x):
        if node is None:
            return float('inf')
        if node.start == x:
            return node.end
        if node.start < x:
            return max(self._query(node.right, x), node.end)
        return min(self._query(node.left, x), node.end)

    def merge_intervals(self, intervals):
        self.build(intervals)
        result = []
        for interval in intervals:
            start = interval[0]
            end = interval[1]
            prev_end = self._query(self.root, start - 1)
            if prev_end < start:
                result.append([prev_end + 1, start])
            self._update(self.root, start, end)
        # AddingInterval after dismantling the tree
        last = result[-1]
        for val in result[::-1]:
            if val[0] == last[1]:
                last = val
            else:
                break
        result = result[:-len(result)-1][::-1]
        return result

    def _update(self, node, x, y):
        if not node:
            return
        if node.start <= x and node.end >= y:
            node.start = min(node.start, x)
            node.end = max(node.end, y)
        else:
            self._update(node.left, x, y)
            self._update(node.right, x, y)
