class UnionFind:
    def __init__(self):
        self.parent = {}
        self.max_val = {}

    def find(self, key):
        if key not in self.parent:
            self.parent[key] = key
            self.max_val[key] = key
        if self.parent[key] != key:
            self.parent[key] = self.find(self.parent[key])
        return self.parent[key]

    def union(self, key1, key2):
        root1 = self.find(key1)
        root2 = self.find(key2)
        if root1 != root2:
            new_root = max(root1, root2)
            for k, v in self.parent.items():
                if v == root1:
                    self.parent[k] = new_root
                    self.max_val[k] = max(self.max_val[k], key2)
            self.parent[root1] = new_root
            return new_root
        return root1

    def get_max(self, root):
        for k, v in self.max_val.items():
            if k == root:
                return v
        return root


