    uf = UnionFind()
    for i in range(len(intervals)):
        for j in range(i + 1, len(intervals)):
            if intervals[i][1] >= intervals[j][0] or intervals[j][1] >= intervals[i][0]:
                uf.union([i, j])
    parent_to_index = {}
    for i in range(len(intervals)):
        root = uf.find(i)
        if root not in parent_to_index:
            parent_to_index[root] = [i]
        else:
            parent_to_index[root].append(i)
    merged_intervals = []
    for indices in parent_to_index.values():
        start = intervals[indices[0]][0]
        end = uf.get_max(indices[0])
        for index in indices[1:]:
            if intervals[index][1] > end:
                end = uf.get_max(index)
        merged_intervals.append([start, end])
    return merged_intervals
