        for neighbor in [1, -1]:
            left_end = end + neighbor
            if left_end >= 0 and left_end < len(intervals):
                if intervals[end][1] >= intervals[left_end][0]:
                    root = dsu.find(end)
                    left_root = dsu.find(left_end)
                    if root != left_root:
                        parent[left_root] = root
                        dsu.union(root, left_root)

    parents = {end: dsu.find(end) for end in range(len(intervals))}
    result = []
    for start, end in intervals:
        root = parents[end]
        in_list = False
        for i, entry in enumerate(result):
            entry_root = parents[result[i][1]]
            if entry_root == root:
                if entry[0] <= start <= entry[1]:
                    start = entry[0]
                else:
                    result[i] = [entry[0], max(entry[1], start),]
                in_list = True
                break
        if not in_list:
            result.append([start, end])

