            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        xr, yr = self.find(x), self.find(y)
        if xr != yr:
            if self.rank[xr] < self.rank[yr]:
                xr, yr = yr, xr
            if self.rank[xr] == self.rank[yr]:
                self.rank[xr] += 1
            self.parent[yr] = xr


def solve(intervals):
    n = len(intervals)
    starts = sorted((start, end, i) for i, (start, end) in enumerate(intervals))
    ends = sorted((end, -start, i) for i, (start, end) in enumerate(intervals))
    uf = UnionFind(n)

    ans = []
    outbreaks = []

    for _, start_rank in starts:
        while outbreaks and outbreaks[-1][0] <= start_rank:
            start_i = outbreaks.pop()[1]
            end_i = uf.find(start_i)
            if end_i not in uf.parent or uf.rank[end_i] == 0:
                ans.append((intervals[start_i][0], intervals[start_i][1]))
                uf.rank[end_i] = 0
            else:
                outbreaks.append((end_i, uf.find(end_i)))
        if start_rank not in uf.parent or uf.rank[start_rank] == 0:
            oend = None
            for _, e_rank in ends:
                if e_rank == start_rank:
                    oend = max(intervals[start_rank][1], intervals[uf.find(e_rank)][1])
                    break
            if oend == None:
                outbreaks.append((start_rank, start_rank))
            else:
                uf.union(start_rank, oend)
                ans.append((intervals[start_rank][0], oend))
            uf.rank[start_rank] = 0
        else:
            for end_rank, _, end_i in endpoints:
                if uf.find(start_rank) == end_i:
                    uf.union(end_rank, start_rank)
    uf.parent = sorted(range(n), key=lambda x: uf.rank[uf.find(x)])
    return [(intervals[i][0], intervals[i][1]) for i in uf.parent]
