import heapq
from typing import List

def solve(nums: List[int], k: int) -> int:
    """Returns the k-th smallest value in the given list of integers."""
    count = {}
    for num in nums:
        count[num] = count.get(num, 0) + 1

    heap = [(-(count[num]) if count[num] > 1 else -1, num) for num in count]
    heapq.heapify(heap)

    while heap[0][0] == -1:
        heapq.heappop(heap)

    for _ in range(k-1):
        heapq.heappop(heap)

    return heap[0][1]
