    i = j = 0
    while i < len(load1) or j < len(load2):
        while i < len(load1) and (j == len(load2) or list(load1.items())[i][0] < list(load2.items())[j][0]):
            q.append(list(load1.items())[i])
            i += 1
        while j < len(load2) and (i == len(load1) or list(load2.items())[j][0] <= list(load1.items())[i][0]):
            q.append(list(load2.items())[j])
            j += 1
        if q:
            key, value = q.pop(0)
            load3[key] = load3.get(key, 0) + value
    return load3

def select(load, k):
    i = 0
    j = 0
    while True:
        key1, value1 = list(load.items())[i]
        i += 1
        while i < len(load) and list(load.items())[i][1] == value1:
            key2, value2 = list(load.items())[i]
            i += 1
            value1 += value2
        if value1 + j >= k:
            parts = k - (value1 + j - value2)
            if value2 == 1:
                return key1
            if parts % value2 == 0:
                return key1 + (parts // value2 - 1)
            return key1 + (parts // value2)

