        median_key = 0
        for _ in range(random.randint(1, 5)):
            midterm = random.uniform(lower, upper)
            midterm_key = int(midterm)
            are_records_equal &= midterm_key in load
            if are_records_equal and random.random() < (load[midterm_key] / n):
                median_key = midterm_key
        new_load = {}
