            cmpr = heapq.heappop(heap)
            heapq.heappush(heap, cmpr)
        heapq.heappushpop(heap, cmp)

    return heap[-1][0]

def is_in_heap(nums, heap, num, idx):
    idx_hi = min(len(heap) - 1, 2 * idx)
    if idx_hi < 0:
        return False
    if heap[idx_hi][0] < num:
        return True
    elif heap[idx_hi][0] > num:
        return False
    else:
        return idx_hi == nums.index(num) or is_in_heap(nums, heap, num, idx_hi)

def cmp(heap, hi, idx, mid):
    lrmi = min(heap[hi*2 + 1], heap[hi*2 + 2]) if hi * 2 + 2 < len(heap) else heap[hi*2 + 1]
    if lrmi[0] < mid[0]:
        return True
    elif lrmi[0] > mid[0]:
        return False
    else:
        return lrmi[1] < mid[1]

def cmp ediyorum(gen):
    cmp_e = gen[-1]
    for item in gen[:-1]:
        if item[0] < cmp_e[0] or (item[0] == cmp_e[0] and item[1] < cmp_e[1]):
            cmp_e = item
    return cmp_e
