import bisect

def solve(nums, k):
    min_val, max_val = min(nums), max(nums)
    bucket_size = (max_val - min_val) // (k - 1) if k > 1 else 1

    def bucketed_insert(x):
        return (x - min_val) // bucket_size

    buckets = []
    for x in nums:
        i = bisect.bisect_right([y for _, y in buckets], bucketed_insert(x))
        buckets.insert(i, (-len(buckets), x))

    buckets.sort()
    return min(x for _, x in buckets[:k])

def bisect_right(a, x):
    lo, hi = -1, len(a)
    while lo + 1 < hi:
        mid = (lo + hi) // 2
        if a[mid][0] <= x:
            lo = mid
        else:
            hi = mid
    return hi

def min_or_max(a):
