def find_second_largest(nums):
    max_heap = []
    cnt_heap = []
    for num in nums:
        if not max_heap or num > max_heap[0]:
            heapq.heappush(max_heap, num)
            while len(max_heap) > 1 and max_heap[0] == max_heap[1]:
                heapq.heappop(max_heap)
                heapq.heappop(cnt_heap)
                heapq.heappush(cnt_heap, 1)
            heapq.heappush(cnt_heap, 1)
        else:
            heapq.heappush(cnt_heap, max_heap[0])
            if cnt_heap[0] < k - 2:
                heapq.heappop(cnt_heap)
                heapq.heappush(cnt_heap, 1)
    return max_heap[0]

def find_k(nums, **bottom_k_heap_finders):
    def __find_k_heap(nums, k):
        max_heap = []
        cnt_heap = []
        for num in nums:
            if len(max_heap) < k:
                heapq.heappush(max_heap, num)
                heapq.heappush(cnt_heap, 1)
            else:
                heapq.heappush(cnt_heap, num)
                if cnt_heap[0] < k:
                    heapq.heappushpop(cnt_heap, 1)
                elif cnt_heap[0] > 2 * k:
