                    heapq.heappush(cnt_heap, max_heap[0])
        return max_heap[0]
    return bottom_k_heap_finders['find_largest' if k == len(nums)](
            [__find_k_heap(nums, j)+i for i in range(len(nums)) for j in range(k-1)])


