            return nums[left]
        p_idx = partition(left, right)
        if k - 1 == p_idx - left:
            return nums[p_idx]
        elif k - 1 < p_idx - left:
            return quickselect(left, p_idx - 1)
        else:
            return quickselect(p_idx + 1, right)

