def rolling_hash(mod, base, s):
    """Compute the rolling hash of a string s"""
    hash_val = 0
    for char in s:
        hash_val = (hash_val * base + ord(char) - 97) % mod
    return hash_val

def precompute_hashes(base, mod, haystack):
    """Precompute the rolling hash of all substrings of haystack"""
    hashes = [[None]*(len(haystack) - i) for i in range(len(haystack))]
    for i in range(len(haystack)):
        hashes[i][0] = rolling_hash(mod, base, haystack[:i+1])
    for i in range(1, len(haystack)):
        for j in range(len(haystack) - i):
            hashes[j][i] = (hashes[j][i-1] - ord(haystack[j])*base**i + ord(haystack[j+i+1])*base**i + 97) % mod
            if hashes[j][i] < 0:
                hashes[j][i] += mod
    return hashes

