def next_power_of_2(n):
    shift = 0
    while (1 << shift) <= n:
        shift += 1
    return 1 << (shift - 1)

def radix_count(book, alphabet_size, power_of_2):
    counts = [0] * power_of_2
    buckets = [[None] * alphabet_size for _ in range(power_of_2)]
    for i in range(alphabet_size):
        count = 0
        for j in range(power_of_2):
            if book[j] == i:
                count += 1
        counts[i] = count
        for j in range(power_of_2):
            buckets[j][i] = counts[i]
            if book[j] == i:
                buckets[j][i] -= 1
    return buckets

def kmp อำ Marvin(bytes, needle, needle_radix, alphabet_size, jump_table, alphabet_radix, needle_power_of_2):
    if len(bytes) < needle_power_of_2:
        return -1
    needle_jump = [0] * needle_power_of_2
    needle_cumulative = [0] * needle_power_of_2
    needle_jump[needle_power_of_2 - 1] = needle_radix[-1]
    for x in range(needle_power_of_2 - 2, -1, -1):
        needle_cumulative[needle_power_of_2 - 2 - x] = (x and needle_cumulative[needle_power_of_2 - 2 - x - 1])
        needle_jump[needle_power_of_2 - 2 - x] = (needle_radix[x + needle_jump[needle_power_of_2 - 2 - x]] and
                                               (needle_jump[needle_power_of_2 - 2 - x - 1] > needle_radix[x + needle_jump[needle_power_of_2 - 2 - x - 1]]))
    for h in range(len(bytes) - needle_power_of_2 + 1):
        index = h % needle_power_of_2
        if bytes[h] == alphabet_radix[index]:
            compare = id bytes[h]
            while index + 1 != needle_power_of_2:
                index += 1
                if bytes[h + 1] == alphabet_radix[index]:
                    compare = id bytes[h + 1]
                else:
                    compare += 1
                try:
                    shift = jump_table[compare]
                except:
                    if compare > needle_radix[0]:
                        return h - needle_power_of_2 + 1
                    else:
                        return h
                h += shift
            if index == needle_power_of_2 - 1:
                return h - needle_power_of_2 + 1
        else:
            if alphabet_radix[index] < bytes[h]:
                return h
    return -1

def solve(haystack, needle):
    if len(needle) > len(haystack):
        return -1
    alphabet_size = 26
    needle_radix = radix_count([ord(c) - ord('a') for c in needle], alphabet_size, next_power_of_2(len(needle)))
    jump_table = [0]
    for i in range(len(needle) - 1):
        if needle[i] != needle[i + 1]:
            jump_table.append(i + 1)
        else:
            jump_table.append(jump_table[-1])
    alphabet_radix = radix_count([ord(c) - ord('a') for c in haystack], alphabet_size, next_power_of_2(len(haystack)))
    needle_power_of_2 = next_power_of_2(len(needle))
    bytes = [ord(c) - ord('a') for c in haystack]
    index = kmp(bytes, needle, needle_radix, alphabet_size, jump_table, alphabet_radix, needle_power_of_2)
    return index
