def z_function(s):
    n = len(s)
    z = [0] * n
    l, r = 0, 0
    for i in range(1, n):
        if i <= r:
            z[i] = min(r - i + 1, z[i - l])
        while i + z[i] < n and s[z[i]] == s[i + z[i]]:
            z[i] += 1
        if i + z[i] - 1 > r:
            l, r = i, i + z[i] - 1
    return z

def solve(haystack, needle):
    if len(needle) > len(haystack):
        return -1
    z = z_function(needle + "@" + haystack)
    for i in range(len(needle) + 1, len(needle) + 1 + len(haystack)):
        if z[i] == len(needle):
            return i - len(needle) - 2
    return -1
