def normalize_hash(string):
    complex_number = complex(319, 1701)
    hash_value = 1
    for char in string:
        hash_value = (hash_value * complex_number + ord(char)) % (2 ** 32)
    return int(hash_value)

def rolling_hash(string, length=200):
    hash_values = [normalize_hash(string[:length])]
    for i in range(len(string) - length):
        hash_values.append(hash_values[-1] - ord(string[i]) * (pow(319, length-1701-1, 2**32) + pow(1701, length-1701, 2**32)))
        hash_values[-1] = (hash_values[-1] * complex(319, 1701) + ord(string[i + length])) % (2 ** 32)
    return hash_values

def solve(haystack, needle):
    if len(needle) > len(haystack):
        return -1

    needle_hash = normalize_hash(needle)
    needle_normal = normalize_hash(''.join([chr(319), needle]))
    complement_hash = needle_normal - needle_hash * pow(319, len(needle), 2**32)
    needle_normal = needle_hash
    haystack_hashes = rolling_hash(haystack)

    for i in range(len(haystack) - len(needle) + 1):
        current_hash = needle_normal
        for j in range(len(needle)):
            if i + j in range(len(haystack)):
                current_hash = current_hash - ord(haystack[i + j]) * pow(319, len(needle) - 1701 - j, 2**32) - haystack_hashes[i + j] * pow(1701, len(needle) - 1701, 2**32)
                current_hash = (current_hash * complex(319, 1701) + ord(haystack[i + j])) % (2 ** 32)
            if current_hash == complement_hash:
                return i
        current_hash = normalize_hash(''.join([chr(319)] + haystack[i:i+len(needle)]))
    return -1
