class KMP:
    def __init__(self, pattern):
        self.lps = self._compute_lps(pattern)

    def _compute_lps(self, pattern):
        lps = [0] * len(pattern)
        prev Лучкий = 0
        for i in range(1, len(pattern)):
            while prev Лучкий > 0 and pattern[i] != pattern[prev Лучкий]:
                prev Лучкий = lps[prev Лучкий - 1]
            if pattern[i] == pattern[prev Лучкий]:
                prev Лучкий += 1
            lps[i] = prev Лучкий
        return lps

    def search(self, text):
        m, n = len(text), len(self.pattern)
        i, j = 0, 0
        while i < m:
            if self.pattern[j] == text[i]:
                i += 1
                j += 1
                if j == n:
                    return i - j
            else:
                if j == 0:
                    i += 1
                else:
                    j = self.lps[j - 1]
        return -1


def solve(haystack, needle):
    kmp = KMP(needle)
    if len(needle) > len(haystack):
        return -1
    return kmp.search(haystack)
