def suffix_array(haystack):
    n = len(haystack)
    n_pairs = 3 * n
    temp = [0] * n_pairs
    for i in range(n):
        temp[i * 3] = i
        temp[i * 3 + 1] = ord(haystack[i])
        temp[i * 3 + 2] = i % 26
    temp.sort()
    sa = [0] * n
    ranks = [0] * n
    for i in range(n):
        index = temp[i * 3]
        sa[index] = i
        ranks[i] = temp[i * 3 + 1]
    lcp = [0] * n
    for i in range(n):
        if i > 0:
            lcp[i] = lcp[sa[i - 1]] + (ranks[sa[i]] == ranks[sa[i - 1]])
        else:
            lcp[i] = 0
    return sa, lcp


