        return -1

    z = z_algorithm(needle + '$' + haystack)  # Append sentinel to avoid edge case
    for i in range(len(needle) + 1, len(z)):
        if z[i] == len(needle):
            return i - len(needle) - 2  # Subtract 2 to adjust for sentinel
    return -1
