            if(char_classes[haystack[i-1]] == 2 and char_classes[haystack[i-1]] != rolling_class):
                rolling_class = 0
                for c in char_classes:
                    if char_classes[c] == 1:
                        rolling_class = c
        if i >= m:
            c = haystack[i - m]
            rolling_hash[i] = (rolling_hash[i - 1] + offset(ord(c) - 96, rolling_hash[i - m]) ) % U
            a = rolling_hash[i] - offset(ord(c) - 96, hash[m])
            a %= U
            a += U if a < 0 else 0
            if a == hash[m + 1]:
                return i - m
        if i >= m:
