def solve(haystack: str, needle: str) -> int:
    def precompute(leftmost_start_index: int) -> tuple[int, int, int]:
        """Return the window offset, next overlap position, and pattern shift for the given leftmost start index."""
        window_offset = len(needle) - (haystack[leftmost_start_index:].find(needle) + 1)
        next_overlap_pos = leftmost_start_index
        pattern_shift = leftmost_start_index
        return window_offset, next_overlap_pos, pattern_shift

    def rolling_hashes() -> list[tuple[int, int, int]]:
        """Return a list of tuples containing the window offset, next overlap position, and pattern shift for each starting position in the haystack."""
        window_offsets = []
        next_overlaps = []
        patterns_shifted = []
        for i in range(len(haystack)):
            if i < len(needle):
                _, _, pattern = precompute(i)
                window_offsets.append(-1)
                next_overlaps.append(-1)
                patterns_shifted.append(pattern)
            else:
                window_offset, next_overlap, pattern = precompute(i - len(needle) + 1)
                window_offsets.append(window_offset)
                next_overlaps.append(next_overlap)
                patterns_shifted.append(pattern)
        return window_offsets, next_overlaps, patterns_shifted

    window_offsets, next_overlaps, patterns_shifted = rolling_hashes()

    def rolling_hashes_offset(window_offset: int) -> int:
        """Return the first position at which needle occurs in haystack offset by the given window offset."""
        if window_offset == -1:
            return -1
        next_overlap = next_overlaps[window_offset]
        pattern = patterns_shifted[window_offset]
        if haystack[window_offset:pattern+len(needle)].startswith(needle):
            return next_overlap
        return -1

    for i in range(0, len(haystack) - len(needle) + 1):
        if haystack[i:i+len(needle)] == needle:
            return i
        next_overlap_pos = i
        while next_overlap_pos <= len(haystack) - len(needle):
            next_overlap_pos = rolling_hashes_offset(next_overlap_pos + len(needle))
            if next_overlap_pos == -1:
                break
            if haystack[next_overlap_pos:next_overlap_pos+len(needle)] == needle and haystack[next_overlap_pos-len(needle):next_overlap_pos].startswith(needle):
                return next_overlap_pos-len(needle)
    return -1
