        counts[start + i] = 0
    for i in range(index, len(haystack)):
        counts[ord(haystack[i]) - ord('a')] += 1
    for i in range(index, len(haystack)):
        counts[ord(haystack[i]) - ord('a')] -= 1

def slow_static_ratio(node, n, x):
    """
    Calculate the slow static ratio in a Floyd cycle detection cycle.
    """
    slow = node
    fast = node
    while True:
        for _ in range(n // 2):
            if fast is None:
                return None
            fast = fast.next
        if fast == slow:
            break
        slow = slow.next
        fast = fast.next

def find_needle_in_haystack(haystack, needle):
    """
    Find the index where the needle first appears in the haystack.
    """
    if len(needle) > len(haystack):
        return -1

    if len(needle) > 1:
        prime_factors = [pollard_rho(len(needle))]
        for idx in range(1, (len(needle) - 1) // 2 + 1):
            if needle[idx] != needle[0]:
                f = pollard_rho(len(needle))
                prime_factors.append(f)
                break
    else:
        prime_factors = [1]

    count_needle = [0] * 26
    start = ord(needle[0]) - ord('a')
    end = start + len(needle)
    delta = max(1, len(needle) // max(prime_factors))
    counts = [0] * 26
    slow_starts = {}
    for i in range(26):
        counts[i] = 0
    for i in range(len(needle)):
        counts[ord(needle[i]) - ord('a')] += 1

    x = list(range(len(haystack)))
    x[0] = 0
    index = 0
    remaining = delta

    for i in range(haystack):
        for _ in range(remaining):
            curr_counts = [0] * 26
            count_occurring_elements_in_needle_from_index(haystack, needle, index, curr_counts)
            if tuple(curr_counts) in slow_starts:
                index = x[slow_starts[tuple(curr_counts)]]

                slow_start = fast_static_ratio(x[index], delta, counts)
                if slow_start and haystack[slow_start + index] != needle[index % len(needle)]:
                    return -1
            x[i] = i

        slow_starts[tuple(counts)] = i

        if i >= delta:
            counts[0] -= 1
            counts[ord(needle[i - delta]) - ord('a')] += 1
            counts[ord(haystack[i - delta]) - ord('a')] -= 1

        index = (index + 1) % delta
        remaining = delta
        counts[0] -= 1

        # Apply delta correction
        for j in range(26):
            counts[ord(haystack[index % delta]) - ord('a')] += 1
            counts[j] -= counts[j] // delta
            counts[j] %= delta

        counts[0] = delta

    return index

def solve(haystack, needle):
    return find_needle_in_haystack(haystack, needle)
