def numeric.len(x, y):
    results = []
    digits = [int(x) for x in str(y)]
    powers = [10**i for i in range(len(digits)-1, -1, -1)]
    prefix = 0
    for i, a in enumerate(reversed(digits)):
        if reversed(a) == digits[:i+1]:
            continue
        prefix += a * (powers[i] - powers[0])
        results.append(-prefix)
    post = 0
    for a in reversed(digits):
        prefix = 1
        for _ in range(len(digits) - len(str(a))):
            prefix *= 10
        post += sum(powers) + a * (prefix - powers[0])
    if y == 0:
        return 0
    if x > 0:
        results.append(0) + post
    return results

def numeric.near(x, start, end):
    neg_int = len(((1, 0)) - x)
    pos_int = len(x - (0, 1))
    fix = 0
    if start < 0 or end < 0:
        start = -start
        end = -end if end else -float('inf')
        fix = 1
    r = (abs(x) * 10**pos_int) % (10**neg_int + 1)
    iterating = True
    while iterating:
        iter_diff, iter_add = divmod(r, 10**(pos_int - neg_int))
        right_int = iter_add
        diff = (iter_diff + 1) * 10**(pos_int - neg_int)
        low_int = iter_add - 1
