class PairTracker:
    def __init__(self):
        self.diff_store = [10**9]
        self.diff_to_index = {}

    def add_diff(self, i, diff):
        j = bisect.bisect_left(self.diff_store, diff)
        end = len(self.diff_store)
        if j != end and diff == self.diff_store[j]:
            j = insort_right(self.diff_store, diff)
        else:
            insort(self.diff_store, diff)
        old_j = self.diff_to_index.get(diff, -1)
        if old_j != -1:
            self.diff_to_index[diff] = i
        self.diff_to_index[diff] = j

def solve(nums, target):
    diff_tracker = PairTracker()
    num_tracker = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in num_tracker:
            return [num_tracker[complement], i]
        diff_tracker.add_diff(i, complement)
        num_tracker[num] = i

    raise Exception('No solution found')
