def _sort_and_search(nums, left, right, target):
    if left == right:
        return left
    mid = (left + right) // 2
    if nums[left] + nums[mid] <= target:
        right_thumb = mid
        left_thumb = left
    else:
        right_thumb = right
        left_thumb = mid + 1
    while left <= right:
        found = right_thumb - left + 1
        while left < left_thumb and nums[left] + nums[left_thumb] < target:
            left += 1
            found -= 1
        if found == 0:
            return left
        right_thumb -= 1
        right -= found
    return left + 1

def solve(nums, target):
    if len(nums) == 2:
        return [0, 1]
    left = 0
    right = len(nums) - 1
    while left < right:
        added = nums[left] + nums[right]
        if added < target:
            left = _sort_and_search(nums, left + 1, right, target)
        elif added > target:
            right = _sort_and_search(nums, left, right - 1, target)
        else:
            return [left, right]
    return [left, _sort_and_search(nums, left, left, target)]
