def solve(nums, target):
    def get_right(nums, i, target):
        lo, hi = i + 1, len(nums) - 1
        while lo <= hi:
            mid = (lo + hi) // 2
            if nums[mid] == target - nums[i]:
                if mid > i:
                    return (mid, True)
                lo = mid + 1
            elif nums[mid] < target - nums[i]:
                lo = mid + 1
            else:
                hi = mid - 1
        return (-1, False)

    def get_left(nums, i, target):
        lo, hi = 0, i - 1
        while lo <= hi:
            mid = (lo + hi) // 2
            if nums[mid] == target - nums[i]:
                if mid < i - 1:
                    return (mid, True)
                hi = mid - 1
            elif nums[mid] < target - nums[i]:
                lo = mid + 1
            else:
                hi = mid - 1
        return (-1, False)

    i = 0
    while i < len(nums):
        _, exists_right = get_right(nums, i, target)
        if exists_right:
            break
        _, exists_left = get_left(nums, i, target)
        if exists_left:
            break
        i += 1
    if i == len(nums):
        return (-1, -1)
    left_i, left_exists = get_left(nums, i, target)
    if left_exists:
        return ((left_i, i) if left_i < i else (i, left_i))
    right_j, right_exists = get_right(nums, i, target)
    if right_exists:
        return ((i, right_j) if i < right_j else (right_j, i))
