def solve(nums, target):
    positives = []
    negatives = []
    zeros = [-float('inf')] * 2

    for i, x in enumerate(nums):
        if x == 0:
            zeros[(i + 1) % 2] = i
        elif x < 0:
            negatives.append((x, i))
            negatives.sort()
        else:
            positives.append((x, i))
            positives.sort(reverse=True)

