        x1, i1 = negatives.pop()
        x2, i2 = positives.pop()

        if x1 + x2 == target:
            return i1, i2

    while positives and positives[-1][0] == positives[0][0]:
        positives.pop()

    while negatives and negatives[-1][0] == negatives[0][0]:
        negatives.pop()

    complements = {}
    for x, i in positives:
        x = -x
        if x in complements:
            return complements[x], i
        complements[x] = i
    return min((j, i1) for x, i in negatives for i1, j in (complements.get(-x), i) if j is not None)
