class NumSequencer:
    def __init__(self, nums):
        self.nums = nums
        self.diff_set = set()

    def solve(self, target):
        self.build_diff_set()
        left, right = 0, 0
        while right < len(self.nums):
            diff = target - self.nums[right]
            if diff in self.diff_set:
                result = (self.nums.index(diff, left, right + 1), right)
                return result
            self.diff_set.add(self.nums[right])
            right += 1
        return None

    def build_diff_set(self):
        self.diff_set.add(self.nums[0])
        for i in range(1, len(self.nums)):
            self.diff_set.add(self.nums[i] - self.nums[i-1])

def solve(nums, target):
    sequencer = NumSequencer(nums)
    result = sequencer.solve(target)
    if result is None:
        raise ValueError("No solution found")
    return result
