class UnionFind:
    def __init__(self, n):
        self.root = [-1] * n
        self.count = n

    def find(self, x):
        if self.root[x] < 0:
            return x
        self.root[x] = self.find(self.root[x])
        return self.root[x]

    def union(self, x, y):
        root_x = self.find(x)
        root_y = self.find(y)
        if root_x != root_y:
            if self.root[root_x] > self.root[root_y]:
                root_x, root_y = root_y, root_x
            self.root[root_x] += self.root[root_y]
            self.root[root_y] = root_x
            self.count -= 1


def solve(n, edges):
