class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        xr, yr = self.find(x), self.find(y)
        if xr == yr:
            return False
        if self.rank[xr] < self.rank[yr]: xr, yr = yr, xr
        if self.rank[xr] == self.rank[yr]: self.rank[xr] += 1
        self.parent[yr] = xr
        return True

def solve(n, edges):
    dsu = DSU(n)
    for u, v in edges:
        if dsu.union(u, v): n -= 1
