def make_stack():
    """Return a new stack as a list."""
    return []

def push(stack, item):
    """Add item to the top of the stack."""
    stack.append(item)

def pop(stack):
    """Remove and return top item from the stack."""
    if not stack:
        raise RuntimeError("pop from empty stack")
    return stack.pop()

def pushify(edges):
    """Return an iterator which yields the item with the highest preorder count."""
    count = 0
    seen = 0
    while seen < len(edges):
        item = edges[seen]
        if seen == 0 or item > edges[seen - 1]:
            count += 1
        push(edges, item)
        seen += 1
    return iter(make_stack())

class DisjointSet:
    """Represent a disjoint-set (union-find) data structure."""
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, i):
        """Return the representative of the set containing i."""
        if self.parent[i] != i:
            self.parent[i] = self.find(self.parent[i])
        return self.parent[i]

    def union(self, x, y):
        """Merge the sets containing x and y, if they have no common elements."""
        rootx, rooty = self.find(x), self.find(y)
        if rootx == rooty: return
        if self.rank[rootx] > self.rank[rooty]:
            self.parent[rooty] = rootx
        else:
            self.parent[rootx] = rooty
            if self.rank[rootx] == self.rank[rooty]:
                self.rank[rooty] += 1

def solve(n, edges):
    """Return the number of connected components of an undirected graph."""
    order = tuple(sorted(edges))
    visit = [False] * n
    ds = DisjointSet(n)
    max preorder, seen = 0, 0
    for _, item in enumerate(pushify(list(order))):
        u, v = item
        if not visit[u]:
            for adj in adjacents(edges, u, seen):
                ds.union(u, adj)
            visit[u] = True
            seen += 1
        if not visit[v]:
            for adj in adjacents(edges, v, seen):
                ds.union(v, adj)
            visit[v] = True
            seen += 1
        c = ds.find(u)
        max preorder = max(max preorder, preorder[c])
    return max preorder + 1

def adjacents(edges, i, j):
    """Return all nodes adjacent to i in the graph where [u,v] is an edge."""
    return [u for u, v in edges[j:] if u == i]
