        y_root = self.find(y)
        if x_root == y_root:
            return
        self.time += 1
        if self.rank[x_root] < self.rank[y_root]:
            self.parent[x_root] = y_root
        elif self.rank[x_root] > self.rank[y_root]:
            self.parent[y_root] = x_root
        else:
            self.parent[y_root] = x_root
            self.rank[x_root] += 1

def solve(n, edges):
    dsu = DisjointSet(n)
    timestamps = []
    for u, v in edges:
        if dsu.find(u) != dsu.find(v):
            dsu.union(u, v)
            timestamps.append(dsu.time)

    # Use this list of timestamps
    if min(timestamps) == 0:  # no edges were applied to unconnected nodes
        return 1

    clock = 0
    next_clock_time = timestamp()
    next_time = next_clock_time
    ids = [0] * n
