        if max(ids[u], ids[v]) > clock:
            clock = max(ids[u], ids[v]) + 1
        ids[u] = clock
        ids[v] = clock

    return sum(1 for value in ids if value == 0) + sum(1 for value in ids if value > clock) + 1
