            if rank[root1] > rank[root2]:
                parent[root2] = root1
            else:
                parent[root1] = root2
                if rank[root1] == rank[root2]:
                    rank[root2] += 1

    # Construct an adjacency list by initializing graphs as empty lists
    graph = [[] for _ in range(n)]

    # Add edges to the graph
    for edge in edges:
        graph[edge[0]].append(edge[1])
        graph[edge[1]].append(edge[0])  # Undirected graph

    # Perform union-find on all adjacent nodes in each connected component
    # A parent[x] != x implies the nodes in the set with x as parent form a component.
    visited = [False] * n
    components = n
    for node in range(n):
