            self.count = 1
            self.left = None
            self.right = None

    def add_tree(root, val, is_left):
        if root.val > val:
            root.val = val
            root.count, root.left, root.right = 1, None, None
        elif is_left and root.count == 1 and root.right is not None:
            root.val = val
            root.left = root.right
            root.right = None
            root.count += 1
        elif not is_left and root.count == 1 and root.left is not None:
            root.val = val
            root.right = root.left
            root.left = None
            root.count += 1
        elif is_left and root.count > 1:
            if root.left is None:
                root.left = Node(val)
                root.count += 1
            else:
                add_tree(root.left, val, True)
        else:
            if root.right is None:
                root.right = Node(val)
                root.count += 1
            else:
                add_tree(root.right, val, False)
        return root

    def remove_tree(root, val):
        if root is None:
            return root
        if root.val > val:
            root.left = remove_tree(root.left, val)
        elif root.val < val:
            root.right = remove_tree(root.right, val)
        elif root.count == 2 and root.right is not None and root.left is not None:
            return root.left
        elif root.count == 2:
            return root.right
        elif root.val == val:
            root.count -= 1
        return root

