            heapq.heappush(pq1, [intersect[1], intersect[0]])
        elif pq1 and pq2:
            intersect = pair_intersect(pq2, pq1[0][1])
            if intersect and intersect >= pq1[0]:
                heapq.heappush(pq2, [intersect[1], intersect[0]])
        else:
