    for i in range(1, n):
        for j in range(n * i):
            d = j // i
            if d < n and I[j] == 0:
                g[i] += g[d]
                g[i] += f[d]
        for j in range(n * (i - 1), n * i):
            if I[j] == 0:
                g[i] += 1
            d = j // (i - 1)
            if d < n:
                f[i] += f[d]

    return n - g[-1]
