def solve(intervals):
    def fenwick_tree(n):
        """Construct a Fenwick tree of size n"""
        tree = [0] * (n + 1)
        return tree

    def fenwick_tree_update(tree, idx, val):
        """Update the Fenwick tree by adding val at idx"""
        while idx < len(tree):
            tree[idx] += val
            idx += idx & -idx

    def fenwick_tree_query(tree, idx):
        """Query the Fenwick tree for the prefix sum at idx"""
        total = 0
        while idx > 0:
            total += tree[idx]
            idx -= idx & -idx
        return total

    def fenwick_tree_range_query(tree, l, r):
        """Query the Fenwick tree for the range sum [l, r]"""
        return fenwick_tree_query(tree, r + 1) - fenwick_tree_query(tree, l)

    intervals.sort(key=lambda x: x[0])
    n = len(intervals)
    ends = [interval[1] for interval in intervals]
    max_end = max(ends)

    # Construct a Fenwick tree to maintain the maximum value in each interval
    max_tree = fenwick_tree(max_end)
    for start, end in intervals:
        max_tree_update = fenwick_tree_update(max_tree, end, 1)

    # Main dynamic programming loop
    dp = [0] * (max_end + 1)
    for end in ends:
        # Find the number of intervals that end before the current interval
        prefix_sum = fenwick_tree_range_query(max_tree, 1, end - 1)
        dp[end] = max(dp[end - 1] + 1, prefix_sum)

    return max(dp)

def build_segments(intervals):
    segments = []
    sorted_intervals = sorted([(end, start) for start, end in intervals])
    active = []
    for end, start in sorted_intervals:
        for a in active:
            if a[1] >= start:
                a[1] = end
                break
        else:
            active.append([end, start])
        segments.append(active)
    return segments

def merge_segments(segments):
    new_segments = []
    min_end = float('-inf')
    for s in segments:
        if not s:
            continue
        curr_min, curr_max = s[0]
        if curr_min <= min_end:
            if curr_max > min_end:
                new_segments.pop()
                new_segments.append([curr_min, curr_max])
        else:
            if curr_max > min_end:
                new_segments.append([curr_max, curr_max])
            new_segments.append([curr_min, curr_min])
            min_end = curr_min
    return new_segments
