    j = 1
    prev_merged = -1
    end_merged = -1

    while i < size:
        if j == i + 1:
            j += 1
            i += 1
        else:
            if i == prev_merged + 1:
                end_merged = max([end_merged, intervals[i][1]])
                i += 1
                if i == j and end_merged <= intervals[j][0]:
