def phi():
    """Calculate the golden ratio"""
    return (1 + 5**0.5) / 2


def psi():
    """Calculate the conjugate of the golden ratio"""
    return (1 - 5**0.5) / 2


def psi_plus_phi():
    """Calculate the sum of the golden ratio and its conjugate"""
    return 1


def matsukuma_solve(n, phi, psi_plus_phi):
    """Matsukuma's formula for the nth Fibonacci number"""
    x = 1
    y = 0
    a_1 = 1
    a_2 = phi
    b_1 = 0
    b_2 = 1
    for _ in range(1, n + 1):
        if _ % 2:
            x = (a_1 * x + b_1 * y) % (psi_plus_phi ** (n - 1))
        else:
            y = (a_2 * x + b_2 * y) % (psi_plus_phi ** (n - 1))
        a_1, a_2 = (a_2, a_1 - a_2)
        b_1, b_2 = (b_2, b_1 - b_2)
    return int(x)


def solve(n):
