class TopologicalSort:
    def __init__(self, n):
        self.adj_list = [[] for _ in range(n)]
        self.in_vertices = [0] * n

    def add_edge(self, u, v):
        self.adj_list[u].append(v)
        self.in_vertices[v] += 1

    def bfs(self, start):
        queue = deque()
        queue.append(start)
        res = []

        while queue:
            vertex = queue.popleft()
            res.append(vertex)
            for neighbor in self.adj_list[vertex]:
                self.in_vertices[neighbor] -= 1
                if self.in_vertices[neighbor] == 0:
                    queue.append(neighbor)

        return res

def solve(n, prerequisites):
    graph = TopologicalSort(n)

    for x, y in prerequisites:
        graph.add_edge(y, x)

    res = graph.bfs(0)

    if len(res) == n:
        return res
    else:
        return []
