def min_heapify(arr, i, n):
    smallest = i
    left_child = 2 * i + 1
    right_child = 2 * i + 2
    if left_child < n and arr[left_child][1] < arr[smallest][1]:
        smallest = left_child
    if right_child < n and arr[right_child][1] < arr[smallest][1]:
        smallest = right_child
