        parent[x] = -1

    for x in range(n):
        dfs(x)
    if len(topological_order) == n:
        return topological_order

    graph = [[] for _ in range(n)]
    indegree = [0] * n
    for x, y in prerequisites:
        graph[y].append(x)
        indegree[x] += 1

    heap = [(indegree[i], i) for i in range(n)]
    heapq.heapify(heap)

    if indegree.count(0) > 0 and n - 1 > indegree.count(0):
        return []
    else:
        cycle_exists = 0
        while heap and cycle_exists == 0:
            indeg, i = heapq.heappop(heap)
            if indeg != 0:
                cycle_exists = -1
            if indeg <= 0:
                continue
            for neighbor in graph[i]:
                indegree[neighbor] -= 1
                heapq.heappush(heap, (indegree[neighbor], neighbor))
        return topological_order if cycle_exists else []
