def solve(n, prerequisites):
    graph = defaultdict(list)
    indegree = [0] * n
    for a, b in prerequisites:
        graph[b].append(a)
        indegree[a] += 1

    queue = deque()
    for i in range(n):
        if indegree[i] == 0:
            queue.append(i)

    stack = []
    while queue:
        node = queue.popleft()
        stack.append(node)
        for neighbor in graph[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                queue.append(neighbor)

    if len(stack) < n:
        return []

    largest_component = []
    while stack:
        node = stack.pop()
        largest_component.append(node)

    # Check for cycles
    visited = {node: None for node in range(n)}
    for node in largest_component:
        if dfs(graph, node, visited):
            return []

    return largest_component

def dfs(graph, node, visited):
    if visited[node] == True:
        return True
    visited[node] = True
    for neighbor in graph[node]:
        if visited[neighbor] == None:
            if dfs(graph, neighbor, visited):
                return True
        elif visited[neighbor] == True:
            return True
    visited[node] = False
    return False
