    while queue:
        node = queue.popleft()
        top_sort.append(node)

        for neighbor in graph[node]:
            indeg[neighbor] -= 1
            if indeg[neighbor] == 0:
                queue.append(neighbor)

    if len(top_sort) == n:
        return top_sort

