    SCCs = []
    visited = set()
    for node in reversed(top_sort):
        if node not in visited:
            SCC = []
            stack = [node]
            while stack:
                nv = stack.pop()
                if nv not in visited:
                    visited.add(nv)
                    SCC.append(nv)
                    stack.extend([u for u in graph[nv] if u not in visited])
            SCCs.append(SCC)

    # Build the final graph
    graph = defaultdict(list)
    indeg = [0] * n
    for SCC in SCCs:
        for i in range(len(SCC)):
            for j in range(i + 1, len(SCC)):
                graph[SCC[i]].append(SCC[j])
                indeg[SCC[j]] += 1

    # Perform topological sort on the final graph
    queue = deque([i for i in range(n) if indeg[i] == 0])
    top_sort = []
    while queue:
        node = queue.popleft()
        top_sort.append(node)

        for neighbor in graph[node]:
            indeg[neighbor] -= 1
            if indeg[neighbor] == 0:
                queue.append(neighbor)

    if len(top_sort) == n:
        return top_sort
    return []
