from collections import defaultdict, deque

def topological_sort(n, prerequisites):
    graph = [[] for _ in range(n)]
    indegree = [0] * n
    for x, y in prerequisites:
        graph[y].append(x)
        indegree[x] += 1

    queue = deque([i for i in range(n) if indegree[i] == 0])
    order = []

    while queue:
        x = queue.popleft()
        order.append(x)
        for y in graph[x]:
            indegree[y] -= 1
            if indegree[y] == 0:
                queue.append(y)

    if len(order) == n:
        return order
    else:
        visited = set()
        seen = defaultdict(list)
        for x, y in prerequisites:
            if x in visited:
                continue
            visited.add(x)
            seen[x].append(y)

        for x in seen:
            stack = [x]
            while stack:
                y = stack.pop()
                for z in graph[y]:
                    if z in seen and z not in visited:
                        visited.add(z)
                        stack.append(z)

        if len(visited) == n:
            visited_dict = dict(seen)
            order = []
            for x, y in prerequisites:
                order.append(y)
                if x in visited_dict:
                    for z in visited_dict[x]:
                        if z not in order:
                            order.append(z)
            return order
        else:
            return []
