from collections import defaultdict, deque


def solve(n, prerequisites):
    children = [[i] for i in range(n)]
    excess = [0] * n
    next_dir = [i + 1 for i in range(n)]
    visited = [False] * n
    dual_stack = []
    build_stack = []

    for a, b in prerequisites:
        excess[a] += 1
        excess[b] -= 1
        children[a].append(b)

    def build_tree(node):
        build_stack.append(node)
        visited[node] = True

        for child in children[node]:
            if not visited[child]:
                build_tree(child)

        dual_stack.append(build_stack.pop())

    for i in range(n):
        if not visited[i] and excess[i] == 1:
            build_tree(i)

    if len(dual_stack) != n:
        return []

    edges = []
    while dual_stack:
        a = dual_stack.pop()
        for b in children[a]:
            edges.append((b, a))
            if next_dir[b] == a + 1:
                for child in children[b]:
                    excess[child] += 1
                next_dir[b] = n

    for i in range(n):
        if next_dir[i] < n:
            return []

    return [i for i, _ in sorted(edges, reverse=True)]
