from collections import defaultdict, deque

def solve(n, prerequisites):
    adj_list = defaultdict(list)
    indegree = [0] * n
    for a, b in prerequisites:
        adj_list[b].append(a)
        indegree[a] += 1

    queue = deque(x for x in range(n) if indegree[x] == 0)
    topo_order = []
    while queue:
        c = queue.popleft()
        topo_order.append(c)
        for a in adj_list[c]:
            indegree[a] -= 1
            if indegree[a] == 0:
                queue.append(a)

    if len(topo_order) != n:
        return []

    pre_order = defaultdict(lambda: []);
    for a, b in reversed(topo_order):
        pre_order[a].append(b)
    res = [0] * n
    for i in reverse_topological_order(topo_order, pre_order):
        res[i] = 1
    return [i for i, r in enumerate(res) if r == 0]


def reverse_topological_order(order, pre_order):
    for it in topological_order(order):
        for c in pre_order.get(it, []):
            yield c
    for it in reversed(order):
        yield it


def topological_order(order):
    num = 0
    visited = []
    for it in order:
        if num <= len(order):
            yield order[num]
            num += 1
        elif it not in visited:
            stack = [it]
            while stack:
                i = stack.pop()
                visited.append(i)
                for c in pre_order[i] if i in pre_order else []:
                    if c not in visited:
                        stack.append(c)
