class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))

    def find(self, x):
        root = x
        while root != self.parent[root]:
            root = self.parent[root]
        while x != root:
            x, self.parent[x] = self.parent[x], root
        return root

    def union(self, x, y):
        self.parent[self.find(y)] = self.find(x)


def	parse_intervals(intervals):
    """Parse intervals and return their indices."""
    intervals.sort(key=lambda x: x[0])
    indices = []
    prev = None
    start = end = None
    for i, (s, e) in enumerate(intervals):
        if start is None:
            start = s
            end = e
        elif s > end + 1:
            if prev is not None:
                indices.append((prev, i - 1))
            prev = i
            start, end = s, e
        else:
            end = max(end, e)
    if prev is not None:
        indices.append((prev, i))
    return indices


