        right_sorted = sorted(right, key=lambda x: (x[0], -x[1]))
        if n <= 20:
            return kway_merging_helper(left_sorted, right_sorted)
        return merge_same(
            kway_merging(left_sorted),
            kway_merging(right_sorted),
        )

    def kway_merging_helper(left, right):
        merged = []
        n, m = len(left), len(right)
        i, j = 0, 0
        while i < n and j < m:
            cur = []
            while i < n and compare(left[i], right[j]) <= 0:
                cur.append(left[i])
                i += 1
            if j > 0 and compare(left[i-1], right[j-1]) < 0:
                cur.append(right[j-1])
            while j < m and compare(right[j], left[i-1]) <= 0:
                cur.append(right[j])
                j += 1
            merged.extend(must_merge(cur))
            i, j = i + len(cur), j + len(cur)
        merged.extend(left[i:])
        merged.extend(right[j:])
        return merged

