        merged_left = []
        for i in range(len(left)-1):
            if left[i][1] >= left[i+1][0]:
                merged_left.append((left[i][0], max(left[i][1], left[i+1][1])))
            else:
                merged_left.append(left[i])
        merged_right = []
        for i in range(len(right)-1):
            if right[i][1] >= right[i+1][0]:
                merged_right.append((right[i][0], max(right[i][1], right[i+1][1])))
            else:
                merged_right.append(right[i])
        for i in merged_right:
            if i[0] >= merged_left[-1][1]:
                merged_left.append(i)
            elif i[1] > merged_left[-1][1]:
                merged_left[-1] = (merged_left[-1][0], i[1])
