            for j in range(i):
                if i+n-j-1 < n and (cur[i+n-j-1][0] <= cur[j][0] and cur[j][1] <= cur[i+n-j-1][1]):
                    keep = True
            if keep:
                merged.append(cur[j])
            else:
                merged.append(cur[i])
        return merged

