def binary_search_first(nums, target):
    left, right = 0, len(nums)
    while left < right:
        mid = (left + right) // 2
        if target <= nums[mid]:
            right = mid
        else:
            left = mid + 1
    if left >= len(nums) or nums[left] != target:
        return -1
    return left

def binary_search_last(nums, target, first):
    left, right = first, len(nums)
    while left < right:
        mid = (left + right + 1) // 2
        if target >= nums[mid]:
            left = mid
        else:
            right = mid - 1
    return left

def solve(nums, target):
    first = binary_search_first(nums, target)
    if first == -1:
        return [-1, -1]
    return [first, binary_search_last(nums, target, first)]
