from collections import defaultdict, Counter
from queue import PriorityQueue

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n
        self.count = [0] * n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        root_x = self.find(x)
        root_y = self.find(y)
        if root_x != root_y:
            if self.rank[root_x] < self.rank[root_y]:
                root_x, root_y = root_y, root_x
            self.parent[root_y] = root_x
            if self.rank[root_x] == self.rank[root_y]:
                self.rank[root_x] += 1
            self.count[root_x] += self.count[root_y]

def solve(nums, k):
    n = max(nums) + 1
    group = defaultdict(list)
    for num in nums:
        group[num].append(num)
    uf = UnionFind(n)
    for num in nums:
        root, count = uf.find(num), uf.count[uf.find(num)] + 1
        uf.count[root] = count
        for neighbor in group[num]:
            neighbor_root = uf.find(neighbor)
            if neighbor_root != root:
                uf.union(num, neighbor)
    count = [uf.count[uf.find(num)] for num in range(n)]
    freq = Counter(count).most_common()
    target_freq = freq[-k][0]
    return [root for root in range(n) if uf.count[uf.find(root)] == target_freq]
