from typing import List
import sys
import heapq
import bisect

def solve(nums: List[int], k: int) -> List[int]:
    if k > len(set(nums)):
        raise ValueError('k is too big')

    freq = {}
    for num in nums:
        freq[num] = freq.get(num, 0) + 1
    max_heap = [(-count, val) for val, count in freq.items()]
    heapq.heapify(max_heap)

    second_max_count = float('inf')
    while k > 1:
        count, val = heapq.heappop(max_heap)
        second_max_count = max(second_max_count, -count)
        k -= 1

    count_thres = second_max_count + 1
    def higher_freq(x):
        count, _ = x
        return count > count_thres

    max_heap = [[-freq[num], num] for num in freq.keys() if -freq[num] >= count_thres]
    max_heap.sort(key=lambda x: x[0])
    ans = []
    for count, num in max_heap:
        count = -count
        if bisect.bisect([t[0] for t in ans], count) == len(ans):
            ans.append((count, num))
    ans.sort(key=lambda x: x[0])
    return sorted([x[1] for x in ans])

def is_max_heap(inorder, pre_order, n):
    if len(pre_order) != n:
        return False
    if pre_order[0] != inorder[0]:
        return False
    index = inorder.index(inorder[0])
    left = inorder[:index]
