    hp = []
    for val, rank in c:
        if len(hp) < k:
            heapq.heappush(hp, (rank, -val))
        elif val < -hp[0][1]:
            heapq.heappop(hp)
            heapq.heappush(hp, (rank, -val))
    return [-l[1] for l in hp]
