def solve_low_high(nums, parity):
    m = Multiset()
    for num in nums:
        m.add(num)
    frequent = []
    for num in m.cnt:
        if m.cnt[num] >= m.cnt[m.smallest_key(m.cnt)]:
            m.remove(num)
            frequent.append(num)
    if len(frequent) < parity:
        frequent = []
        m2 = Multiset()
        for num in nums:
            m2.add(num)
            if len(m.cnt) >= parity:
                break
        frequent = [x for x in m2.cnt.keys() if m2.cnt[x] == m.cnt[m.smallest_key(m.cnt)]]
    return frequent
