def solve(nums, k):
    count = Counter(nums)
    h = []
    for freq in count.values():
        heapq.heappush(h, (-freq, freq))  # Negative frequency for max heap

    unique_nums = set(nums)
    while k > 1 and h:
        _, freq = heapq.heappop(h)
        k -= 1
        if h and -h[0][0] != freq:
            break

    kth = k - query(h, unique_nums, count)

    def query(h, unique_nums, count):
        while h:
            freq, _ = heapq.heappop(h)
            if count[-freq] == 1:
                del count[-freq]
                unique_nums.remove(-freq)
                return 1
        return 0

    return sorted([_.bit_length() - 63 for _, _ in h] + [-_.bit_length() + 63 for _, _ in h[:kth]])
