        if len(result) == k:
            break
        if bisect_left(sorted_freqs, counter[val]) <= k:
            result.append(val)

    while len(result) < k:
        mintreeplen = k - len(result)
        leftlo = max_freq if not result else counter[result[-1]]
        rightlo = rightlo = max_freq + 1
        while rightlo - leftlo > 1:
            mid = (leftlo + rightlo) // 2
            shrinkedlist = [val for freq, val in frequencies if freq >= mid]
            shrinkedlist.sort()
            if bisect_left(shrinkedlist, most_frequent[-1]) < k - len(result):
                rightlo = mid
            else:
