from sys import getrefcount
from itertools import accumulate
from operator import itemgetter
from collections import Counter

class Node:
    def __init__(self, val, freq):
        self.val = val
        self.freq = freq
        self.next = None
        self.prev = None

    def __del__(self):
        if self.next:
            self.next.prev = self.prev
        if self.prev:
            self.prev.next = self.next

class CustomCounter(Counter):
    def __init__(self, locator):
        selflocator = locator
        self.locator = locator
        super().__init__()

    def __missing__(self, val):
        node = Node(val, 0)
        self.locator[node] = node
        self.locator[val] = node
        return node

class BucketSort:
    def __init__(self):
        self.max_freq = 0
        self.head = None
        self.tail = None

    def add_node(self, val, freq):
        node = self.locator[val]
        node.freq = freq
        if not self.head:
            self.head = node
            self.tail = node
        else:
            if freq - self.max_freq >= len(self.buckets):
                raise ValueError("Too many frequent values")
            bucket = self.buckets[freq - self.max_freq]
            if node.prev:
                node.prev.next = node.next
                if node.next:
                    node.next.prev = node.prev
            if node.next:
                node.next.prev = node.prev
                node.prev = node.next
            bucket.append(node)
            self.locator[val].next = bucket[-1]
            self.locator[val].prev = bucket[-1]
            return
            self.buckets[freq - self.max_freq].append(node)
            node.next = bucket[-1]
            if bucket[-1]:
                bucket[-1].prev = node
            if not node.prev:
                self.tail = node
            self.locator[val].next = bucket[-1]
            self.locator[val].prev = bucket[-1]
            return

        bucket = [node]
        while node.next:
            bucket.append(node.next)
            node = node.next
        self.max_freq = freq
        self.head = bucket[0]
        self.tail = bucket[-1]
        self.buckets = [[n for n in bucket if n.freq == f] for f in range(freq, self.max_freq + 1)]
        if len(self.buckets) > freq - self.max_freq:
            raise ValueError("Too many frequent values")

def solve(nums, k):
    counter = CustomCounter({val: 0 for val in nums})
    freqs = list(accumulate((counter[val] + 1 for val in nums), initial=[0]))
    freqs_dict = {val: idx for idx, val in enumerate(freqs)}
    sorted_idx = sorted(freqs_dict, reverse=True)
    tails = [None] * (len(nums) + 1)
    heads = [None] * (len(nums) + 1)

    def moveToFront(node):
        n = getrefcount(node)[1]
        node.prev.next = node.next
        if node.next:
            node.next.prev = node.prev
        if node.prev:
            node.prev.next = node
        else:
            heads[freqs_dict[node.freq]] = node
        node.prev = None
        node.next = tails[freqs_dict[node.freq]]
        if node.next:
            node.next.prev = node
        tails[freqs_dict[node.freq]] = node
        node.freq = freqs_dict[node.freq]
        return

    for f in sorted_idx:
        for _ in range(freqs[f]):
            moveToFront(counter[f])

    def sortBucket(head):
        node = head
        while node:
            if node.next:
                while node.next.next and node.next.freq < node.next.next.freq:
                    node.next, node.next.next = node.next.next, node.next
                node = node.next
            else:
                node = None
        return head

    buckets = []
    node = heads[len(nums)]
    while node:
        bucket = []
        while node and not node.val in bucket:
            bucket.append(node.val)
            node = node.next
        buckets.append(bucket)
        node = node.next
    return buckets[k - 1]
