        if ceil == -INF:
            continue
        lens[i] = 1
        pred[i] = [j for j in range(i) if nums[j] < ceil]
        pred[i].sort(key=lambda x: -lens[x])

        for j in range(i + 1, min(n, i + 32)):
            if nums[j] == ceil:
                lens[i] += 1

        for k, j in enumerate(pred[i]):
            if nums[j] < nums[i]:
                ndiff = nums[i] - nums[j]
                for w in range(k + 1, len(pred[j])):
                    if lens[pred[j][w]] + ndiff > lens[i]:
                        lens[i] = lens[pred[j][w]] + ndiff
                        pred[i] = pred[j][:w] + [pred[j][w], i]
                        break

