def solve(nums):
    n = len(nums)

    # Function to check if a value is reachable in a binomial coefficient table
    def is_reachable(binom_coeff, val):
        for i in reversed(range(len(binom_coeff) + 1)):
            if val >= binom_coeff[i] and i > 0:
                return True
        return False

    # Function to generate binomial coefficient table
    def gen_binom_table(n):
        table = [[1]]
        for i in range(1, n + 1):
            row = [1]
            for j in range(1, i):
                row.append(table[i - 1][j - 1] + table[i - 1][j])
            row.append(1)
            table.append(row)
        return table

    # Function to update the binomial coefficient table after appending a value
    def update_binom_table(table, num):
        n = len(table)
        new_row = [(table[n - 1][i] + num) if i > 0 else num for i in range(n)]
        return table + [new_row]

    binom_coeff = [[nums[0]]]
    max_length = 1
    max_reachable = [False] * (10001 * n)
    max_reachable[binom_coeff[0][0] * n] = True

    for i, num in enumerate(nums[1:]):
        binom_coeff = update_binom_table(binom_coeff, num)
        for val in binom_coeff[-1]:
            if val > max_reachable[val * n]:
                max_reachable[val * n] = True
                max_length = max(max_length, val)

    # Then check for a potential subsequence with up to n elements
    for i in range(n):
        for j in range(n):
            if binom_coeff[j][i] > max_length and is_reachable(binom_coeff[j], binom_coeff[j][i]):
                max_length = binom_coeff[j][i]

    # Update answer to minimum reachable value
    index = next((i for i, x in enumerate(max_reachable) if x), None)
    binom_table = gen_binom_table(n)
    min_reachable_val = float('inf')
    for j in range(n):
        val = binom_table[j][n - 1]
        if val * n <= index < (val + 1) * n and val < min_reachable_val:
            min_reachable_val = val
    return min_reachable_val + 1
