    """Partitions the list around a pivot p."""
    # Move the pivot to the end
    i = lo
    while i < lo + hi - 1:
        if nums[i] < p:
            nums[i], nums[lo] = nums[lo], nums[i]
            lo += 1
        elif nums[i] > p:
            nums[hi-1], nums[i] = nums[i], nums[hi-1]
            hi -= 1
            if hi <= lo:  # pivot is at index hi-1
                nums[hi], nums[lo] = nums[lo], nums[hi]
                break
