    if m > n:
        return -1
    p = modulo_base(200)
    h = pow(26, m - 1, (1 << 8) - 1)
    needle_hash = sum(f(p, c, 1) for c in needle) % (1 << 8)
    haystack_hash = sum(f(p, c, 0) for c in haystack[:m]) % (1 << 8)
