def solve(nums):
    def find_max_crossing_log(n):
        l = 1
        while (l <= n):
            l <<= 1
        return l >> 1

    def find_max_crossing(mid):
        s1 = sum(1 for i in range(len(nums)) if nums[i] < mid)
        s2 = sum(1 for i in range(len(nums)) if nums[i] >= mid)
        return s1 - nums[~s2]

    def binary_search(begin, end):
        while begin < end:
            mid = find_max_crossing_log((begin + end) // 2)
            if mid > begin:
                mid = max(begin, find_max_crossing(mid))
            else:
                mid = find_max_crossing(mid)
            if mid == begin:
                return find_max_crossing(begin)
            elif nums[mid] < begin:
                begin = mid
            else:
                end = mid

    return binary_search(0, len(nums) - 1)
