def dfs(i, order, graph, used):
    used[i] = 1
    for j in graph[i]:
        if used[j] == 0:
            dfs(j, order, graph, used)
    order.append(i)

def sweep(edges, n):
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    used = [0] * n
    order = []

    for i in range(n):
        if used[i] == 0:
            dfs(i, order, graph, used)
    order.reverse()

    labels = list(range(n))
    ct = 0

    for i in range(n):
        for j in graph[i]:
            if labels[i] > labels[j]:
                labels[i] = min(labels[i], labels[j])
        if labels[i] != i:
            ct += 1

    return ct

def solve(n, edges):
    sys.setrecursionlimit(n * 2)
    ans = sweep(edges, n)
    if n == 1 or len(edges) < n - 1:
        if len(edges) == 0:
            return n
        else:
            return 1
    return n - ans
