def label(node, labels):
    if labels[node] < 0:
        return labels[node]
    labels[node] = label(node, labels)
    return labels[node]

def initialize_labels(n):
    labels = [-1] * n
    return labels

def update_labels(labels, edge):
    u, v = edge
    u_label = label(u, labels)
    v_label = label(v, labels)
    if u_label != v_label:
        labels[v_label] = u_label
        return u_label
    return -1

def solve(n, edges):
    labels = initialize_labels(n)
    updated = True
    while updated:
        updated = False
        new_labels = [-1] * n
        for edge in edges:
            label = update_labels(labels, edge)
            if label != -1:
                updated = True
                new_labels[label] = label
                new_labels[edge[0]] = label
                new_labels[edge[1]] = label
        labels = new_labels
    return sum(1 for label in labels if label < 0)
