from typing import List

def solve(n: int, edges: List[List[int]]) -> int:
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    labels = [n for _ in range(n)]
    def propagatedRoute(edges: List[List[int]], labels: List[int]) -> bool:
        changes = False
        for u in range(n):
            min_label = labels[u]
            for v in edges[u]:
                min_label = min(min_label, labels[v])
            if labels[u] != min_label:
                labels[u] = min_label
                changes = True
        return changes

    num_components = n
    while True:
        if not any(propagatedRoute(graph, labels)):
            break
        num_components -= 1

    return num_components
