    for _ in range(1, n+1):
        stack = list(range(n))
        changed = True

        while stack and changed:
            changed = False
            x = stack.pop()
            if lab[x] != x:
                y = lab[x]
                lab[x] = x
                if x < y: stack.append(y)
                stack.extend(i for i in range(x+1, y) if i not in stack)
                stack.extend(i for i in range(y, x-1, -1) if i not in stack)
                for j in stack:
                    lab[j] = min(lab[j], y)
                    if lab[j] < y: changed = True

