def compare_labels(node1, node2, labels):
    return node1[1] == node2[1] == labels[node2]

def extract_nodes(edge, labels):
    return min(edge), labels[min(edge)], max(edge), labels[max(edge)]

def merge_labels(node1, node2):
    return min(node1[1], node2[1])

def sweep_edges(n, edges, labels):
    changed = True
    while changed:
        changed = False
        changes = [False]*n
        for edge in edges:
            if compare_labels(*extract_nodes(edge, labels)):
                min_node, min_label, max_node, max_label = extract_nodes(edge, labels)
                if min_label != max_label:
                    labels[max_node] = merge_labels((max_node, max_label), (min_node, min_label))
                    if not changes[max_node]:
                        changes[max_node] = True
                    if not changes[min_node]:
                        changes[min_node] = True
                    changed = True
        for i in range(n):
            if changes[i]:
                labels[i] = merge_labels((i, labels[i]), (i, float('inf')))
    return sum(1 for label in labels if label < float('inf'))

def solve(n, edges):
    labels = list(range(n))
    return sweep_edges(n, edges, labels)
