        for j in range(i - 1, -1, -1):
            idx = bisect.bisect_left([x[0] for x in intervals[j:rightmost_i + 1]], intervals[j][1])
            if idx != len(intervals[j:rightmost_i + 1]):
                new_interval_idx = bisect.bisect_left([x[1] for x in intervals[j:rightmost_i + 1]], intervals[j][0], idx, len(intervals[j:rightmost_i + 1]))
                if new_interval_idx < len(intervals[j:rightmost_i + 1]):
