def solve(intervals):
    intervals.sort(key=lambda x: x[1])
    n = len(intervals)
    suffix = [[interval[1], interval[1]] for interval in intervals]
    added = [interval[1] for interval in intervals]
    for i in range(n - 2, -1, -1):
        last_added = binary_search(suffix[i][1], added)
        suffix[i][1] = added[last_added] if last_added < n else suffix[i][1]
        added[i] = suffix[i][1]
    removed = [0] * n
