    intervals.sort(key=lambda x: x[1])
    merged = [intervals[0]]
    for interval in intervals[1:]:
        if merged[-1][1] >= interval[0]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], interval[1]))
        else:
            merged.append(interval)
    return merged

def solve(intervals):
    merged = merge(intervals)

    def is_compatible(i, k):
        return merged[i][1] <= merged[k][0]

    def binary_search(left, right, comp):
        while left < right:
            mid = (left + right + 1) // 2
            if comp(mid):
                left = mid
            else:
                right = mid - 1
        return left

    n = len(merged)
    dp = [0] * n
    prefix_zeroes = [0] * n
    for i in range(n):
        l, r = 0, i
        compatible_i = i
        k = binary_search(l, r, lambda i: not is_compatible(compatible_i, i) and merged[i][0] > merged[compatible_i][1])
        if k == r:
            prefix_zeroes[i] = 1
        else:
            prefix_zeroes[i] = prefix_zeroes[k] + 1
        dp[i] = min(1, dp[k] + prefix_zeroes[i] if is_compatible(i, k) else i // 2)

    return n - max(dp)
