def solve(intervals):
    if not intervals:
        return 0
    intervals.sort(key=lambda x: x[1])
    n = len(intervals)
    memo = [None] * n

    def recurse(index):
        if index == n:
            return 0
        if memo[index] is not None:
            return memo[index]
        remove = 1 + recurse(index + 1)
        include = 0
        i = index + 1
        while i < n and intervals[i][0] < intervals[index][1]:
            include = max(include, 1 + recurse(i))
            i += 1
        memo[index] = min(remove, include)
        return memo[index]

    return min(recurse(0), recurse(1))

