            self.n = n
            self.reach = [0] * n
            self.before = [0] * n
            self.after = [0] * n

    def nodes_by_degree(graph):
        q = []
        for i in range(len(graph.reach)):
            if graph.reach[i] == 0:
                q.append(i)
        nodes = {}
        idx = 0
        while q:
            v = q.pop(0)
            nodes[v] = idx
            idx += 1
            for i in range(len(graph.before)):
                if graph.before[i] == v and graph.reach[i] == 0:
                    graph.reach[i] = 1
                    q.append(i)
        return nodes

    def dpsolve(nodes, graph):
        dp = [0] * len(graph.reach)
        for u in nodes:
            dp[u] = 1
        for u in nodes:
            for v in range(len(graph.before)):
                if graph.before[v] == u:
                    dp[u] = max(dp[u], dp[v] + 1)
                elif graph.after[v] == u:
                    dp[u] = max(dp[u], dp[v] + 2)
        return max(dp)

    end = max(end for start, end in intervals) + 1
    n = end

    graph = Graph(n)

    nodes = nodes_by_degree(graph)

    for i in range(n):
        early = -50000
        for s, e in intervals:
            if s <= i and i < e:
                if e > early:
                    graph.before[early] = i
                    graph.after[i] = early
                    early = e
        graph.reach[i] = 1

    return len(intervals) - dpsolve(nodes, graph)
