                if new_num(sx) < new_num(sy) and new_num(sy) < new_num(ex):
                    G.add_edge(f'{i}-0', f'{j}-1')
                if new_num(sy) < new_num(ex) and new_num(ex) < new_num(ey):
                    G.add_edge(f'{j}-0', f'{i}-1')
        return G

    def longest_path(G):
        @lru_cache(maxsize=None)
        def longest_paths(node):
            if node not in G:
                return {'parents': []}
            best = {'_lengths': float(-inf), 'parents': []}
            for parent, _ in G[node]:
                parent_name, parent_edge = parent
                parent_depth = G.nodes[parent]['depth']
                new_lengths = dp[parent_name][parent_edge] + 1
                if new_lengths > best['lengths']:
                    best = {'lengths': new_lengths, 'parents': [(parent_name, parent_edge)]}
                elif new_lengths == best['lengths']:
                    best['parents'].append((parent_name, parent_edge))
            if len(best['parents']) == 0:
                return {'lengths': 0, 'parents': [(node, 0)]}
            longest_parent = max(best['parents'], key=lambda parent: dp[parent[0]][parent[1]]['lengths'])
            return {'lengths': best['lengths'], 'parents': [longest_parent] + best['parents']}

        G.add_node(0, {'depth': 0})
        longest_depths = {node: 0 for node in G.nodes()}
        for i in range(1, len(intervals)):
            longest_depths[i] = 0
            for parent, _ in G.nodes(i):
                longest_depth = longest_depths[parent]
                if longest_depth + 1 > longest_depths[i]:
                    longest_depths[i] = longest_depth + 1
        for node in reversed(random_pos(G)):
            longest_depths[node] = max(longest_depths[node], longest_depths[G.nodes[node]['parent']])
            G.nodes[node]['depth'] = longest_depths[node]
        dp = {node: longest_paths(node) for node in G.nodes()}
        return max(dp[node]['lengths'] for node in G.nodes())

    def random_pos(G):
        nodes = list(G.nodes())
        node_ids = list(range(len(nodes)))
        random.shuffle(node_ids)
        random_pos = {old_id: i for i, old_id in enumerate(random_ids)}
        random_pos[0] = 0
        for node, _ in G.nodes(data=True):
            if node != 0:
                G.nodes[node]['parent'] = random_pos[G.nodes[node]['parent']]
        return [random_pos[i] for i in random_ids]

    G = build_dag()
    return len(intervals) - 1 - longest_path(G)
