                        dp[j][k] = max(dp[j][k] if dp[j][k] != -1 else 0, dp[j][i] + dp[i][k])
                        max_path[j][k] = max(max_path[j][k], max_path[j][i] + long_path(DAG, i, k, dp[j], max_end))
                        visited.remove(j)
    n = max(max_end)
