import networkx as nx
from collections import defaultdict

def solve(intervals):
    # Build the compatibility graph (directed acyclic graph)
    graph = nx.DiGraph()
    for i in range(len(intervals)):
        for j in range(len(intervals)):
            if i != j and intervals[i][1] <= intervals[j][0]:
                graph.add_edge(i, j)

    # Initialize DP table with infinity
    dp = defaultdict(lambda: float('inf'))
    dp[-1] = 0

    # Perform DFS to find the longest path in the graph
    seen = set()
    def dfs(node):
        if node in seen:
            return float('inf')
        seen.add(node)
        res = dp[node]
        for neighbor in graph.neighbors(node):
            res = min(res, 1 + dfs(neighbor))
        seen.remove(node)
        return res

    # Update the DP table with the longest path values
    for i in range(len(intervals)):
        dp[i] = min(dp[i], dfs(i))

    # Return the minimum number of intervals to remove
    return len(intervals) - max(dp.values())
