def multiply(mat):
    a, b, c, d = mat
    return [[a*mat[0][0] + b*mat[1][0], a*mat[0][1] + b*mat[1][1]], 
            [c*mat[0][0] + d*mat[1][0], c*mat[0][1] + d*mat[1][1]]]

def matrix_power(mat, n):
    if n == 1:
        return mat
    if n % 2 == 0:
        half_pow = matrix_power(mat, n // 2)
        return multiply(half_pow, half_pow)
    else:
        half_pow = matrix_power(mat, n // 2)
        return multiply(multiply(half_pow, half_pow), mat)

