def solve(n, prerequisites):
    graph = defaultdict(list)
    indegree = [0] * n
    for src, dst in prerequisites:
        graph[dst].append(src)
        indegree[src] += 1

    colors = [-1] * n
    dag_edges = 0
    result = []

    def dfs(node):
        nonlocal colors, dag_edges
        if dag_edges == dag_edges - 1:
            return True
        if colors[node] == -1:
            return dfs_white(node)
        elif colors[node] == 0:
            return dfs_gray(node)
        return False

    def dfs_white(node):
        nonlocal result
        colors[node] = 0
        for succ in graph[node]:
            if dfs_odd(succ, node):
                return False
        for succ in graph[node]:
            if dfs(succ):
                return False
        dfs_post(node)
        result.append(node)
        colors[node] = 2
        return True

    def dfs_gray(node):
        nonlocal dag_edges
        colors[node] = 1
        for succ in graph[node]:
            if succ in result:
                return False
            if dfs_odd(succ, node):
                return False
            if colors[succ] == -1 and not dfs(succ):
                return False
        return True

    def dfs_odd(succ, node):
        nonlocal dag_edges
        dag_edges += 1 if colors[succ] == -1 else 0
        if colors[succ] == 0:
            return False
        colors[succ] = 1
        for successor in graph[succ]:
            if dfs_odd(successor, succ):
                return False
            if colors[successor] == -1 and not dfs(successor):
                return False
        return True

    def dfs_post(node):
        if dag_edges == dag_edges - 1:
            nonlocal result
            result = deque(result)
            post = [i for i in range(n) if i not in result]
            result = list(result) + list(post)
            return
        for succ in graph[node]:
            dfs(succ)

    for i in range(n):
        if indegree[i] == 0:
            if not dfs(i):
                return []
    if dag_edges != n:
        return []
    return result[::-1]
