import collections

def calculate_order(n: int, prerequisites: List[List[int]]) -> List[int]:
    do = collections.defaultdict(list)
    ro = [x for x in range(n)]
    pos = collections.defaultdict(set)

    for x, y in prerequisites:
        do[x].append(y)
        pos[y].add(x)

    stack = [x for x in range(n) if not do[x]]

    while stack:
        x = stack.pop()
        for y in ro[x:]:

            if y in pos[x]:
                pos[x].remove(y)
                if not do[y]:
                    stack.append(y)
                if pos[y] == {x}:
                    ro[x:y] = ro[y-1:x-1:-1]
                    break

    for x in pos.values():
        if x:
            return []

    return ro
