class Graph:
    def __init__(self, n):
        self.n = n
        self.adj_list = [[] for _ in range(n)]

    def add_edge(self, a, b):
        self.adj_list[b].append(a)

    def _dfs(self, node, color, colors, p_colors, post_order, res):
        colors[node] = color

        for neighbor in self.adj_list[node]:
            if colors[neighbor] == color and neighbor in p_colors:
                return [False, []]
            if colors[neighbor] == 0:
                p_colors.add(neighbor)
                ret, res = self._dfs(neighbor, color ^ 1, colors, p_colors, post_order, res)
                if not ret:
                    p_colors.pop()
                    return [False, []]
            elif colors[neighbor] == color:
                return [False, []]

        post_order.append(node)
        return [True, post_order]

    def _reverse_dfs(self, node, parent, colors):
        for neighbor in self.adj_list[node]:
            if neighbor != parent and colors[neighbor] == colors[node]:
                return [False]
            if colors[neighbor] == 0:
                colors[neighbor] = -colors[node]
                ret = self._reverse_dfs(neighbor, node, colors)
                if not ret:
                    return [False]
        return [True]

    def solve(self, n, prerequisites):
        adj = [self.adj_list[i] + [i] for i in range(n)]
        colors = [0] * n
        p_colors = set()
        for a, b in prerequisites:
            adj[b].append(a)
        for i in range(n):
            if colors[i] == 0:
                ret, post_order = self._dfs(i, 1, colors, {i}, [], [])
                if not ret:
                    return []
                if len(post_order) == n and True in self._reverse_dfs(post_order[-1], -1, colors):
                    res = list(reversed(post_order))
                else:
                    post_order.reverse()
                    res = post_order
                return res
        return adjacency_list_to_topological_order(adj)

