def solve(n, prerequisites):
    """Orders tasks numbered 0 to n - 1 respecting prerequisites."""
    graph = [[] for _ in range(n)]
    ins = [0] * n

    for a, b in prerequisites:
        ins[a] += 1
        graph[b].append(a)

    for i in range(n):
        if ins[i] == 0:
            order = i
            break
    else:
        return []

    is_visited = [0] * n
    while order < n and is_valid_order(is_visited, graph, order):
        predecessor = order
        while ins[predecessor] > 0:
            predecessor -= 1
        predecessor = order if predecessor == order else predecessor + 1

        for successor in graph[order]:
            ins[successor] -= 1
            if ins[successor] == 0:
                successor_holder = successor
                while ins[successor_holder] > 0:
                    successor_holder -= 1
                successor_holder = successor if successor_holder == successor else successor + 1
                order = max(successor_holder, order)

        order += 1

    return [i for i in range(n) if is_visited[i] == 1]
