        node, is_largest = stack.pop()
        if is_largest:
            if node.children[0] and node.children[0].start <= node.end:
                stack.append((node.children[1], True))
                stack.append((node.children[0], False))
            else:
                merged_intervals.append([node.start, node.end])
        else:
            for i, child in enumerate([node.children[0], node.children[1]]):
                if child:
