        last = first
        for lower in range(first + 1, len(nums)):
            if nums[lower] != target:
                break
            last = lower
    else:
        return [-1, -1]

    temp_left, temp_right = brackets(nums, target)
    if temp_left > last:
        temp_left = last

    while temp_left > 0:
        if nums[temp_left - 1] == target:
            first = temp_left - 1
        temp_left -= 1

    if first == -1:
        return [-1, -1]

    last = last
    for higher in range(last - 1, temp_right, -1):
        if nums[higher] != target:
            break
        last = higher

    if last == -1:
        return [-1, -1]
    return [first, last]
