class LRUCache:
    def __init__(self, capacity=256):
        self.capacity = capacity
        self.cache = {}

    def __lru_cache_wrap__(self, func):
        def wrap(*a, **kw):
            kw.pop('cache',None)
            v = self.cache.get(a)
            if v is not None:
                return v
            v = func(*a, **kw)
            if len(self.cache) >= self.capacity:
                self.cache.clear()
            self.cache[a] = v
            return v
        return wrap

    def __getattribute__(self, *a, **kw):
        return super().__getattribute__('%s__%s' % ('cache_',a[0]))
