def compress_values(nums):
    ranks = sorted(set(nums))
    compression = {x: i for i, x in enumerate(ranks)}
    return compression, ranks

class FenwickTree:
    def __init__(self, n):
        self.n = n
        self.tree = [0] * (n + 1)

    def update(self, idx, delta):
        while idx <= self.n:
            self.tree[idx] += delta
            idx += idx & -idx

    def query(self, idx):
        res = 0
        while idx > 0:
            res += self.tree[idx]
            idx -= idx & -idx
        return res

    def find_kth(self, k):
        idx = 0
        for p in range(len(self.tree) - 1, 0, -1):
            if 2 * idx + (p & -p) <= len(self.tree) - 1 and k > self.tree[idx + p]:
                k -= self.tree[idx + p]
                idx += p
        return idx + 1

def solve(nums):
    compression, ranks = compress_values(nums)
    n = len(nums)
    maxima = [float('-inf')] * n
    rank_tree = FenwickTree(n)
    max_ranks = [0] * n

    for i, x in enumerate(nums):
        r = compression[x]
        maxima[i] = rank_tree.query(r) if r > 0 else -max_ranks[i-1]
        rank_tree.update(r, 1)
        max_ranks[i] = max(max_ranks[i-1], maxima[i])

    res = 0
    rank_tree2 = FenwickTree(n)
    for i in reversed(range(n)):
        x, r = nums[i], compression[nums[i]]
        rank_tree2.update(r, 1)
        rank_tree.update(r + 1, -1)
        if x > max_ranks[i-1]:
            if rank_tree.query(r) > 0:
                rank_tree2.update(r, -1)
                rank_tree.update(r + 1, 1)
        else:
            res = max(res, max_ranks[i-1], rank_tree.find_kth(r))
    return res
