class Fenwick:
    """Fenwick Tree Data Structure"""

    def __init__(self, n):
        """Initialize a Fenwick Tree with n leaves"""
        self.n = n
        self.treap = [None] * (2 * n)

    def _lca(self, k):
        """Find the k-th smallest rank in the right child subtree"""
        pa = 0
        pc = self.n
        while pc - pa > 1:
            md = (pc + pa) // 2
            if sum(self.treap[md + self.n]) >= k:
                pc = md
            else:
                pa = md
        return pc

    def _lca_rank(self, k):
        """Query the rank (1-indexed) of the k-th smallest value in the right child subtree"""
        rank = 0
        pa = 0
        pc = self.n
        while pc - pa > 1:
            md = (pc + pa) // 2
            if sum(self.treap[md + self.n]) >= k:
                rank += md + 1
                pa = md
            else:
                pc = md
        return rank

    def range_max(self, l, r):
        """Compute the maximum value in the interval [l, r)"""
        if r <= l:
            return -10000
        tot = None
        for sake in (l, r):
            low = 0
            high = self.n - 1
            while low < high:
                mid = (low + high) // 2
                v = self._lca(mid + 1)
                if v >= sake:
                    high = mid
                else:
                    low = mid + 1
            rank = self._lca_rank(sake)
            tot = max(tot, self.treap[rank + self.n][rank])
        return tot

    def update_range_max(self, l, r, y):
        """Update the maximum value in the interval [l, r)"""
        for sake in (l, r):
            low = 0
            high = self.n - 1
            while low < high:
                mid = (low + high) // 2
                v = self._lca(mid + 1)
                if v >= sake:
                    high = mid
                else:
                    low = mid + 1
            idx = self._lca_rank(sake)
            ych = (y,) + self.treap[idx + self.n]
            self.treap[idx + self.n] = max(ych, ych[1:])


class RankEncoder:
    """Rank encoder"""

    def __init__(self, nums):
        """Initialize the rank encoder with shrinked values (0-indexed)"""
        encode = {val: idx for idx, val in enumerate(sorted(set(nums)))}
        self.n = len(encode)
        self.encode = encode

    def query(self, x):
        """Query the rank (0-indexed) of value x"""
        return self.encode[x]

    def decode(self, j):
        """Decode the j-th smallest rank to value"""
        return list(self.encode.keys())[j]


def solve(nums):
    """Compute the length of the longest strictly increasing subsequence"""

    rce = RankEncoder(nums)
    fen = Fenwick(len(nums))
    dp = [0] * len(nums)
    ans = 0
    for i in range(len(nums)):
        x = rce.query(nums[i])
        y = max(fen.range_max(i, len(nums)), 0) + 1
        fen.update_range_max(i, i + 1, x)
        df = x + 1 - y
        dp[i] = df + dp[max(0, i - y + 1)]
        ans = max(ans, dp[i])
    return ans
