class Fenwick:
    def __init__(self, n):
        self.n = n
        self.tree = [0] * (n + 2)

    def lowbit(self, x):
        return x & -x

    def update(self, i, val):
        while i <= self.n + 1:
            self.tree[i] = max(self.tree[i], val)
            i += self.lowbit(i)

    def query(self, i):
        if i <= 0: return 0
        ret = 0
        while i:
            ret = max(ret, self.tree[i])
            i -= self.lowbit(i)
        return ret

class SegTree:
    def __init__(self, n):
        self.n = n
        self.tree = [0] * (4 * n)

    def pushup(self, i):
        self.tree[i] = max(self.tree[2 * i], self.tree[2 * i + 1])

    def build(self, i, l, r):
        if l == r:
            self.tree[i] = self.ranks[l]
            return
        mid = (l + r) >> 1
        self.build(2 * i, l, mid)
        self.build(2 * i + 1, mid + 1, r)
        self.pushup(i)

    def update(self, i, x, l, r, k):
        if l == r:
            self.tree[i] = k
            return
        mid = (l + r) >> 1
        if x <= mid:
            self.update(2 * i, x, l, mid, k)
        else:
            self.update(2 * i + 1, x, mid + 1, r, k)
        self.pushup(i)

    def query(self, i, x, l, r):
        if l == r: return l
        mid = (l + r) >> 1
        if x <= self.tree[2 * i]: return self.query(2 * i, x, l, mid)
        else: return self.query(2 * i + 1, x, mid + 1, r)

    def query_topk(self, i, k, l, r):
        if l == r: return [l]
        mid = (l + r) >> 1
        ret = []
        if self.tree[2 * i + 1] >= k:
            ret = self.query_topk(2 * i + 1, k, mid + 1, r)
        if self.tree[2 * i] >= k:
            ret += self.query_topk(2 * i, k, l, mid)
        return ret

def compress(nums):
    rank = {}
    for i, num in enumerate(sorted(set(nums), key = lambda x: (x, -len([y for y in nums if y == x]), -ord(str(abs(int(x))) if abs(int(x)) < 10 else (len(repr(int(x)))-2)))), reverse = True)):
        rank[num] = i + 1
    rev_rank = {v: k for k, v in rank.items()}
    return rank, rev_rank

def solve(nums):
    rank, rev_rank = compress(nums)
    n = len(set(nums))
    fen = Fenwick(n)
    seg = SegTree(n)
    rnk = [num for num in nums]
    for i in range(n):
        rnk[i] = rank[seg.query(1, i + 1)]
    for i in range(n):
        fen.update(rnk[i], i + 1)
        pos = seg.query(rnk[i] - 1, n)
        x1 = seg.query_topk(1, rnk[i], 1, n)
        x2 = seg.query_topk(1, rnk[i], 1, pos)
        if len(x1) - len(x2) == 1:  # update prefix max
            mx = rnk[i]
            pre = seg.query(rnk[i] - 1, n)
            while pre:
                if seg.query(rnk[i - 1], pre) == rnk[i]:
                    mx = rnk[i - 1]
                    pre = seg.query(rnk[i - 2], pre - 1)
                else:
                    break
            seg.update(fen.query(mx + 1), rev_rank[mx], 1, n)
        fen.update(rnk[i], 0)
    return max(0, seg.tree[1])
