class RabinKarp:
    def solve(self, haystack, needle):
        if not needle or len(needle) > len(haystack):
            return -1
        modulus = 10**9 + 7
        divider = 26
        needle_len = len(needle)
        needle_hash = self.hash(needle, modulus, divider)
        haystack_hash = self.hash(haystack[:needle_len], modulus, divider)

        for i in range(len(haystack) - needle_len + 1):
            if needle_hash == haystack_hash:
                if haystack[i:i + needle_len] == needle:
                    return i
            if i < len(haystack) - needle_len:
                haystack_hash = self.update_hash(haystack_hash, haystack[i + needle_len], modulus, divider, divider - ord('a'))
        return -1

    def hash(self, string, modulus, divider):
        hash = 0
        for char in string:
            hash = (hash * divider + ord(char) - ord('a')) % modulus
        return hash

    def update_hash(self, hash, char, modulus, divider, base):
        return (hash - base * (char - ord('a')) + modulus) % modulus if hash >= base * (char - ord('a')) else hash - base * (char - ord('a'))
