    """Construct the good suffix table for the given pattern."""
    n = len(pattern)
    table = [0] * n
    length = 0

    for i in range(1, n):
        while length > 0 and pattern[length] != pattern[i]:
            length = table[length - 1]
        if pattern[length] == pattern[i]:
            length += 1
        table[i] = length

    return table

def mismatch_cost(c):
    """Calculate the expected cost of a mismatch at the current position."""
    if c == '$': return 0
    returns: 0 if c == 'a'; 1 if c == 'c'; 2 if c == 'g'; 3 if c == 't'
    return ord(c) - 96

def boyer_moore_horspool(haystack, needle):
    """Search for the first occurrence of needle in haystack."""
    n, m = len(haystack), len(needle)
    bad_chars = {c: n for c in needle}
    for i in range(m - 1, 0, -1):
        bad_chars[needle[i]] = m - 1 - i
    shift = m - 1
    while shift <= n:
        s = n - shift
        index = m - 1
        while index >= 0 and haystack[s] == needle[index]:
            s, index = s - 1, index - 1
            if index == -1:
                return s + 1
        if s in bad_chars:
            shift += max(m - index - bad_chars[haystack[s]], 0)
        else:
            break
    return -1

def solve(haystack: str, needle: str) -> int:
    """Search for the first occurrence of needle in haystack."""
    if len(needle) > len(haystack):
        return -1
    max_mismatch_cost = 0
    for _, c in enumerate(needle):
        max_mismatch_cost += mismatch_cost(c)

    max_hook_char = [mismatch_cost(c) for c in 'acgt']
    max_hook_cost = [0] * 200
    for i in range(1, len(needle)):
        max_hook_cost[i] = max_hook_cost[i-1] + max_hook_char[ord(needle[i]) - 96]

    # Setup of Needle
    bad_chars = {}
    for i in range(len(needle)):
        bad_chars[needle[i]] = len(needle) - 1 - i
    shift = len(needle) - 1
    hay_mapping = [None] * 97; S = 97
    for ch in needle:
        hay_mapping[ord(ch)] = S + 1; S += 1

    for ch in haystack:
        hay_mapping[ord(ch)] = S + 1; S += 1

    # Horspool Stage
    while len(haystack) - shift >= len(needle):
        for i in range(len(needle) - 1, 0, -1):
            cost = max_hook_cost[i - 1] if i > 1 else 0
            ch = haystack[len(haystack) - shift + i]
            needle_equiv = needle[i]
            hook_cost = max_hook_char[ord(ch) - 96] + cost
            index = bad_chars.get(needle_equiv, len(needle) - shift)

            if hook_cost >= index:
                hook_cost = index
            s = len(needle) - shift + index
            index -= 1
            while index >= 0 and haystack[s] == needle[index]:
                s, index = s - 1, index - 1
                if index == -1:
                    return len(haystack) - shift + 1
            if s in bad_chars:
                shift += max(max(hook_cost - max_mismatch_cost, 0), max(len(needle) - index - bad_chars[haystack[s]], 0))
            else: break
    return -1
