        return -1

    bad_char_heuristic = compute_bad_char_heuristic(needle)
    needle_len = len(needle)
    haystack_len = len(haystack)
    anchor = needle_len - 1

    while anchor < haystack_len:
        bad_char = ord(haystack[anchor])
        if bad_char_heuristic[bad_char] == needle_len - 1:
            needle_match = True
            for i in range(needle_len):
