        y_root = find(y)
        if x_root == y_root:
            return
        if rank[x_root] > rank[y_root]:
            parent[y_root] = x_root
        elif rank[y_root] > rank[x_root]:
            parent[x_root] = y_root
        else:
            parent[y_root] = x_root
            rank[x_root] += 1
        nonlocal components
        components -= 1

    for u, v in edges:
        union(u, v)

