        if intervals[i-1][0] >= right:
            can_merge_here = True
        if can_merge_here and can_merge(intervals[:i], i, intervals[i-1][1]):
            dp[i] = [left + 1 if left else 1, end=right]
        else:
            dp[i] = [left + 1 if left else 1, end=intervals[i-1][1]]

