class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n + 1))
        self.rank = [0] * (n + 1)
        self.time = 0

    def find(self, x):
        if x != self.parent[x]:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        root_x, root_y = self.find(x), self.find(y)
        if root_x != root_y:
            if self.rank[root_x] > self.rank[root_y]:
                root_x, root_y = root_y, root_x
            self.parent[root_x] = root_y
            self.rank[root_y] += self.rank[root_x]
            self.time += 1
            return self.time
        return 0

def solve(intervals):
    def overlap(i, j):
        return intervals[i][1] >= intervals[j][0] and intervals[i][0] <= intervals[j][1]

    n = len(intervals)
    dsu = UnionFind(n)
    size = [1] * n
    events = [(start, i, False) for i, (start, end) in enumerate(intervals)] + \
            [(end, i, True) for i, (start, end) in enumerate(intervals)]

    events.sort()

    res = 0
    for t, i, end in events:
        merged_with = dsu.find(i)
        if merged_with:
            size[merged_with] += size[i]
            res += 1
            dsu.parent[i] = merged_with
        else:
            for j in range(n):
                if overlap(i, j) and dsu.find(j) != i:
                    dsu.union(i, j)
                elif not end and not overlap(i, j) and dsu.find(i) == dsu.find(j):
                    res += 1
                    dsu.union(i, j)

    return n - max(size)
