from collections import defaultdict
from typing import List

def solve(intervals: List[List[int]]) -> int:
    import math
    # Use interval length as node weight in a graph
    graph = defaultdict(list)
    for i, (s1, e1) in enumerate(intervals):
        for j, (s2, e2) in enumerate(intervals):
            if i != j and min(e1, e2) >= max(s1, s2) + 1:
                graph[i].append(j)

    color = [0] * len(intervals)
    count = 1

    # Topological sort with Kahn's algorithm
    in_degree = [0] * len(intervals)
    queue = []
    for nodes in graph.values():
        for node in nodes:
            in_degree[node] += 1
    for i, deg in enumerate(in_degree):
        if deg == 0:
            queue.append(i)

    while queue:
        node = queue.pop(0)
        color[node] = count
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)
        count += 1

    # Check if remaining intervals are non overlapping and count removed intervals
    max_edges_between_satisfiable = sum(max(max(math.inf, e1 - e2 + 1) for e1 in intervals[n])) for n, e2 in enumerate(intervals))

    for i, (s1, e1) in enumerate(intervals):
        if color[i] == 0:
            for j, (s2, e2) in enumerate(intervals):
                if i != j and max(s2 + 1, e1 + 1) <= min(s1, e2 + 1):
                    max_edges_between_satisfiable -= 1

    return len(intervals) - max_edges_between_satisfiable

