class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, p):
        if self.parent[p] != p:
            self.parent[p] = self.find(self.parent[p])
        return self.parent[p]

    def union(self, p, q):
        prt, qrt = self.find(p), self.find(q)
        if prt == qrt:
            return False
        if self.rank[prt] < self.rank[qrt]:
            self.parent[prt] = qrt
        elif self.rank[qrt] < self.rank[prt]:
            self.parent[qrt] = prt
        else:
            self.parent[qrt] = prt
            self.rank[prt] += 1
        return True


def solve(intervals):
    all_parents = {}
    graph = {}
    for i, (s, e) in enumerate(intervals):
        node = (s, e)
        all_parents[node] = i
        graph[node] = []
        for prev_e in range(s - 1, e):
            prev_node = (prev_e + 1, prev_e + 2)
            if prev_node not in graph:
                continue
            other_node = (prev_e + 1, prev_e + 2) if node > prev_node else (prev_e, prev_e + 1)
            graph[node].append(other_node)

    mf = UnionFind(len(intervals))
    for node in graph:
        for_nbr = all_parents[node]
        for nei in graph[node]:
            if mf.union(for_nbr, all_parents[nei]):
                graph[nei].remove(node)

    components = {}
    for i in range(len(intervals)):
        node = intervals[i]
        if not any(curr_node == node for curr_node in components):
            components[node] = {i}

        for rc_node in components:
            if not any(nbor_node == rc_node for nbor_node in graph[node]):
                if node == rc_node:
                    continue
                common_nodes = components[rc_node] & components[node]
                if common_nodes:
                    new_bag = components[node] - common_nodes
                    components[rc_node] = components[rc_node] | new_bag
                    del components[node]

    return len(components) - 1
