from collections import defaultdict

def build_graph(intervals):
    nodes = set()
    for start, end in intervals:
        nodes.add(start)
        nodes.add(end)
    nodes = sorted(list(nodes))
    graph = {}
    for i, node in enumerate(nodes):
        graph[i] = []
        for start, end in intervals:
            if start in nodes[i+1:]:
                if end > node:
                    graph[i].append(len(nodes) + (end - node) - 1)
                else:
                    graph[i].append(end - node)
            if end in nodes[i+1:]:
                if start < node:
                    graph[i].append(len(nodes) + (node - start) - 1)
                else:
                    graph[i].append(node - start)
    return nodes, graph

def longest_path(graph):
    n = len(graph)
    dp = [0] * n
    max_len = 0
    for i in range(n):
        for neighbor in graph[i]:
            if neighbor < n:
                dp[i] = max(dp[i], (dp[neighbor] + 1))
            else:
                dp[i] = max(dp[i], (neighbor - i + 1))
        max_len = max(max_len, dp[i])
    return max_len

def solve(intervals):
    nodes, graph = build_graph(intervals)
    m = len(nodes)
    p = longest_path(graph)
    n = len(intervals)
    return n - m + p
