from collections import defaultdict, deque

def solve(n, prerequisites):
    adj = defaultdict(list)
    indeg = [0] * n
    for x, y in prerequisites:
        adj[y].append(x)
        indeg[x] += 1

    stack = deque([i for i in range(n) if indeg[i] == 0])
    ret = []

    def dfs(i):
        for x in adj[i]:
            indeg[x] -= 1
            if indeg[x] == 0:
                stack.append(x)
        yield i
        if not stack:
            yield from map(dfs.__wrapped__, adj[i])
        else:
            yield from dfs(stack.pop())

    if not sum(indeg):
        discard = []
        order = list(dfs(next(iter(stack))))  # Compute ordering
        for x in order:
            if all(y in ret or (y, x) in prerequisites for y in adj[x]):
                ret.append(x)
            else:
                discard.append(x)
        if discard or not sum(indeg):
            return []
        return ret
    return []
