    degrees = [0] * n
    edges = [[] for _ in range(n)]

    for a, b in prerequisites:
        degrees[a] += 1
        edges[b].append(a)

    in_degree = [0] * n
    graph = [[] for _ in range(n)]

    for i in range(n):
        if degrees[i] == 0:
            in_degree[i] = 1
            graph[0].append(i)

    def repeat_source_removal():
        queue = deque()
        for i, degree in enumerate(degrees):
            if degree == 0:
                queue.append(i)
            if in_degree[i] == 1 and len(edges[i]) > 0:
                return None

        if not queue:
            return None

        while queue:
            v = queue.popleft()
            for w in edges[v]:
                degrees[w] -= 1
                in_degree[w] += 1
                if degrees[w] == 0 and in_degree[w] == 1:
                    queue.append(w)
                    in_degree[w] = 0
                    graph[len(queue) - 1].append(w)
        return 1

    for _ in range(len(graph)):
        if repeat_source_removal() is None:
