def solve(n, prerequisites):
    graph = [[-1] * (n + 1) for _ in range(n + 1)]
    indegree = [0] * (n + 1)
    for a, b in prerequisites:
        graph[b][a] = indegree[a] = 1

    def has_source(graph, indegree):
        for i in range(n + 1):
            if indegree[i] == 0:
                return i
        return -1

    def remove_source(graph, indegree, src):
        if isinstance(graph, defaultdict):
            if src in graph:
                del graph[src]
                del indegree[src]
        else:
            for i in range(n + 1):
                graph[i][src] = -1
                indegree[i] = 0
            for i in range(n + 1):
                if graph[i][src] != -1:
                    indegree[i] = 1

    def dfs(graph, indegree, path):
        for node in range(n + 1):
            if indegree[node] == 0:
                path.append(node)
                yield from dfs(graph[node], indegree[node]) or [path]
                path.pop()

    def has_cycle(graph, indegree):
        src = has_source(graph, indegree)
        if src == -1:
            return False
        vis = [False] * (n + 1)
        vis[src] = True
        stack = deque([src])
        while stack:
            node = stack.pop()
            for i in range(n + 1):
                if graph[node][i] != -1 and not vis[i]:
                    stack.append(i)
                    vis[i] = True
                    if indegree[i] > 0:
                        return True
        return False

    res = []
    while n > 0:
        if has_cycle(graph, indegree):
            return []
        src = has_source(graph, indegree)
        remove_source(graph, indegree, src)
        if isinstance(graph, defaultdict) and not graph:
            del graph
        else:
            graph = [row[:-1] for row in graph]
        res = dfs(indegree, n)[0] + res[::-1]
    return res
