            vis[task] = True
            for next_task in graph[task]:
                if not vis[next_task]:
                    dfs(next_task, vis)
                elif not vis[task]:
                    topology_order += 1

            vis[task] = 'vis'
            dfsorder.append(task)

        vis = [False] * n
        vis[task] = True

        dfs(task, vis)
        topo.extend([d for d in reversed(dfsorder) if d >= 0])

        return topo

    return []

    widest_dependency_depth = defaultdict(int)
    dependencies = defaultdict(list)
    nodes = []
    for a, b in prerequisites:
        nodes.append(a)
        nodes.append(b)
        dependencies[a].append(b)
        widest_dependency_depth[a] += 1

    if widest_dependency_depth[n-1] > 0:
        return []
    if all(depth == 0 for depth in widest_dependency_depth.values()):
        return list(range(n))

    stack = [None]
    visited = set()
    widest_ordered = [None] * n
    next_roots = deque()

    while stack:
        n = stack.pop()
        if n is None:
            if not visited:
                visited.clear()
                continue
            widest_ordered[visited[0]] = len(visited)
            depth = deepest_dependency(visited, dependencies)
            if depth == widest_dependency_depth[visited[0]]:
                next_roots.appendleft(visited[0])
            stack.append(None)
        elif n not in visited:
            visited.add(n)
            stack.append(None)
            stack.append(n)

    nodes = deque()
    for leaves in [visited[:depth] for depth in range(widest_ordered[n-1], -1, -1)]:
        for l in leaves:
            nodes.append(l)

    def next_roots_in_set(roots, roots_set):
        for r in roots_set:
            if widest_ordered[r] == widest_ordered[roots[0]]:
                yield r

    def reconstruct(roots, visited):
        if widest_ordered[roots[0]] == 0:
            yield []
        else:
            root_node = next(roots_in_set)
            seen_roots = {r for r in visited}
            sub_paths = list(reconstruct(next_roots_in_set(root_node, visited), visited|{root_node}))
            yield [root_node] + [r for r in sub_paths if r is not None]

    roots = next_roots if next_roots else None
    roots_in_set = next_roots_in_set(roots, visited)
    return reconstruct(roots_in_set, set()) 

def deepest_dependency(root, dependencies):
    stack = [(root, 1)]
    visited = {root}
    depth = 0
    while stack:
        current_descent, depth = stack.pop()
        for e in dependencies[current_descent]:
            if e in visited:
                continue
            visited.add(e)
            stack.append((e, depth + 1))
            depth = max(depth, stack[-1][1])
    return depth
