        order = []
        stack = [0]
        visited[0] = 1

        while stack:
            u = stack.pop()
            order.append(u)
            for v in self.graph[u]:
                if visited[v]:
                    if visited[v] == 1:
                        return []
                else:
                    visited[v] = 1
                    stack.append(v)
                    stack.append(v)

        reverse_order = [0] * self.n
        for i, node in enumerate(order):
            reverse_order[node] = i

        return reverse_order

