    graph = Graph(n)
    for u, v in prerequisites:
        graph.add_edge(v, u)
        R[u] += 1

    topo_order = graph.topsort()

    if not topo_order:
        return []

    stack = topo_order[:]
    while stack and R[stack[-1]] != 0:
        u = stack.pop()
        for v in graph.graph[u]:
            if graph.graph[v]:
                R[v] -= 1

    if stack:
        order = [i for i in range(n)]
        while stack:
            v = stack.pop()
            order[graph.n - len(stack) - 1], order[v] = order[v], order[graph.n - len(stack) - 1]
        return order

    return topo_order

