        self.root = self._create(root)

    def _create(self, intervals):
        if not intervals:
            return None

        intervals.sort(key=lambda x: x[0])
        mid = len(intervals) // 2

        node = Node(intervals[mid][0], intervals[mid][1])
        node.left = self._create(intervals[:mid])
        node.right = self._create(intervals[mid+1:])

        return node

    def _merge(self, a, b):
        return [min(a[0], b[0]), max(a[1], b[1])]

    def _overlap(self, node, query, result):
        if node is None:
            return None

        if query[0] <= node.end and query[1] >= node.start:
            node = self._merge(result, node)
            result = node
            node.left  = self._overlap(node.left,  query, result)
            node.right = self._overlap(node.right, query, result)
        else:
            node.left  = self._overlap(node.left,  query, result)
            node.right = self._overlap(node.right, query, result)

        return node

def solve(intervals):
    intervals.sort(key=lambda x: x[0])
    tree = IntervalTree(intervals)

    result = []
    def traverse(node):
        if node:
            result.append([node.start, node.end])
            traverse(node.left)
            traverse(node.right)

    tree_root = tree.root
    traverse(tree_root)

    return result
