class Node:
    def __init__(self, start, end, left=None, right=None):
        self.start = start
        self.end = end
        self.left = left
        self.right = right

def insert(root, node):
    if root is None:
        return node
    if node.start < root.start:
        root.left = insert(root.left, node)
    else:
        root.right = insert(root.right, node)
    return root

def merge(node):
    if node is None:
        return None
    node.left = merge(node.left)
    node.right = merge(node.right)
    if node.left is None and node.right is not None:
        node.start, node.end = node.right.start, node.right.end
        node.right = None
    elif node.left is not None and node.right is None:
        pass
    elif node.left is None and node.right is None:
        return None
    elif node.left and node.right and node.left.end >= node.right.start:
        node.start = min(node.left.start, node.right.start)
        node.end = max(node.left.end, node.right.end)
        node.right = node.left
        node.left = None
    return node

def flatten(node):
    if node is None:
        return []
    return flatten(node.left) + [[node.start, node.end]] + flatten(node.right)

def solve(intervals):
    root = None
    for start, end in intervals:
        node = Node(start, end)
        root = insert(root, node)
    root = merge(root)
    return sorted(flatten(root))
