        self.right = None

class IntervalTree:
    def __init__(self):
        self.root = None

    def insert(self, node):
        if self.root is None:
            self.root = node
        else:
            self._insert(self.root, node)

    def _insert(self, current, node):
        if node.start < current.start:
            if current.left is None:
                current.left = node
            else:
                self._insert(current.left, node)
        elif node.start > current.end:
            if current.right is None:
                current.right = node
            else:
                self._insert(current.right, node)
        else:
            # merge interval, it's guaranteed to exist here
            if node.end > current.end:
                current.end = node.end
                if current.right is None:
                    current.right = node
                else:
                    self._insert(current.right, node)

def split(current):
    if current is None:
        return current, None, None
    left, right = current.left, current.right
    current.left, current.right = None, None

    lower = None
    higher = left
    while True:
        lower_half = higher.left
        higher_half = higher.right
        if lower_half is None:
            lower = higher
            right = higher_half
            break
        elif higher_half is None:
            lower = higher
            right = higher_half
            break
        elif lower_half.start <= higher_half.end:
            higher = higher_half
        else:
            break
    return lower, higher, right

def merge(lower, higher):
    if lower is None or higher is None:
        return higher if higher is not None else lower
    lower.start = min(lower.start, higher.start)
    lower.end = max(lower.end, higher.end)
    lower.left = merge(lower.left, higher.left)
    lower.right = merge(lower.right, higher.right)
    return lower

def solve(intervals):
    intervals.sort(key=lambda x: x[0])
    tree = IntervalTree()
    for start, end in intervals:
        tree.insert(IntervalNode(start, end))
    merged = []
    stack = [tree.root]
    while stack:
        node = stack.pop()
        if node.left and (node.right and node.left.end > node.right.start or node.right is None):
            lower, higher, right = split(node)
            merged.append([lower.start, lower.end])
            if higher is not None:
                stack.append(higher)
            if right is not None:
                stack.append(right)
        elif node.left and not (node.right and node.left.end > node.right.start):
            stack.append(node)
            stack.append(node.left)
            stack.append(node.right)
        elif node.right and not (node.left and node.right.start <= node.left.end):
            stack.append(node.right)
        elif node.left:
            stack.append(node.left)
        else:
            merged.append([node.start, node.end])
    return merged
