    class Node:
        def __init__(self):
            self.start = 0
            self.end = 0
            self.left = None
            self.right = None
            self.lazy = ()

    def addInterval(self, node, start, end):
        if not node:
            node = self.Node()
            node.start = start
            node.end = end
        if start <= node.start:
            if end > node.start:
                self.addInterval(node.left, start, min(end, node.start))
            self.addInterval(node, max(start, node.start), end)
        else:
            if end > node.end:
                self.addInterval(node.right, start, end)
            self.addInterval(node, start, min(end, node.end))
        self.mergewithLazy(node)

    def add(self, start, end):
        self.addInterval(self.root, start, end)

    def mergewithLazy(self, node):
        if node.lazy:
            start1, end1, start2, end2 = node.lazy
            node.start = min(start1, start2)
            node.end = max(end1, end2)
            node.lazy = ()

    def query(self, start, end):
        result = []
        self.queryh(node=self.root, start=start, end=end, result=result)
        return result

    def queryh(self, node, start, end, result):
        if node is None:
            return True
        if node.lazy:
            start1, end1, start2, end2 = node.lazy
            self.queryh(node.left, start, end, result)
            self.queryh(node.right, start, end, result)
            return True
        if start <= node.start and node.end <= end:
            result.append([node.start, node.end])
            return False
        if start < node.start:
            self.queryh(node.left, start, end, result)
        if end > node.end:
            self.queryh(node.right, start, end, result)
        self.mergewithLazy(node)

def solve(intervals):
    tree = IntervalTree()
    for i, (start, end) in enumerate(intervals):
        tree.add(start, end)
        for prevStart, prevEnd in intervals[:i]:
            if prevEnd > start and prevStart < end:
                tree.addInterval(tree.root, min(prevStart, start), max(prevEnd, end))
                tree.lazy = (prevStart, prevEnd, start, end)
                tree.mergewithLazy(tree.root)
    return tree.query(0, 10000)

