class IntervalTree:
    def __init__(self):
        self.starts = []
        self.ends = []

    def insert(self, start, end):
        if not self.starts or start > self.starts[-1]:
            self.starts.append(start)
            self.ends.append(end)
        else:
            i = binary_search(self.starts, start)
            j = binary_search(self.ends, end)
            while i > 0 and self.starts[i-1] >= start:
                j = max(j, binary_search(self.ends, self.ends[i-1]) + 1)
                self.ends[i-1] = self.ends.pop()
                self.starts[i-1] = self.starts.pop()
                i -= 1
            self.starts.insert(i, start)
            self.ends.insert(i, end)

def merge_overlapping_intervals(intervals):
    intervals.sort()
    result = []
    interval_tree = IntervalTree()

    i = 0
    while i < len(intervals):
        if not result or intervals[i][0] > result[-1][1]:
            result.append(intervals[i])
            interval_tree.insert(intervals[i][0], intervals[i][1])
        elif intervals[i][1] > result[-1][1]:
            start, end = result.pop()
            result.append([start, intervals[i][1]])
            interval_tree.insert(start, intervals[i][1])
        i += 1

    return result

def binary_search(lst, query):
    left, right = 0, len(lst)
    while left < right:
        mid = (left + right) // 2
        if lst[mid] < query:
            left = mid + 1
        else:
            right = mid
    return left
