    current_interval = None
    result = []
    for timestamp, delta, root in events:
        if delta == 1:
            roots.union(root, root + 1)
        else:
            next_root = roots.find(root)
            if current_interval is not None and current_interval != next_root:
                result.append(list(current_interval))
                current_interval = None
            current_interval = (next_root, timestamp)
    if current_interval is not None:
        result.append(list(current_interval))
