class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        xr, yr = self.find(x), self.find(y)
        if xr != yr:
            if self.rank[xr] < self.rank[yr]:
                xr, yr = yr, xr
            if self.rank[xr] == self.rank[yr]:
                self.rank[xr] += 1
            self.parent[yr] = xr

def solve(intervals):
    n = len(intervals)
    interval_idx = [(start, i) for i, (start, end) in enumerate(intervals)]
    interval_idx.sort()
    uf = UnionFind(n)

    result = []
    for (start, i) in interval_idx:
        next_i = uf.find(i) if result else None
        if next_i is None:
            start, end = intervals[i]
            if result:
                prev_end = result[-1][1]
                if start <= prev_end:
                    uf.union(i, result[-1][1])
                    if i != result[-1][1]:
                        start = min(start, result[-1][0])
                        end = max(end, result[-1][1])
                    result.pop()
                else:
                    result.append([start, end])
            else:
                result.append([start, end])
        else:
            prev_start, prev_end = result[next_i]
            last_merged_end = prev_end
            index_end = intervals[next_i][1]
            new_start = min(start, prev_start)
            new_end = index_end
            new_intervals = intervals[next_i:]
            while index_end < end:
                next_interval = (interval_idx.next((i for i in range(n) if uf.find(i) == uf.find(next_i) and index_end < intervals[i][1]))[1])
                new_start = min(new_start, intervals[next_interval][0])
                new_end = max(new_end, intervals[next_interval][1])
                index_end = intervals[new_intervals.pop(0)][1]
            for pair in intervals[new_intervals]:
                result.append(pair)
            if result:
                result.pop(next_i)
            result.insert(next_i, [new_start, new_end])

    return [[interval[0], interval[1]] for group in groupby(result, key=lambda x: x[1]) for interval in group]
