        if first and last:
            return first, last
        l, r = 0, len(nums) - 1
        while l <= r:
            m = (l + r) // 2
            if nums[m] == target:
                if not first or m < first:
                    first = m
                if not last or m > last:
                    last = m
                left, right = m - 1, m + 1
                while left >= 0 and nums[left] == target:
                    first = left
                    left -= 1
                while right < len(nums) and nums[right] == target:
                    last = right
                    right += 1
                return hand_written_binary_search(nums, target, first, last)
            elif nums[m] < target:
                l = m + 1
            else:
                r = m - 1
        return first, last

    return hand_written_binary_search(nums, target)
