            return left, right
        mid = (left + right) // 2
        if nums[mid] == target:
            i = mid
            while i >= 0 and nums[i] == target:
                i -= 1
            while mid < len(nums) and nums[mid] == target:
                mid += 1
            return i + 1, mid - 1 if mid < len(nums) else mid - 1
        elif nums[mid] < target:
            return binary_search(nums, target, mid + 1, right)
        else:
            return binary_search(nums, target, left, mid - 1)

    i, j = 0, len(nums)
    while i < j:
        m = (i + j) // 2
        if nums[m] < target:
            i = m + 1
        else:
            j = m
    if i >= len(nums) or nums[i] != target:
        return [-1, -1]
    l, r = binary_search(nums, target, i, len(nums))
    return [l, r]
