    dp_cache = {len(nums): 0}
    for i in range(len(nums)-1, -1, -1):
        dp_cache[i] = max(dp_cache.get(i+1, 0), max(dp(i) for i in range(i+1, len(nums))))

    max_val = max(nums)
    the_largestOkIdx = [min_val-1]*(max_val-min_val + 1)
    remainSub = [(len(nums)-i-1, dp(i)) for i in range(len(nums))]
    for i in range(len(nums)-1, -1, -1):
        remainSub.insert(0, (len(nums)-i-1, dp(i)))

    for i in range(max_val-min_val+1):
        idx = binary_search(the_largestOkIdx[i:], i + min_val - 1)
        found = remainSub[idx]
        dp_cache[i+min_val-1] += (found[0] if found and found[1] == i else 0)

    return max(dp_cache.values())
