class RangeMinQuery:
    def __init__(self, nums):
        self.n = len(nums)
        self.bit = [0] * (self.n + 1)
        for i, num in enumerate(nums):
            self.update(i, num)

    def update(self, i, val):
        i += 1
        while i <= self.n:
            self.bit[i] = min(self.bit[i], val)
            i += i & -i

    def query(self, i):
        res = float('inf')
        while i > 0:
            res = min(res, self.bit[i])
            i -= i & -i
        return res

    def find_kth(self, k):
        l, r = 0, self.n
        while l < r:
            mid = (l + r) // 2
            if self.query(mid) < k:
                l = mid + 1
            else:
                r = mid
        return l - 1

