import heapq
def heappush(heap, item):
    heap.append(item)
    heapq._siftdown(heap, 0, len(heap)-1)

def heappop(heap):
    return heapq._heappop(heap)

def _siftdown(heap, startpos, pos):
    newitem = heap[pos]
    while pos > startpos:
        parentpos = (pos - 1) >> 1
        parent = heap[parentpos]
        if newitem < parent:
            heap[pos] = parent
            pos = parentpos
            continue
        break
    heap[pos] = newitem
