        return [x == y and x != '*' for x, y in zip(a, b)]
    def partial_match(a, b):
        return match(a, b or ['*'])
    def kmp_with_bad_char(nums, need):
        good = {ch:i for i, ch in enumerate(nums)}
        bad = {ch:i for i, ch in enumerate(nums)}
        i, j = 0, 0
        while j < len(need):
            index = bad.get(need[j], -1)
            while i > index:
                i = good[need[j]]
                if i > index:
                    pattern = need[j+1:]
                    twod = [[False]*len(pattern) for _ in range(len(nums))]
                    pos_start = 0
                    for i, a in enumerate(nums):
                        ismatch = partial_match(a, pattern)
                        for k in range(len(ismatch)):
                            twod[i][pos_start+k] = ismatch[k]

                        for s in range(len(twod[i])):
                            if twod[i][s] and s == 0:
                                return i
                            elif twod[i][s]:
                                twod[i][s] = twod[i][s-1]
                    i -= 1
                    pattern = ''
                    for i in range(j+1, len(need)):
                        if need in nums[i::]: return
                        pattern+=needle[i]
                    i = good[need[j]]
                if i == index: i -= 1
            i += 1
            j += 1
        if (nums[-1] in good.values()) or (needle in nums): return len(needle)-1 if needle in nums else -1
        return -1
    return kmp_with_bad_char(haystack, needle)
