def find_first(s, p):
    if len(p) > len(s):
        return -1
    pre = [0] * len(p)
    j = 0
    for i in range(1, len(p)):
        while j > 0 and p[j] != p[i]:
            j = pre[j-1]
        if p[j] == p[i]:
            j += 1
        pre[i] = j
    i = j = 0
    while i < len(s):
        while j > 0 and s[i] != p[j]:
            j = pre[j-1]
        if s[i] == p[j]:
            j += 1
        if j == len(p):
            return i - j + 1
        i += 1
    return -1
