def solve(haystack, needle):
    def hash_function(s):
        hash_map = {}
        curr_hash = 0
        for i in range(len(s)):
            curr_hash = (curr_hash * 31 + ord(s[i]) - ord('a') + 1) % (10**9 + 7)
            hash_map[i] = curr_hash
        return hash_map

    def rolling_hash(hash_map, s):
        curr_hash = hash_map[len(s) - 1]
        for i in range(len(s) - 1, 0, -1):
            if i < len(s):
                curr_hash = (curr_hash - (10**9 + 7) * ord(s[i - 1]) + ord(s[i]) - ord('a')) % (10**9 + 7)
                hash_map[i - 1] = curr_hash
        return hash_map

    def search(hash_map, s):
        prefix = needle[:len(needle) - 1]
        suffix = needle[1:]
        if len(prefix) == 0:
            return -1
        prefix_hash = hash_function(prefix)[0]
        suffix_hash = hash_function(suffix)[0]
        for i in range(len(haystack) - len(suffix) + 1):
            if hash_map[i] == suffix_hash and haystack[i:i+len(suffix)] == suffix:
                return i
            if i > 0:
                hash_map[i] = (hash_map[i-1] - (10**9 + 7) * ord(haystack[i-1]) + ord(haystack[i])) % (10**9 + 7)
        return -1

    if len(needle) > len(haystack):
        return -1
    hash_map = hash_function(haystack)
    hash_map = rolling_hash(hash_map, haystack)
    return search(hash_map, needle)
