        m, n = len(text), len(pattern)
        j, hits = 0, -1
        for i in range(m):
            if pattern[j] == text[i]:
                j += 1
                if j == n:
                    hits = i - n + 1
                    break
            else:
                if j > 0:
                    j = lps[j - 1]
                else:
                    i += 1
        return hits

    max_len = min(len(haystack), len(needle))
    if max_len == len(needle):
        return -1 if needle not in haystack else haystack.index(needle)
