def solve(nums):
    def get_prefix_hash_values(arr):
        prefix_hash = [0]
        prefix_hash_values = [-1] * len(arr)
        for i in range(len(arr)):
            prefix_hash.append((prefix_hash[-1] ^ arr[i]) & 0xFFFFFFFF)
        for i in range(len(arr)):
            prefix_hash_values[prefix_hash[i] & 0xFFFFFFFF] = i
        return prefix_hash_values

    def get_suffix_hash_values(arr):
        prefix_hash_values = get_prefix_hash_values(arr[::-1])[::-1]
        n = len(arr)
        suffix_hash_values = [-1] * n
        for i in range(n):
            suffix_hash_values[prefix_hash_values[i] & 0xFFFFFFFF] = n - 1 - i
        return suffix_hash_values

    def get_hash_collision(arr, n):
        prefix_hash_values = get_prefix_hash_values(arr)
        suffix_hash_values = get_suffix_hash_values(arr)
        for i in range(n):
            prefix_index = prefix_hash_values[i & 0xFFFFFFFF]
            suffix_index = suffix_hash_values[i & 0xFFFFFFFF]
            if prefix_index != suffix_index and prefix_index != -1 and suffix_index != -1:
                return max(prefix_hash_values[i & 0xFFFFFFFF], suffix_hash_values[i & 0xFFFFFFFF])

    n = len(nums)
    prefix_hash = [0]
    for i in range(1, n + 1):
        prefix_hash.append((prefix_hash[-1] ^ i) & 0xFFFFFFFF)
    repeated_value = get_hash_collision(prefix_hash, n)
    if repeated_value == -1:
        return -1
    for i in range(n):
        if nums[i] == repeated_value:
            return repeated_value
    return -1
