    Returns the number of connected components of an undirected graph.

    :param n: Number of nodes in the graph.
    :param edges: List of pairs [u, v] representing edges between nodes.
    :return: Number of connected components.
    """
    parent = list(range(n))

    def find(u):
        if parent[u] != u:
            parent[u] = find(parent[u])
        return parent[u]

    def union(u, v):
        root_u = find(u)
        root_v = find(v)
        if root_u != root_v:
            parent[root_u] = root_v

    for u, v in edges:
