class Matrix:
    def __init__(self, m, n):
        self.m = m
        self.n = n
        self.data = [[0 for _ in range(n)] for _ in range(m)]

    def __mul__(self, other):
        m, n = self.m, self.n
        p, q = other.m, other.n
        result = Matrix(m, q)
        for i in range(m):
            for j in range(q):
                for k in range(n):
                    result.data[i][j] += self.data[i][k] * other.data[k][j]
        return result

    def identity(self, n):
        for i in range(n):
            self.data[i][i] = 1

    def power(self, k):
        if k == 1:
            return self
        half_pow = self.power(k >> 1)
        if k & 1:
            return half_pow * half_pow * self
        else:
            return half_pow * half_pow

def solve(n):
