        result = pair(matrix_power(add=add_scalar, a), p)
        return tuple(map(int, (result[0] * result[3] + result[1] * result[2], result[0] * result[2], result[0] * result[1], result[3] * result[3] + result[2] * result[2])))

    if n <= 1: return n
    fib_pair = tuple((1, 1, 0, 1))
