    left_sum = float('-inf')
    curr_sum = 0
    for i in range(mid, low - 1, -1):
        curr_sum += arr[i]
        if (curr_sum > left_sum):
            left_sum = curr_sum
    right_sum = float('-inf')
    curr_sum = 0
    for i in range(mid + 1, high + 1):
        curr_sum += arr[i]
        if (curr_sum > right_sum):
            right_sum = curr_sum
    return left_sum + right_sum

def max_subarray_sum(arr):
