        while left < right:
            mid = left + (right - left) // 2
            if nums[mid] <= target:
                left = mid + 1
            else:
                right = mid
        return left - 1 if left > 0 and nums[left - 1] == target else -1

    left = find_left(nums, target)
    right = find_right(nums, target)
    return [left, right] if left != -1 and right != -1 else [-1, -1]
