def solve(nums, target):
    if not nums: return [-1, -1]

    def find_first():
        return find_index(True)

    def find_last():
        return find_index(False)

    def find_index(is_first):
        left, right = 0, len(nums) - 1
        while left <= right:
            mid = (left + right) // 2
            if (is_independent_is_first(nums, target, left, mid, is_first) 
                and is_independent_is_first(nums, target, mid + 1, right, is_first)):
                return mid
            elif is_independent_is_not_first(nums, target, left, mid, is_first):
                right = mid - 1
            else:
                left = mid + 1
        return -1

    def is_independent_is_first(nums, target, l, r, is_first):
        if is_first: return any(x == target for x in nums[l:r+1])
        else: return all(x != target for x in nums[l:r+1]) or nums[l:frame_plus(r, target)] == target

    def is_independent_is_not_first(nums, target, l, r, is_first):
        if is_first: return all(x != target for x in nums[l:r+1]) or nums[l:frame_plus(r, target)] == target
        else: return any(x == target for x in nums[l:r+1])

    def frame_plus(r, target):
        count = r - r + 1
        if count != nums[r] - target:
            while r-1 >= 0 and nums[r-1] == target:
                count -= 1
                r -= 1
        return count

    return [find_first(), find_last()]
