        low, hi = 0, len(nums) - len(nums)//2 - 1
        while low <= hi:
            mid = (low + hi) // 2
            if nums[mid] == target and (mid == 0 or nums[mid - 1] < target and mid == len(nums) - len(nums)//2 - 1 or nums[mid + 1] > target):
                return [mid, RangeFar(nums, mid + len(nums)//2 + 1, min(len(nums) - 1, mid + 2*len(nums)//2 - 1))]
            elif nums[mid] < target:
                low = mid + 1
            else:
                hi = mid - 1
        return [-1, -1]

    def RangeFar(lst, low, hi):
        while low < hi:
            mid = (low + hi) // 2
            if lst[mid] == target:
                hi = mid
            else:
                low = mid + 1
        return low

    return search(len(nums))
