def solve(nums):
    def find_min_end_for(i, k, dp):
        for j in range(k):
            if nums[j] > nums[i] and (dp[i][1] == -1 or dp[j][1] >= dp[i][1]):
                dp[i][1] = dp[j][1] + 1
                dp[i][0] = min(dp[i][0], dp[j][0])
        dp[i][0] = min(dp[i][0], 1)
    def incmnt(dp):
        n = len(dp)
        g = [[float('inf')] * 2 for _ in range(n)]
        increase_vals = [float('-inf')] * n
        for i in range(n): 
            minend = -1
            mincost = dp[i][0] 
            for j in range(i-1, -1, -1):
                if nums[i] > nums[j] and dp[j][1] >= minend: 
                    if dp[j][0] < mincost: 
                        mincost = dp[j][0] 
                        minend = dp[j][1]
                    elif dp[j][0] == mincost and dp[j][1] < minend:
                        minend = dp[j][1]
            g[i][0] = mincost  
            g[i][1] = minend 
            increase_vals[i] = nums[i] if minend != -1 else g[i][0] + 1
        new_dp = [[float('inf')] * 2 for _ in range(n)]
        new_dp[n-1] = g[n-1]
        for k in range(n - 2, -1, -1):
            find_min_end_for(k, n, new_dp)
        return new_dp

    dp = [[float('inf')] * 2 for _ in range(len(nums))]
    increase_dp = [[float('inf')] * 2 for _ in range(len(nums))]
    new_dp = increase_dp
    final = [[float('inf')] * 2 for _ in range(len(nums))]
    for i in range(len(nums)):
        find_min_end_for(i, len(nums), final)
        if i == len(nums) - 1: break
        new_dp = incmnt(new_dp)
        for j in range(i-1, -1, -1):
            if nums[i] > nums[j] and final[j][1] > new_dp[i][1]:
                new_dp[i][1] = final[j][1]
                new_dp[i][0] = min(final[j][0], new_dp[i][0])
        new_dp[i][0] = min(new_dp[i][0], 1)
    increase_vals = [nums[i] + 1 if num != float('inf') else float('inf') for i, num in enumerate(increase_dp[0])]
    min_not_increasing = min(increase_vals)
    max_length = -1
    for end in range(len(nums)): 
        if min_not_increasing <= nums[end]: 
            break
        max_length = max(max_length, new_dp[end][1] + 1)
    return max_length
