        anchor_index = random.randint(lo, hi)
        nums[anchor_index], nums[hi] = nums[hi], nums[anchor_index]
        anchor = nums[hi]

        i = lo - 1
        for j in range(lo, hi):
            if nums[j] < anchor:
                i += 1
                nums[j], nums[i] = nums[i], nums[j]
        nums[i + 1], nums[hi] = nums[hi], nums[i + 1]
        return i + 1

    def quickselect(nums, lo, hi, k):
        if lo == hi:
            return nums[lo]
        pivot = randompartition(nums, lo, hi)
        if k == pivot + 1:
            return nums[pivot]
        elif k < pivot + 1:
            return quickselect(nums, lo, pivot - 1, k)
        else:
            return quickselect(nums, pivot + 1, hi, k)

    if not nums:
        return None
    return quickselect(nums, 0, len(nums) - 1, k)
