def quickselect(nums, k, start):
    if not nums:
        return None
    pivot_index = partition(nums, start)
    if k == pivot_index + start + 1:
        return nums[pivot_index]
    elif k < pivot_index + start + 1:
        return quickselect(nums[:pivot_index], k, start)

def partition(nums, start):
    pivot = random.randrange(start, len(nums))  # choose a random pivot
    nums[start], nums[pivot] = nums[pivot], nums[start]
    i = start + 1
    for j in range(start + 1, len(nums)):
        if nums[j] < nums[start]:
            nums[i], nums[j] = nums[j], nums[i]
            i += 1
    nums[start], nums[i - 1] = nums[i - 1], nums[start]
    return i - 1
