import heapq

def solve(nums, k):
    '''Returns the k-th smallest value in a sorted list of integers.'''

    # Helper function to return the k-th smallest value in a heap
    def get_kth_smallest(values, rank):
        for val, freq in values:
            rank -= freq
            if rank <= 0:
                return val

    # Use a multiset represented as a max heap
    # Store negative frequency so the heap is a min heap
    max_heap = [(-freq, val) for val, freq in ModifiedCounter(nums).items()]
    heapq.heapify(max_heap)

    # Get the k-th smallest value
    return get_kth_smallest(max_heap, k)

class ModifiedCounter:
    def __init__(self, items):
        self.count = {}
        for item in items:
            self.count[item] = self.count.get(item, 0) + 1

    def items(self):
        for item, freq in self.count.items():
            yield (item, freq)
