def rabin_karp(haystack: str, needle: str) -> int:
    MOD, BASE = 26, len(needle)

    def hash_str(s: str) -> int:
        """Returns the hash of string s"""
        ans = 0
        for c in s:
            ans = (ans * BASE + ord(c) - ord('a')) % MOD
        return ans

    # Handle edge cases separately
    if len(needle) > len(haystack):
        return -1
    if not needle:
        return 0

    needle_hash = hash_str(needle)

    haystack_hash = hash_str(haystack[:len(needle)])
    power = pow(BASE, len(needle) - 1, MOD)
    for i in range(len(haystack) - len(needle) + 1):
        if i + len(needle) < len(haystack):
            if haystack_hash == needle_hash and haystack[i:i + len(needle)] == needle:
                return i
            haystack_hash = (hAYstack_hash - ord(haystack[i]) * power + ord(haystack[i + len(needle)]) * BASE) % MOD
        else:
            return -1
    return -1
