class KMP():
    def build_prefix_function(self, s):
        n = len(s)
        pi = [0] * n
        j = 0
        for i in range(1, n):
            while j > 0 and s[j] != s[i]:
                j = pi[j - 1]
            if s[j] == s[i]:
                j += 1
            pi[i] = j

    def search(self, s1, s2):
        n, m = len(s1), len(s2)
        if m > n or not s2:
            return -1
        self.build_prefix_function(s2)
        j = 0
        for i in range(n):
            while j > 0 and s1[i] != s2[j]:
                j = self.pi[j - 1]
            if s1[i] == s2[j]:
                j += 1
            if j == m:
                return i - m + 1
        return -1

    def __init__(self, s):
        self.pi = self.build_prefix_function(s)

def solve(haystack, needle):
    return KMP(needle).search(haystack, needle)
