    suffixArray = kmpSuffixArray(needle)
    for i in range(len(haystack)):
        for j in range(len(needle)):
            if i + j >= len(haystack):
                break
            if pace[ord(haystack[i + j]) - ord('a')] & (1 << j):
                sandwich[j + 1] = i
                break
        else:
            continue
        break
    if i + j < len(haystack):
        position = sandwich[suffixArray[j]] + 1
        while j and position < len(haystack):
            if haystack[position] == needle[j]:
                j -= 1
                position += 1
            else:
                j = suffixArray[j-1]
