def solve(nums):
    def mod_inverse(a, m):
        t = 0
        newt = 1
        r = m
        newr = a
        while newr != 0:
            quotient = r // newr
            t, newt = newt, t - quotient * newt
            r, newr = newr, r - quotient * newr
        if r > 1:
            return None
        if t < 0:
            t += m
        return t

    def get_coprime_length(m):
        Phi = (m - 1 + mod_inverse(m, m - 1) * m) // 2  # Euler's criterion
        return Phi

    n = len(nums)
    m = n + 1
    m_duplicate = 1

    for i in range(1, m):
        if get_coprime_length(m) % i != 0:
            m_duplicate *= i

    A = 0
    B = 0
    for i in range(n):
        A = (A + m_duplicate * nums[i]) % m
        B = (B + m_duplicate * i) % m

    X = (m - (A - B)) % m

    pow_A = 1
    pow_n = mod_inverse(m_duplicate, m)
    for _ in range(X):
        pow_A = (pow_A * m_duplicate) % m

    pow_n_A = 0
    for i in range(n):
        if i >= X:
            pow_n_A = (pow_n_A + nums[i] - pow_A) % m

    return abs(pow_n_A)
