def prefix_sum(nums):
    prefix = [0]
    for num in nums:
        prefix.append(prefix[-1] + num)
    return prefix

def binary_search(prefix, target, start, end):
    while start <= end:
        mid = start + (end - start) // 2
        if prefix[mid] == target:
            return mid
        elif prefix[mid] < target:
            start = mid + 1
        else:
            end = mid - 1
    return end

def solve(nums, target):
    prefix = prefix_sum(nums)
    index = binary_search(prefix, target, 1, len(prefix) - 1)
    i = index - 1
    while i >= 1 and prefix[i] < target:
        i -= 1
    j = index
    while j < len(prefix) - 1 and prefix[j] > target:
        j += 1
    return [i, j]
