def UnionFind(n):
    parents = list(range(n))
    sizes = [1] * n
    def find(x):
        if parents[x] != x:
            parents[x] = find(parents[x])
        return parents[x]
    def union(x, y):
        x_root = find(x)
        y_root = find(y)
        if x_root == y_root:
            return
        if sizes[x_root] < sizes[y_root]:
            x_root, y_root = y_root, x_root
        parents[y_root] = x_root
        sizes[x_root] += sizes[y_root]
    return find, union, sizes

