class Solution:
    def solve(self, intervals):
        def compare(i, j):
            if intervals[i][1] < intervals[j][1]:
                return i
            elif intervals[i][1] > intervals[j][1]:
                return j
            else:
                return i if intervals[i][0] < intervals[j][0] else j

        def sort_references(reference, arr):
            i = 0
            references = [-1]*len(arr)
            references[reference] = 0
            for j in range(1, len(arr)):
                x = arr[compare(j-1, j)]
                while i > 0 and compare(i-1, j) > compare(i-1, x):
                    references[compare(i-1, x)] = compare(i-1, x)
                    i -= 1
                references[compare(j-1, j)] = j
                i += 1
            return references

        intervals_ranges = sorted(range(len(intervals)), key=lambda x: intervals[x][0])
        stack = [0]
        intervals_references = [None]*len(intervals)

        for i in intervals_ranges[1:]:
            while intervals[stack[-1]][1] > intervals[i][0]:
                intervals_references[stack.pop()] = i
            stack.append(i)

        count, remaining = 0, 0
        while stack:
            j = stack.pop()
            start = intervals[j][0]
            while remaining < len(stack) and intervals[stack[remaining]][0] <= start:
                count += 1
                remaining += 1
            start = intervals[j][1]
            while remaining < len(stack) and intervals[stack[remaining]][0] <= start:
                count += 1
                remaining += 1

        for i in intervals_references:
            if i is not None:
                count += 1

        return count
