def convex_hull_topo(graph):
    """Computes the topological sort of a planar graph given its vertices and edges."""
    sta = []
    while graph:
        for src in graph:
            if not graph[src]:
                sta.append(src)
                for neighbor in graph:
                    graph[neighbor].remove(src)
                graph.pop(src)
                break
        if not graph:
            raise ValueError("Cycle detected")
    return sta

def solve(intervals):
    def orientation(p, q, r):
        val = (q[1] - p[1]) * (r[0] - q[0]) - (q[0] - p[0]) * (r[1] - q[1])
        if val == 0:
            return 0
        return 1 if (val > 0) else -1

    def in_rect(point, rect):
        x0, y0, x1, y1 = rect
        return (x0 <= point[0] and point[0] <= x1) and (y0 <= point[1] and point[1] <= y1)

    n = len(intervals)
    points = [(a, b, True) for a, b in intervals] + [(b, a, False) for a, b in intervals]
    points.sort()

    hull = []
    for p in points:
        while len(hull) > 1:
            q = hull[-2]
            r = hull[-1]
            if orientation(q, r, p) == 0 or p[0] == q[0]:
                break
            hull.pop()
        hull.append(p)

    intersecting = []
    for p in hull:
        rect = p[:2]
        for q in hull[hull.index(p) + 1:]:
            if q[2] == p[2]:
                intersecting.append((max(rect[0], q[0]), min(rect[1], q[1])))
            else:
                intersecting.append((max(rect[0], q[0]), min(rect[1], q[1])))
                intersecting.append((max(rect[0], q[1]), min(rect[1], q[0])))

    graph = dict()
    for interval in intersecting:
        a = interval[0]
        b = interval[1]
        intersection_points = []
        for c, d in intersecting:
            if interval != (c, d) and in_rect((a, b), (c, d)):
                intersection_points.append((c, d))
        graph[a] = set(x for x in intersection_points if b < x[0])
        graph[b] = set(x for x in intersection_points if a > x[1])

    return len(convex_hull_topo(graph)) - n
