def prefix_sum_benefit(arr):
    n = len(arr)
    ps = [0] * (n + 1)
    for i in range(1, n):
        ps[i+1] = ps[i] + (0 if (ps[i] > arr[i] or arr[i] == 0) else arr[i] - ps[i])

    return min(ps[1:])

def total_prefix_sum_benefit(arr):
    result = 0
    dp = [[i for i in range(len(arr)+1)] for _ in range(len(arr)+1)]
    for n in range(1, len(arr)+1):
        for i in range(n, 0, -1):
