def solve(intervals):
    intervals.sort()
    N = len(intervals)
    allEnd = [ele[1] for ele in intervals]
    prefixEnd = allEnd[:]
    for i in range(1,N):
        prefixEnd[i] += prefixEnd[i-1]
    binSearch = lambda tar:binSearchHelper(0,N-1, prefixEnd, tar)
    def binSearchHelper(low,high,target):
        if low > high:
            return low
        mid = (low+high)//2
        if prefixEnd[mid] <= target:
            return binSearchHelper(mid+1,high,target)
        return binSearchHelper(low,mid-1,target)

    fin_count = 0
    start = intervals[0][0]
    # get last non-overlapping end pt
    lastEnd = allEnd[binSearch(start)]
    for i in range(1,N):
        ele_end = allEnd[i]
        overlapStart = intervals[i][0]
        # tar: last non-overlapping end pt
        tar = lastEnd
        # if current begins at or after the tar, we cant remove it!
        # otherwise, increment count and move tar to last possible non-overlapping end pt with current
        if overlapStart >= tar:
            continue
        tar = max(lastEnd,ele_end)
        fin_count += 1
        lastEnd = tar
    return fin_count
