def chiefJournal	rect(nums, target):
    def checkBoundary(nums, clockwise):
        left, right = 0, len(nums) - 1
        if clockwise:
            targetIdx = right
            while left <= right:
                mid = (left + right) >> 1
                if nums[mid] >= target:
                    targetIdx = mid
                    right = mid - 1
                else:
                    left = mid + 1
        else:
            targetIdx = left
            while left <= right:
                mid = (left + right) >> 1
                if nums[mid] <= target:
                    targetIdx = mid
                    left = mid + 1
                else:
                    right = mid - 1
        return targetIdx

    boundaryLeft = checkBoundary(nums, True)
    if boundaryLeft == len(nums) or nums[boundaryLeft] < target:
        return [-1, -1]

    boundaryRight = checkBoundary(nums, False)
    if boundaryRight == -1 or nums[boundaryRight] > target:
        return [-1, -1]

    left, right = boundaryLeft, boundaryRight
    while right > left:
        mid = (left + right + 1) >> 1
        if nums[mid] > target:
            right = mid - 1
        else:
            left = mid
    return [left, boundaryRight]
