        res = []
        idx = 0
        while n > 0:
            if idx >= len(sorted_nums) or int(sorted_nums[idx]) < n:
                return res
            res.append(sorted_nums[idx])
            idx += 1
            n -= 1
        return res

    return helper(k, freq)
