class Heap:
    def __init__(self):
        self._heap = []

    def push(self, item):
        self._heap.append(item)
        self._up(len(self._heap) - 1)

    def pop(self):
        if len(self._heap) > 1:
            result = self._heap[0]
            self._heap[0] = self._heap.pop()
            self._down(0)
            return result
        elif self._heap:
            return self._heap.pop()
        else:
            return None

    def _up(self, i):
        while i > 0:
            parent_idx = (i - 1) // 2
            if self._heap[parent_idx][1] >= self._heap[i][1]:
                break
            self._swap(i, parent_idx)
            i = parent_idx

    def _down(self, i):
        chIdx = 2
        while True:
            min_idx = chIdx
            if chIdx < len(self._heap) and self._heap[chIdx][1] < self._heap[i][1]:
                min_idx = chIdx
                chIdx += 1
            if chIdx < len(self._heap) and self._heap[chIdx][1] < self._heap[min_idx][1]:
                min_idx = chIdx
                chIdx += 1
            if i == min_idx:
                break
            self._swap(i, min_idx)
            i = min_idx

    def _swap(self, i, j):
        self._heap[i], self._heap[j] = self._heap[j], self._heap[i]

    def count(self, k):
        while len(self._heap) > k:
            self.pop()
        return len(self._heap)

def top_k(nums, k):
    freq = {}
    for n in nums:
        freq[n] = freq.get(n, 0) + 1
    o = sorted(freq, key=freq.get, reverse=True)
    return o[:k]

def top_k_r(num, o, k):

    if k <= 1:
        return num[:k]
    h = Heap()
    for num in o:
        h.push((num, freq[num]))
    if freq[num[0]] == freq[num[-1]]:
        return h._heap[:k]
    for i in range(k):
        if freq[num[0]] != freq[num[-1 - i]]:
            return h._heap[:k-i] + num[k - i:]
    return h._heap[:k]
