def partition(nums, i, s):
    pivot = nums[i]
    smaller = [nums[j] for j in range(i+1, s) if nums[j] < pivot]
    larger = [nums[j] for j in range(i+1, s) if nums[j] >= pivot]
    nums[i+1:s] = smaller + larger
    return i + 1

def quickselect_quicksort(nums, k, i=0, s=None):
    s = len(nums) if s is None else s
    if s == 1:
