def heapify_external(nums, i, n):
    left_child = 2 * i + 1
    right_child = 2 * i + 2
    largest = i
    if left_child < n and nums[i] < nums[left_child]:
        largest = left_child
    if right_child < n and nums[largest] < nums[right_child]:
        largest = right_child
    if largest != i:  # not knuth shuffle where largest child is inserted at largest index
        nums[i], nums[largest] = nums[largest], nums[i]
        heapify_external(nums, largest, n)

