    return distinct_nums[bisect.bisect_left(distinct_nums, nums[0]) + k - 1]

def insert_sort(nums: List[int]) -> None:
    for i in range(1, len(nums)):
        key = nums[i]
        j = i - 1
        while j >= 0 and nums[j] > key:
            nums[j + 1] = nums[j]
            j -= 1
        nums[j + 1] = key

def binary_search(nums: List[int], target: int) -> int:
    left, right = 0, len(nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return left

def sorted_arr(nums: List[int]) -> List[int]:
    insert_sort(nums)
    return nums

def bisect_left(nums: List[int], num: int) -> int:
    return binary_search(sorted_arr(nums), num)
