    max_index = len(haystack) - len(needle)
    fermat_primes = [2, 3, 5]
    for x in range(2, len(needle)):
        good = True
        for p in fermat_primes:
            if not fermat(x):
                good = False
                break
        if good:
            fermat_primes.append(x)

    for base in fermat_primes:
        if max_index < 0:
            break
        poly_sub = [0] * (len(needle) + 1)
        poly_sub[-1] = 1
        poly_hay = [0] * len(haystack)
        for j in range(max_index, -1, -1):
            i = j + len(needle) - 1
            poly_hay[i] = haystack[i]
            n = needles[i % len(needle)]
            for k in range(len(needle) - 1, -1, -1):
                delta = (poly_sub[k + 1] - (n - poly_sub[k]) * 
                         base**((i + k) % len(needle))) % base 
                poly_hay[i - 1] = deltamod = delta % base
                n = hay[i - 1] = haystack[i - 1]
                poly_sub[k] = delta
            if deltamod == needle[-1]:
                break        
        if all(map(lambda x,y: x==y, needle, poly_hay)):
            return j
        max_index -= 1
    return -1

