def nextGap(gap):
    if gap == 0:
        return 0
    beta = (gap // 2)
    alpha = 1 if gap & 1 else 0
    return max(nextGap(beta), gap - beta + alpha)

def kmp_algorithm(haystack, needle):
    m = len(needle)
    if m == 0 or m > len(haystack):
        return -1
    next_table = [0] * m
    j = 0
    for i in range(1, m):
        l_jump = nextGap(i - j)
        if i + l_jump >= m:
            j = i
        next_table[i] = j
        if needle[j] == needle[i]:
            j += 1
    i = j = 0
    while i < len(haystack) and j < m:
        if haystack[i] == needle[j]:
            i += 1
            j += 1
        if j == m:
            return i - j
        l_jump = nextGap(j - i)
        if j + l_jump >= m:
            j = next_table[j - 1]
        else:
            i += l_jump
    return -1

def solve(haystack, needle):
    return kmp_algorithm(haystack, needle)
