def solve(haystack, needle):
    def rolling_hash(haystack, needle_len):
        h_prefix = 0
        alphabet = 26
        for c in needle:
            h_prefix = (h_prefix * alphabet + ord(c) - ord('a')) % 2**32
        h_suf = 0
        hash_set = set()
        for i in range(len(haystack) - needle_len + 1):
            for j in range(i, i + needle_len):
                h_suf = (h_suf * alphabet + ord(haystack[j]) - ord('a')) % 2**32
                if h_suf == h_prefix:
                    hash_set.add(i)
            if i > 0:
                h_suf = (h_suf - (ord(haystack[i - 1]) - ord('a')) * alphabet**needle_len) % 2**32
                if h_suf < 0:
                    h_suf += 2**32
                if not haystack[i - 1].islower():
                    h_suf += 2**32
                if i - 1 in hash_set:
                    hash_set.remove(i - 1)
    rolling_hash(haystack, len(needle))
    return list(hash_set).pop(0) if hash_set else -1
