            return nums[i - 1]
        if i > 1 and nums[i - 2] == nums[i - 1]:
            return nums[i - 1]
        if i < n and nums[i + 1] == i:
            diff.add(nums[i])
        uf.union(nums[i - 1], i)
    return uf.find(n)
