        root2 = find(node2)
        if root1 != root2:
            if counts[root1] >= counts[root2]:
                roots[root2] = root1
                counts[root1] += counts[root2]
                counts[root2] = 0
            else:
                roots[root1] = root2
                counts[root2] += counts[root1]
                counts[root1] = 0
    return roots, find, union

