def solve(n, edges):
    parents = list(range(n))
    rank = [0] * n
    def find(x):
        if parents[x] != x:
            parents[x] = find(parents[x])
        return parents[x]
    def union(x, y):
        root_x, root_y = find(x), find(y)
        if root_x == root_y:
            return
        if rank[root_x] > rank[root_y]:
            parents[root_y] = root_x
        else:
            parents[root_x] = root_y
            if rank[root_x] == rank[root_y]:
                rank[root_y] += 1
    for edge in edges:
        union(*edge)
    return len(set(find(x) for x in range(n)))
