def evaluate(intervals, partition_id, dp):
    if partition_id == len(intervals):
        return 0
    if dp[partition_id] is not None:
        return dp[partition_id]

    remove = 1 + evaluate(intervals, partition_id + 1, dp)
    not_remove = float('inf')
    for i in range(partition_id + 1, len(intervals)):
        end = intervals[i][1]
        if intervals[partition_id][1] <= end:
