@specialize
def toposort(graph):
    if not graph:
        return []
    in_degree = {u: 0 for u in graph}
    for vcs in graph.values():
        for v in vcs:
            in_degree[v] += 1
    q, stack = deque([u for u in in_degree if in_degree[u] == 0]), []
    while q:
        u = q.popleft()
        stack.append(u)
        for v in graph.get(u, ()):
            in_degree[v] -= 1
            if in_degree[v] == 0:
                q.append(v)
    if len(stack) != len(in_degree):
        raise InvalidScheduleError
    return stack

