    return order if len(order) == n else []

def solve(n, prerequisites):
    graph = defaultdict(list)
    for a, b in prerequisites:
        graph[b].append(a)
    def is_valid(graph, path, visited):
        for node in graph:
            if node not in path and any(p in path for p in graph[node]):
                return False
        return True
    def dfs(graph, node = None, path = [], visited = set()):
        if not node:
            node = path[-1] if path else 0
        if len(path) == n:
            return path
        visited.add(node)
        for child in [p for p in graph[node] if p not in visited]:
            if dfs(graph, child, path+[child], visited):
                return path+[child]
            visited.remove(child)
        return []
    return dfs(graph) if is_valid(graph, [], set()) else solver(n, prerequisites)
