from collections import defaultdict, deque

def solve(n, prerequisites):
    require = defaultdict(list)
    chosen = [None]*n

    for a, b in prerequisites:
        require[a].append(b)
        chosen[b] = True

    def valid(a):
        return False if chosen[a] else all(chosen[b] for b in require[a])

    def topsort():
        stack = deque([i for i in range(n) if valid(i)])

        top = []
        considered = set()

        while stack:
            u = stack.pop()
            if u not in considered:
                top.append(u)
                considered.add(u)
                for v in require[u]:
                    if valid(v) and v not in considered:
                        stack.append(v)

        if len(top) == n:
            return top
        return None

    return topsort()
