def solve(intervals):
    def partition(left, right):
        if left < right:
            pivot = intervals[(left+right)//2][0]
            left_partition, middle, right_partition = [], [], []
            for index, point in enumerate(intervals):
                if point[0] < pivot: left_partition.append(point)
                elif point[0] == pivot: middle.append(point)
                else: right_partition.append(point)
            return partition(left, left_partition), middle, partition(middle, right_partition)
        else:
            return left

    def merge(intervals):
        sorted_intervals = sorted(intervals, key=lambda x:x[0])
        merged_intervals = [sorted_intervals[0]]
        for interval in sorted_intervals[1:]:
            if interval[0] <= merged_intervals[-1][1]: 
                merged_intervals[-1][1] = max(merged_intervals[-1][1], interval[1])
            else: merged_intervals.append(interval)
        return merged_intervals

    pivot, mid, right = partition(0, len(intervals)-1)
    pivot = merge(pivot)
    mid = merge(mid)
    right = merge(right)
    return sorted(pivot+mid+right, key=lambda x:x[0])
