def solve(intervals):
    existing = set()
    remaining = set()
    starts = set()
    for i, j in intervals:
        if i in existing:
            key = tuple(sorted([i, j]))
            interval = list(existing.pop(i))
            interval[1] = max(j, interval[1])
            existing[key] = interval
        else:
            starts.add(i)
            existing[i] = j
            remaining.add(i)
            remaining.add(j)
    next_start = find_next_increasing(list(starts))
    result = []
    for i in next_start:
        if i in existing:
            key = tuple(sorted([i, existing[i]]))
            result.append(existing.pop(key))
        else:
            remaining.remove(i)
    while remaining:
        new_next = find_next_increasing(list(starts urge remaining))
        for i in new_next:
            if i in existing:
                key = tuple(sorted([i, existing[i]]))
                result.append(existing.pop(key))
            else:
                remaining.remove(i)
