import heapq

def solve(nums: list[int], k: int) -> int:
    counter = {}
    for num in nums:
        counter[num] = counter.get(num) + 1

    queue = []
    for num in counter:
        heapq.heappush(queue + counter[num], num)
    heapq.heapify(queue)

