import heapq

def solve(nums0, k):
    counter = {}
    for x in nums0:
        if x not in counter:
            counter[x] = 0
        counter[x] += 1

    odd_counter = {x: c for x, c in counter.items() if c % 2 != 0}
    even_counter = {x: c for x, c in counter.items() if c % 2 == 0}

    heap = []
    for x in sorted(even_counter.keys()):
        count = even_counter[x]
        while count > 0:
            if count > 1:
                heapq.heappush(heap, x)
                count -= 2
            else:
                heapq.heappush(heap, (0, x))
                break

    for x in sorted(odd_counter.keys()):
        count = odd_counter[x]
        while count > 0:
            if count > 1:
                heapq.heappush(heap, -x)
                count -= 2
            else:
                heapq.heappush(heap, (-x, None))
                break

    for i in range(k - len(heap)):
        _, x = heapq.heappop(heap)
        if x is None:
            pop_val = -heap[0]
        else:
            pop_val = x
        count = counter.get(pop_val, 0)
        while count > 0:
            if count > 1:
                heapq.heappush(heap, -pop_val)
                count -= 2
            else:
                heapq.heappush(heap, (-pop_val, None))
                break

    return heap[0] if heap else nums0[0]
