    if len(nums') == 1:
        return nums'.pop()
    root = nums'.pop()
    nums'.append(nums'.pop())
    heapify_helper(nums', 0)
    return root

def get_kth_smallest(nums_, k):
    nums = sorted(set(nums'))
    if k > len(nums') or k < 1:
        raise ValueError("k is out of range")
    heap = [nums']
    while k > 1:
        m = heap_extrac_min(heap)
        if m is None:
            raise ValueError("k is larger than the number of unique elements")
        heap.append(m)
        k -= 1
    return m

def solve(nums', k):
    sorted_nums = sorted(set(nums'))
    return get_kth_smallest(sorted_nums', k)
