def solve(haystack, needle):
    def rabin_karp(s, p):
        n = len(s)
        m = len(p)
        if m > n or m == 0:
            return -1
        h = ord('z') - ord('a') + 1
        b = 257
        p_pow = [0] * (m+1)
        s_pow = [0] * (n+1)
        p_pow[0] = 1
        s_pow[0] = 1
        for i in range(1, m+1): p_pow[i] = (p_pow[i-1] * b) % h
        for i in range(1, n+1): s_pow[i] = (s_pow[i-1] * b) % h
        h_pow = 1
        for i in range(n):
            h_pow = (h_pow * b) % h
        p_hash = 0
        s_hash = 0
        for i in range(m):
            p_hash = (p_hash + ord(p[i]) * p_pow[m-i-1]) % h
            s_hash = (s_hash + ord(s[i]) * s_pow[n-i-1]) % h
        for i in range(n-m+1): 
            if p_hash == s_hash: 
                for j in range(m): 
                    if s[i+j] != p[j]: return i
            if i < n-m: 
                s_hash = (h * (s_hash - ord(s[i]*s_pow[n-i-1])) + ord(s[i+m]*s_pow[n-i-1])) % h
                if s_hash < 0: s_hash += h
        return -1
    return rabin_karp(haystack, needle)
