def solve(nums):
    def checkDup(A, n, mid):
        dup = 0
        for num in A:
            if num <= mid:
                dup ^= num
            else:
                dup ^= num - mid - 1
        return dup

    n = sum(1 for x in nums if x != 1)
    l, r = 1, n
    while l < r:
        mid = (l + r) // 2
        dup = checkDup(nums, n, mid)
        if dup and dup <= mid:
            r = mid
        else:
            l = mid + 1
    return l if checkDup(nums, n, l - 1) else l - 1
