    n = len(nums) - 1
    for i in range(n):
        p = nums[i] % (n // 2 + 1)
        q = nums[i] // (n // 2 + 1)

        if q < (n-i):
            nums[p] += n // 2 + 1
            nums[q + (n-i)] -= n // 2 + 1
        else:
            nums[p] += n // 2 + 1
            nums[p + (n-i - q)] -= n // 2 + 1

    for i in range(n):
        if nums[i] >= n:
            return i + 1
