def ex(nums, a, b):
    if a == b:
        return nums[a-1] + nums[b-1]
    c = (a + b) // 2
    pa = ex(nums, a, c)
    pb = ex(nums, c+1, b)
    if pa < pb:
        return pa
    return pb

