def solve(n, edges):
    parent = list(range(n))
    rank = [0] * n

    def root(x):
        if parent[x] != x:
            parent[x] = root(parent[x])
        return parent[x]

    def union(x, y):
        root_x, root_y = root(x), root(y)
        if root_x != root_y:
            if rank[root_x] > rank[root_y]:
                parent[root_y] = root_x
            else:
                parent[root_x] = root_y
                if rank[root_x] == rank[root_y]:
                    rank[root_y] += 1

    for u, v in edges:
        union(u, v)

    return len(set(root(i) for i in range(n)))
```

