def mergeOverlapping(intervals):
    if not intervals:
        return []

    intervals = [(intervals[i][0], i, 0) for i in range(len(intervals))] + \
                [(intervals[i][1], i, 1) for i in range(len(intervals))]
    intervals.sort()

    mergeStack = []
    result = []

    for interval in intervals:
        if not mergeStack or mergeStack[-1][2] != 1 or interval[0] > mergeStack[-1][0]:
            mergeStack.append(interval)
        else:
            lastInterval = mergeStack.pop()
            if lastInterval[2] == 0: key, i, _ = lastInterval
            else: key, i, _ = interval
            newInterval = [min(key, interval[0]), max(lastInterval[0], interval[0]), i]
            result.append(newInterval)
            if interval[1] > newInterval[1]: result.append([interval[1], i])
            else: result.append([newInterval[1], i])
            mergeStack.append(newInterval)

    return result

def solve(intervals):
    merges = mergeOverlapping(intervals)
    return len([m for m in merges if m[2] == 1]) + len(intervals) - len(merges)
