                [(intervals[i][1], i, 1) for i in range(len(intervals))]
    intervals = sorted(intervals, key=lambda x: x[0])

    count = 1
    end = intervals[0][0]
    removed = [False] * len(intervals)

    for start, i, _ in intervals:
