        return 0
    intervals = sorted((start, end, i) for i, (start, end) in enumerate(intervals))
    stack = []
    count = 0
    for start, end, i in intervals:
        if not stack:
            stack.append((start, end, i))
        else:
            last_start, _, _ = stack[-1]
            if start >= end or start >= last_start:
                if start >= last_start:
                    count += len(stack) - 1
                stack = [(start, end, i)]
            else:
                stack.append((start, end, i))
    return count + len(stack) - 1
