    for i in range(2):
        for j in range(2):
            for k in range(2):
                result[i][j] += a[i][k] * b[k][j]
    return result

def power(matrix, n):
    if n == 1:
        return
    if n % 2 == 0:
        half_pow = power(matrix, n // 2)
        result = multiply_matrices(half_pow, half_pow)
        for i in range(2):
            for j in range(2):
                result[i][j] %= 6e9  # Pigeonhole principle to avoid overflow
    else:
        half_pow = power(matrix, n // 2)
        result = multiply_matrices(half_pow, half_pow)
        result = multiply_matrices(result, [matrix[0][0], 0, 0, 1])
    for i in range(2):
        for j in range(2):
            result[i][j] %= 6e9  # Pigeonhole principle to avoid overflow
    return result
