        while bfs_queue:
            task = bfs_queue.popleft()
            if visited[task]:
                continue
            visited[task] = True
            order.append(task)
            for neighbor in graph[task]:
                indegree[neighbor] -= 1
                if indegree[neighbor] == 0:
                    bfs_queue.append(neighbor)

        if len(order) == n:
            return order
        return []

    order = has_valid_order()

    if not order:
        return []

    return order + [i for i in range(n) if not visited[i]]
