    if first_idx == -1:
        return [-1, -1]
    last_idx = binary_search(nums, 0, len(nums) - 1, target)
    while last_idx > first_idx and nums[last_idx] == nums[last_idx - 1]:
        last_idx -= 1
    return [first_idx, last_idx]
