    f = [1] * N
    dp = [nums[-1]] + [float('inf')] * (N - 1)
    for i in range(N - 1, -1, -1):
        for j in range(i + 1, N):
            f[j] = max(f[j], f[i] + 1 if nums[j] > nums[i] else f[j])
