            f[j] = max(f[j], f[i])
        if nums[i] < dp[0]: dp[0] = nums[i]
        else:
            l, r = 0, N - 1
            while l < r:
                m = (l + r + 1) // 2
                if dp[m] < nums[i]: l = m
                else: r = m - 1
            if dp[l] < nums[i]: dp[l] = nums[i]
            if l + 1 < N and dp[l + 1] < nums[i]: dp[l + 1] = nums[i]
