def solve_dfs(nums):
    if not nums:
        return 0
    n = len(nums)
    subsequence = [float("-inf")] * n
    length = 1

    def dfs(i):
        nonlocal length
        if i >= n:
            length = max(length, 1)
            return
        subsequence[i] = max(
            subsequence[i],
            1,
            (subsequence[i - 1] if i > 0 else 0) + 1
            if nums[i] > (nums[i - 1] if i > 0 else float("inf"))
            else 0
        )
        if subsequence[i] > length:
            length = subsequence[i]
            dfs(i + 1)
        else:
            dfs(i + 1)

    dfs(0)
    return length
