def solve(nums, k):
    counter = Counter(nums)
    counts = []
    for count in counter.values():
        counts.append(count)
    max_count = max(counts)
    all_max_counts = nlargest(k, counts)
    if len(set(all_max_counts)) == 1:
        if all_max_counts[0] != k:
            mostrequent_value = next(key for key, value in counter.items() if value == all_max_counts[0])
            most_frequent = mostrequent_value
            most_frequent_list = []
            for key, value in counter.items():
                if value == all_max_counts[0]:
                    most_frequent_list.append(key)
            return most_frequent_list
        return nlargest(k, counter.keys(), key=counter.get)
    most_frequent_value_list = []
    for v in counter:
        if counter[v] == max_count:
            most_frequent_value_list.append(v)
    indexes = []
    for i, value in enumerate(counter.values()):
        if value == max_count:
            indexes.append(i)
    second_max = sorted(set([value for i, value in enumerate(counts) if i not in indexes]))[-k + 1]
    return [v for v, count in counter.items() if count == max_count and count > second_max]
