        left = 0
        right = k - freq * index
        while (high == left or
               low == right or
               (high - left > 1 and  (high + left - 2) // 2 >= (k - freq * index) / (index + 1))):
            if high == left:
                low = True
                left += 1
            elif right == low:
                high = False
                right -= 1
            else:
                mid = (high + left - 2) // 2
                new_k = k - mid * index
                prev_high = high
                new_high = helper(new_k, freqs, index + 1)[1]
                if (prev_high and new_high) or (not new_high and not prev_high):
