def solve(haystack: str, needle: str) -> int:
    def kmp_tab(t, p):
        l, m = len(t), len(p)
        next_idx = [-1] + [0] * m
        i = j = 0
        while i < l:
            if j == 0 or t[i] == p[j]:
                i += 1
                if t[i] == p[j]:
                    j += 1
                    if j == m:
                        return i - m
                else:
                    if next_idx[j] != -1:
                        j = next_idx[j]
            else:
                j = next_idx[j]
        return -1

    def kmp_search(s1, s2, s3, start_idx):
        if not s1 or not s2:
            return -1
        new_needle = s1 + s2
        l1, l2, l3 = len(s1), len(s2), len(s3)
        if start_idx > l3 - l1:
            return -1
        if s2 == s1[-l2:]:
            if s1[-l2:] in s3[start_idx:start_idx + l1]:
                return start_idx + s3[start_idx:start_idx + l1].index(s1[-l2:])
            else:
                return -1
        return start_idx + kmp_tab(s3, new_needle)

    # Base case: If needle is longer than haystack, return -1
    if len(needle) > len(haystack):
        return -1

    # If the whole haystack matches the needle, return 0
    if haystack == needle:
        return 0

    # If needle is empty, return 0
    if needle == '':
        return 0

    # Find the index of the first character that matches 
    # between the haystack and the prefix of the needle
    max_first_char_match_index = 0
    for i in range(len(needle)):
        if needle[i] in haystack[:len(needle) - i]:
            max_first_char_match_index = max(max_first_char_match_index, haystack.find(needle[i], 0, len(needle) - i))

    # Check for partial matches
    l1, l2, l3 = len(needle[:-1]), len(needle[1:]), len(haystack)
    if max_first_char_match_index > l3 - l1:
        return -1
    elif needle[:-1][-len(needle[1:]):] in haystack[max_first_char_match_index: max_first_char_match_index + l1]:
