def solve(n, edges):
    visited = [False] * n
    def count_components(node):
        if visited[node]:
            return 0
        visited[node] = True
        component_size = 1
        for edge in edges:
            if edge[0] == node:
                component_size += count_components(edge[1])
            elif edge[1] == node:
                component_size += count_components(edge[0])
        return component_size

    disconnected_components = sum(1 for i in range(n) if not visited[i])
    connected_components = sum(count_components(i) for i in range(n) if not visited[i]) - disconnected_components
    return connected_components + disconnected_components
