def solve(n, edges):
    visited = [0] * n

    def is_visited(u):
        return visited[u] == 1

    def mark_as_visited(u):
        visited[u] = 1

    def mark_connection(u, v):
        mark_as_visited(u)
        mark_as_visited(v)

    def is_connected(u, v):
        return visited[u] == 1 and visited[v] == 1

    def find_group(u):
        if is_visited(u):
            return
        group_heads[u] = u
        for v in graph[u]:
            find_group(v)
            group_heads[u] = min(group_heads[u], group_heads[v])

    def union_groups(u, v):
        head_u, head_v = group_heads[u], group_heads[v]
        visited[u] = 0
        visited[v] = 0
        group_heads[head_u] = head_v

    group_heads, graph = {}, [[] for _ in range(n)]
    for u, v in edges:
        if not is_connected(u, v):
            mark_connection(u, v)
            graph[u].append(v)
            graph[v].append(u)

    for i in range(n):
        find_group(i)

    ans = len(group_heads)
    for u, v in edges:
        head_u, head_v = group_heads[u], group_heads[v]
        if head_u != head_v:
            union_groups(u, v)
            ans -= 1

    return ans + 1 if ans == 0 else ans
