def is_valid(n, edges):
    used = set()
    for u, v in edges:
        if u == v or (u, v) in used:
            return False
        used.add((u, v))
        used.add((v, u))
        if len(used) > (n * (n - 1)) // 2:
            return False
    return True

def solve_wrapper(n, edges):
    if not is_valid(n, edges):
        raise ValueError("Input is invalid")
    return solve(n, edges)
