def heapq_resize(heap, k):
    new Heap = []
    for _ in range(k):
        if heap:
            _, freq = heappop(heap)
            _, existing_freq = heappop(heap)
            new_freq = freq + (existing_freq if freq == 1 else 0)
            heappush(new Heap, (freq if freq != 1 else -float("inf"), new_freq))
    return heappop(new Heap)[1] if new Heap else -float("inf")
