def _one_time_required(nums, k):
    return itertools.islice(sorted(nums), k-1, None)

def _multiple_times_required(nums, k):
    return heapq.nsmallest(k, nums)

def kth_smallest(nums, k):
    if k == 1:
        return min(nums)
    elif k > len(nums):
        return None
    n = len(nums) // k
    remaining = len(nums) % k
    return solve(_one_time_required(nums, n + 1) if remaining != 0 else nums, n + 1 + remaining if remaining != 0 else n)

def solve_removed(nums, k):
    _one_time = _one_time_required(nums, k)
    _multiple = _multiple_times_required(nums, k)
    if len(_one_time) >= _multiple:
        return _one_time[0]
    else:
        return _multiple[0]
