def solve(haystack: str, needle: str) -> int:
    if len(needle) > len(haystack):
        return -1

    cache = {}

    def compute_mask(j: int) -> str:
        if j < len(needle) or j >= len(haystack):
            return ""

        for k in range(len(needle)):
            if j - k - 1 >= 0 and haystack[j - k - 1] != needle[k]:
                return ""
        return haystack[:j - len(needle)]

    for i in range(len(haystack) - len(needle) + 1, -1, -1):

        if haystack[i:i + len(needle)] == needle:
            return i

        left = i
        while left >= 0 and (left in cache or left + len(needle) <= len(haystack)) :
            if left in cache:
                ak = compute_mask(left)
                a = haystack[i:i + len(needle)]
                if a.startswith(ak) and a[len(ak):] == needle[len(ak):]:
                    return i
            else:
                left = cache.pop(item=left - len(needle) + 1)
            left += 1

            while left <= len(haystack) - len(needle) and (left in cache or left - 1 in cache):
                del cache[left]
                left -= 1

            cache[left] = compute_mask(left)
    return -1
