            return -1
        if len(needle) == 0:
            return 0
        prefix_length = 0
        window_start = 0
        for i in range(1, len(needle)):
            while window_start > 0 and needle[i] != needle[window_start]:
                window_start = prefix_length
                if prefix_length > 0:
                    prefix_length -= 1
            if needle[i] == needle[window_start]:
                prefix_length += 1
                window_start += 1
            if window_start == len(needle) - 1:
                return i - window_start
        window_start = 0
        for i in range(len(haystack) - len(needle)):
            if haystack[i + len(needle)] == needle[0]:
                if i + window_start < window_start:
                    window_start = i
                else:
                    prefix_length = 0
                    while window_start > 0 and haystack[i + prefix_length] != needle[window_start]:
                        window_start = prefix_length
                        if prefix_length > 0:
                            prefix_length -= 1
                    if haystack[i + prefix_length] == needle[window_start]:
                        window_start += 1
                        prefix_length += 1
                    if i + prefix_length + window_start == len(needle) - 1:
                        return i + len(needle) - window_start - 1
            if i + window_start - prefix_length >= len(needle):
                window_start = prefix_length + 1
        return -1

