def solve(nums):
    n = len(nums) - 1
    bits = [(num - 1) // n for num in nums]
    counts = [[0] * n for _ in range(14)]
    for i, bit in enumerate(bits):
        mask = 1 << i
        for j in range(n):
            if bit & mask:
                counts[i][j] += 1
    most_significant_bit = max(i for i, bit in enumerate(counts) if bit)
    masks = [(1 << i) for i in range(most_significant_bit + 1)]
    repeated_num = 0
    for mask in masks:
        for i in range(n):
            if counts[most_significant_bit - (mask & (~mask + 1))][i] == n - 1:
                repeated_num += (2** (most_significant_bit - (mask & (~mask + 1)))) * (i + 1)
    return repeated_num
