def intersect(starts, ends):
    n = len(starts)
    if n == 0: return []
    starts.reverse()
    ends.reverse()
    ends = [end for _, end in sorted(zip(ends, ranges(n)), reverse=True)]
    pointers = [0] * n
    stack = []
    for i in range(n):
        while stack and starts[i] >= ends[stack[-1]]:
            stack.pop()
        pointers[i] = stack[-1] if stack else -1
        stack.append(i)
    return pointers

def dfs(graph):
    n = len(graph)
    visited = [False] * n
    no_of_artpoints = 0
    for i in range(n):
        if not visited[i]:
            no_of_artpoints += 1
            stack = [i]
            while stack:
                u = stack.pop()
                if not visited[u]:
                    visited[u] = True
                    for v in range(len(graph[u]) - 1, graph[u][-1], -1):
                        stack.append(graph[u][v])

    return no_of_artpoints

