def solve(n):
    'calculate the n-th Fibonacci number efficiently using the technique mentioned in fib_genre'

    if any((n < 0, n > 500)):
        raise ValueError('n must be in the range 0 <= n <= 500')

    if n < 61:
        return fib_genre(n)

    a, b = 0, 1
    for _ in range(61):
        a, b = b, a + b

    c, d = 0, 1
    for _ in range(n - 60):
        c, d = d, (c + d) % 10

    a = (a * 10 + c) % 1000000007
    b = (b * 10 + d) % 1000000007
    for _ in range(61):
