from collections import Counter

def solve(nums, k):
    def find(k):
        i = 1
        while True:
            if (count := Counter(nums).most_common(i)).count((x[0], x[1])) == 1 and count[0][1] == k:
                return count[0][0]
            i += 1

    res = {find(k): 0}
    left, right, unique = min(nums), max(nums), len(set(nums))
    while right - left > 1:
        mid = (left + right) // 2
        if find(mid) == list(res.keys())[0]:
            right = mid
        elif find(mid) not in res:
            right = mid
        else:
            left = mid
    new_nums = sorted(num for num in nums if find(num) == list(res.keys())[0])
    for i in range(len(new_nums)):
        new_count = [(new_nums[i], 0)]
        for j in range(i + 1, len(new_nums)):
            if new_nums[j] == new_nums[i]:
                new_count.append((new_nums[j], new_count[-1][1] + 1))
        if k > 1 and new_count[-1][1] == k and (new_count[-1][1] > count := Counter(nums).most_common(i + 1)[k - 1][1] if k + 1 < i + 1 else 0):
            new_nums[i : j + 1] = []
            new_count = [(x, 0) for x in new_nums]
            k -= 1
    answer = []
    for i in range(len(new_nums)):
        for x, y in new_count:
            if x == new_nums[i] and y == new_count[i][1]:
                answer.append(x)
                break
    return answer
