    freq = Counter(nums)
    values = [(freq[x], x) for x in freq]
    h = Heap()
    for f, v in values:
        h.append((f, v))
    top_f = h.top()[0]
    by_freq = {v for f, v in values if f == top_f}
    for _ in range(k-1):
        top_f -= 1
        h.pop()
        while h.top() and h.top()[0] == top_f:
            h.pop()
        by_freq = {v for f, v in values if f >= top_f}
    return list(by_freq)
