        if count > 0:
            heapq.heappush(heap, (count, num))
            freq[num] -= 1

    for _ in range(k - 1):
        count, num = heapq.heappop(heap)
        if freq[num] > 0:
            freq[num] -= 1
            heapq.heappush(heap, (count, num))

