        while len(stack) > 1 and stack[0] >= stack[1]:
            pop_stack.append(stack.pop(0))
        for x in pop_stack:
            stack.pop(0)
        seen.add(num)

    while len(stack) > k:
        stack.pop(0)
    return -stack[0]
