def solve(nums, k):
    count = {}

    for num in nums:
        count[num] = count.get(num, 0) + 1

    queue = []

    for n, freq in count.copy().items():
        heapq.heappush(queue, (freq, n))

    if k <= len(nums) // 2:
        return heapq.nsmallest(k, count.keys())[k-1]

    if k > len(nums) - len([n for n, freq in count if freq == 1]):
        return heapq.nlargest(len(nums) - k + 1, count.keys())[-1]

    m = k
    m1 = k//2
    while queue:
        freq, n = heapq.heappop(queue)
        freq -= 1
        if freq > 0:
            heapq.heappush(queue, (freq, n))
        m -= 1
        if m <= 0:
            break
        if freq > 1:
            freq1 = freq // 2
            p = []
            for _ in range(freq1):
                heapq.heappush(p, n)
            for _ in range(freq - freq1):
                heapq.heappush(queue, (freq1, n))
            if n not in count or queue[0][1] != n:
                queue = sorted(p + queue)
        elif p:
            queue += p
            queue = sorted(queue)
        if m == m1:
            return n
        m1 -= 1
    return n
