import heapq

def solve(nums, k):
    """Returns the k-th smallest value in nums."""

    # Create a dictionary to store the frequency of each number
    freq = {}

    def helper(nums):
        """Helper function to count the frequency of each number."""

        for num in nums:
            freq[num] = freq.get(num, 0) + 1

    # Create a min heap from the frequency dictionary
    def priority_queue(h):
        """Converts a dictionary into a min heap."""

        return [(-c, n) for n, c in h] + [[]]  # Store the count negatively in a min heap

    helper(nums)
    pq = priority_queue(freq)

    # Push all elements to the min heap
    while pq[-1] == []:
        pq.pop()
        if len(pq) == 1:
            break

    # Pop the smallest element k times and return the result
    for _ in range(k - 1):
        c, n = heapq.heappop(pq)
        if c != -1:
            heapq.heappush(pq, [c + 1, n])
    return -heapq.heappop(pq)[-1]
