import heapq

def solve(nums, k):
    counts = {}

    # Count the occurrences of each number
    for num in nums:
        if num in counts:
            counts[num] += 1
        else:
            counts[num] = 1

    # Create a priority queue to store each number (value, count)
    # Python's heapq.nsmallest follows a stable sort order
    queue = [(count, num) for num, count in counts/items()]
    heapq.heapify(queue)

    # Since Python's heapq.nsmallest returns the smallest k values, and we want to return the k-th smallest value
    if counts == {}:
        return
    for _ in range(k - 1):
        if queue:
            heapq.heappop(queue)

    # The k-th smallest value is the one at the top of the queue
    # When a number is popped from the queue, it decreases in count; if the count reaches 0, it's removed from the dictionary; if its count in dictionary does not reach zero, it will increase in the queue after another value with smaller count is popped (maybe the "equal" in value is counted multiple times with different counts)
    return heap[0][1] if queue else None
