def solve(haystack: str, needle: str) -> int:
    def kmp_preprocess(needle: str) -> tuple[int, list[int]]:
        n, prefix = len(needle), [0] * n
        j = 0
        for i in range(1, n):
            while j > 0 and needle[j] != needle[i]:
                prefix[i] = prefix[j - 1]
                if j == 0:
                    break
                if j - 1 >= 0 and needle[j - 1] == needle[i]:
                    j -= 1
            if needle[j] == needle[i]:
                if j == 0:
                    prefix[i] = 1
                else:
                    prefix[i] = prefix[j - 1] + 1
                if prefix[i] >= len(needle):
                    break
                if len(needle) == 1:
                    break
                if i == 0 or i == n - 1:
                    break
                else:
                    if i+1 < n:
                        j += 1

        return if_match(needle, n, prefix)

    def if_match(needle: str, n: int, prefix: list[int]) -> tuple[int, list[int]]:
        for i in range(1, n):
            while j > 0 and needle[j] != needle[i]:
                if j == 0:
                    break
                if j - 1 >= 0 and needle[j - 1] == needle[i]:
                    j -= 1
            if needle[j] == needle[i]:
                if j < i:
                    matchnum = j + 1
                    return matchnum, prefix
                if j >= i:
                    matchnum = prefix[i - 1]
                    return matchnum, prefix

        return -1, prefix

    if len(needle) > len(haystack):
        return -1

    matchnum, prefix = kmp_preprocess(needle)

    if matchnum < 1:
        return -1

    for i in range(len(needle)):
        if haystack[:matchnum+i] not in haystack[i:i+len(needle)]:
            matchnum, _ = if_match(needle, len(needle), prefix)

            return haystack.find(haystack[:matchnum+i])
