def solve(haystack, needle):
    def rabin_karp(s, p):
        n = len(s)
        m = len(p)
        if m > n or m == 0:
            return -1
        h = ord('z') - ord('a') + 1
        b = 257
        p_pow = [0] * (m+1)
        s_pow = [0] * (n+1)
        p_pow[0] = 1
        s_pow[0] = 1
        for i in range(1, m+1, 1) :
            p_pow[i] = (p_pow[i-1]*b % h)
        for i in range(1, n+1, 1) :
            s_pow[i] = (s_pow[i-1]*b % h)
        p_val = 0
        for i in range(m) :
            p_val = (p_val*b + ord(p[i]) - ord('a')) % h
        s_val = 0
        for i in range(m) :
            s_val = (s_val*b + ord(s[i]) - ord('a')) % h
        for i in range(n-m+1) :
            if p_val == s_val :
                for j in range(i, i+m) :
                    if s[j] != p[j-i]:
                        break
                    if j == i+m-1 :
                        return i
            if i < (n-m) :
                s_val = (b*(s_val-ord(s[i]) + ord('a')) % h + ord(s[i+m]) - ord('a')) % h
                if s_val < 0 :
                    s_val = s_val + h
        return -1

    return rabin_karp(haystack, needle)
