    needle = needle + "$"
    lps = kmp_preprocess(needle)
    i, j = 0, 0
    while i < len(haystack):
        if haystack[j] == needle[j]:
            j += 1
        if j == len(needle):
            return i - (len(needle) - 1)
        elif i < len(haystack) and haystack[i] != needle[j]:
            if j:
                j = lps[j - 1]
            else:
                i += 1
    return -1
