class UnionFind:
    def __init__(self):
        self.parents = {}
        self.union_counts = {}

    def create_set(self, node):
        self.parents[node] = node
        self.union_counts[node] = 1

    def find_set(self, node):
        if self.parents[node] == node:
            return node
        return self.find_set(self.parents[node])

    def union_sets(self, node1, node2):
        set1 = self.find_set(node1)
        set2 = self.find_set(node2)
        if set1 != set2:
            if self.union_counts[set1] <= self.union_counts[set2]:
                self.parents[set1] = set2
                self.union_counts[set2] += self.union_counts[set1]
            else:
                self.parents[set2] = set1
                self.union_counts[set1] += self.union_counts[set2]


def solve(intervals):
    intervals_by_end = []
    uf = UnionFind()

    for start, end in intervals:
        if end not in uf.union_counts:
            uf.create_set(end)
            intervals_by_end.append((end, (start, end)))

    intervals_by_end = [a for a in sorted(intervals_by_end, key=lambda x:(-x[0], -x[1][0]))]

    for i in range(1, len(intervals_by_end)):
        if intervals_by_end[i-1][0] > intervals_by_end[i][1][0]:
            break
        uf.union_sets(intervals_by_end[i][0], intervals_by_end[i-1][0])

    result = sum(uf.union_counts.values())

    return len(intervals) - result
