from collections import defaultdict, deque

class Graph:
    def __init__(self, n):
        self.n = n
        self.g = [[] for _ in range(n)]
        self.in_degree = [0] * n

    def add_edge(self, a, b):
        self.g[a].append(b)
        self.in_degree[b] += 1

def solve(n, prerequisites):
    graph = Graph(n)
    for a, b in prerequisites:
        graph.add_edge(b, a)

    order = [i for i in range(n)]
    order.sort(key=lambda x: graph.in_degree[x])

    visited = [False] * n
    topo = []
    def topsort(v):
        if visited[v]:
            return
        visited[v] = True
        for u in graph.g[v]:
            topsort(u)
        topo.append(v)

    for v in order:
        if not visited[v]:
            topsort(v)

    if len(topo) != n:
        return []
    return topo[::-1]
