class Node:
    def __init__(self, start, end):
        self.start = start
        self.end = end
        self.left = None
        self.right = None

class IntervalTree:
    def __init__(self):
        self.root = None

    def insert(self, node, start, end):
        if node is None:
            return Node(start, end)
        if start < node.start:
            node.left = self.insert(node.left, start, end)
        elif start > node.end:
            node.right = self.insert(node.right, start, end)
        else:
            node.end = max(node.end, end)
        return node

    def merge(self, node, start, end):
        if node is None:
            return Node(start, end)
        if start <= node.start:
            node = self.merge(node.left, start, end)
        else:
            node = self.merge(node.right, start, end)
        return node

    def merge_intervals(self, intervals):
        root = None
        for start, end in intervals:
            root = self.insert(root, start, end)
        if not root:
            return []
        nodes = []
        stack = [root]
        while stack:
            node = stack.pop()
            nodes.append(node)
            if node.left:
                stack.append(node.left)
            if node.right:
                stack.append(node.right)
        nodes.sort(key=lambda x: x.start)
        res = []
        i = 0
        while i < len(nodes):
            if not res or nodes[i].start > res[-1][1]:
                res.append([nodes[i].start, nodes[i].end])
            else:
                last = res.pop()
                res.append([last[0], max(last[1], nodes[i].end)])
            i += 1
        return res

def solve(intervals):
    return IntervalTree().merge_intervals(intervals)
