                uf.union(i, j)
            edges.add((i, j))
    parent = {}
    for x in range(len(intervals)):
        parent[uf.find(x)] = None
    edges = [(uf.find(x), uf.find(y)) for x, y in edges if uf.find(x) != uf.find(y)]
    edges.sort()
