        disjoint_intervals.append((start, end))
        disjoint_set.union(root, tuple([i[0] for i in disjoint_intervals]), tuple([i[1] for i in disjoint_intervals]))
        disjoint_intervals = [list(interval) for interval in disjoint_intervals if disjoint_set.find(tuple(interval)) == root]

