def solve(nums, target):
    def two_pointers_search(nums, target):
        if not nums:
            return [-1, -1]
        left, right = [], []
        i, j = 0 + 1, len(nums) - 1
        while i <= j:
            m = i + (j - i) // 2
            if nums[m] == target:
                left = [m - 1, m]
                right = [m, m + 1]
                while left and nums[left[-1]] == target: left.pop()
                while right and nums[right[0]] == target: right.pop(0)
                left.append(m)
                right = [m] + right
                while left and right and nums[left[0]] == nums[right[-1]]:
                    if left[0] < right[-1]: break
                    left.pop(0)
                    right.pop()
                return left + [-1] if len(left) > 1 else [-1, -1]
            elif nums[m] < target:
                i = m + 1
            else:
                j = m - 1
        return [-1, -1]

    first, last = two_pointers_search(nums, target)
    if first == [-1]: return [-1, -1]
    first = two_pointers_search(nums[:first[0] + 1], target - 1)
    last = two_pointers_search(nums[last[-1]:], target)
    return [left for left, right in [first, last] if left != [-1]][0]
