from collections import Counter
from operator import itemgetter

class Heap:
    def __init__(self):
        self.data = []

    def append(self, value):
        self.data.append(value)
        self.data.sort(reverse = (self.max or False))

    def pop(self):
        return self.data.pop(0)

    def _sorted(self):
        return sorted(self.data, reverse = (self.max or False))

    def __len__(self):
        return len(self.data)

    def __init_max__(self):
        if len(self.data) > 0:
            self.max = self.data[0]
        else:
            self.max = None

class Helper:
    @staticmethod
    def solve(nums, k):
        return Helper.count_top_frequent(nums, k)

    @staticmethod 
    def freq(nums):
        return Counter(nums)

    @staticmethod
    def count_top_frequent(nums, k):
        freq = Helper.freq(nums)
        heap = Heap()
        heap.max = False
        for val, cnt in freq.items():
            heap.append((val, cnt, 1))

        if k == len(freq):
            return list(freq.keys())
        for i in range(len(nums)-len(freq)):
            val = nums[i+len(freq)]
            if freq[val] != 1:
                freq -= {val:1}
            cnt = freq.get(val, 0)-1
            heap.append((val, cnt, 1))
        top_k_freq = sorted(heap._sorted(), key=itemgetter(2), reverse = False)[:k]
        return list(set(x[0] for x in top_k_freq))
