    pq = _pq_from_qq(qq)
    while pq[0] < -k:
        _, i, indices = _heapq.heappop(pq)
        for x in nums[i]:
            if not indices or random.random() < len(indices) / (len(nums[i]) + len(indices)):
                indices.append(x)
