                    mid = (left + right) >> 1
                    if pq[j-1] <= val:
                        left = mid + 1
                    else:
                        pq[j-1], pq[i] = pq[i], pq[j-1]
                        i += 1
                        j -= 1
                return j
            k = pq_update(0, k)
            nums[pq_update(0, idx - 1)] = val
