    def partition(l, r):
        pivot_idx = random.randint(l, r)
        swap(pivot_idx, r)
        i = l
        for j in range(l, r):
            if nums[j] <= nums[r]:
                swap(i, j)
                i += 1
        swap(i, r)
        return i

    def quickselect(l, r, target):
        if l == r:
            return nums[l]
        idx = partition(l, r)
        if target == idx:
            return nums[idx]
        elif target < idx:
            return quickselect(l, idx - 1, target)
        else:
            return quickselect(idx + 1, r, target)

    return quickselect(0, len(nums) - 1, k - 1)
