import random

def compress(nums):
    hist = {}
    for x in nums:
        hist[x] = hist.get(x, 0) + 1
    return hist

def iterative_suggestion(nums):
    hist = compress(nums)
    areas = [(-count, x) for x, count in hist.items()]
    heapq.heapify(areas)
    return sum(heapq.heappop(areas)[1] for _ in range(len(nums) - len(hist)))

def median_or_mode(nums, target_cnt):
    hist = compress(nums)
    if len(hist) == len(nums):
        return iterative_suggestion(nums)
    sorted_items = sorted(hist.items(), key=lambda x: x[1])
    sorted_values = [v for v, _ in sorted_items]
    n_unique = len(sorted_values)

    if n_unique % 2 == 0 and target_cnt == n_unique // 2 + 1:
        target_cnt -= 1
    cnt_left = bisect.bisect_left(sorted_values, sorted_values[target_cnt - 1]) if target_cnt <= n_unique / 2 else target_cnt
    cnt_right = n_unique - cnt_left
    return sorted_values[target_cnt - 1] if cnt_left < target_cnt else (sorted_values[-1] + sorted_values[-2]) / 2

def bisect_value_insertion(nums, target, lower_or_greater):
    i = len(nums) // 2
    while True:
        if nums[i] < target:
            if lower_or_greater == 'greater':
                return i + 1
            else:
                i += 1
        elif nums[i] > target:
            if lower_or_greater == 'greater':
                i -= 1
            return i
        else:
            return i

def bisect_search(nums, target):
    return bisect_value_insertion(sorted(nums), target, 'greater')

def select_kth(nums, k):
    _shift = random.randint(1, 0x10000)
    sample = sorted(x + _shift for x in nums)
    return (k - 1) % len(nums) + bisect_search(sample, median_or_mode(sample, k))

