    sorted_items = sorted((x + 1, i) for i, x in enumerate(nums))
    right = n
    left = -1
    while right > left + 1:
        mid = (right + left) // 2
        if select_kth(nums, k) <= sorted_items[mid][0]:
            right = mid
        else:
            left = mid
    return sorted_items[right][0] - 1
