def _ProcessHeaps(heaps, k):
    seconds, seconds_ratio = [], []
    for i, heap in enumerate(heaps):
        if heap:
            second = heap[0][0]
            seconds.append(second)
            seconds_ratio.append(len(heap))

    mapped_seconds = sorted([(second, ratio, idx) for idx, (second, ratio) in enumerate(zip(seconds, seconds_ratio))], key=lambda x: x[0])
    return _FindKthValue(mapped_seconds, k)


def _FindKthValue(mapped_seconds, k):
    left, right = 0, len(mapped_seconds) - 1
    while left < right:
        mid = (left + right) // 2
        if mapped_seconds[mid][2] + 1 >= k:
            right = mid
        else:
            left = mid + 1
    return mapped_seconds[left][0]


def _Histogram(histograms, start, end):
    if start == end:
        return [num for _, num in histograms[start]]
    lists = [_Histogram(histograms, start, (start + end) // 2),
             _Histogram(histograms, (start + end) // 2 + 1, end)]
    merged = []
    i, j = 0, 0
    while i < len(lists[0]) and j < len(lists[1]):
        if (lists[0][i][1] if i < len(lists[0]) else float('-inf'),
                lists[1][j][1]) <= end // 2:
            merged.append(lists[0][i])
            i += 1
        else:
            merged.append(lists[1][j])
            j += 1
    merged += lists[0][i:] + lists[1][j:]
    return merged
