        k -= 1
        popped = min_heap[idx]
        if popped != nums[idx]:  # Update the removed count
            if popped not in num_removed:
                num_removed[popped] = 0
            num_removed[popped] += 1
            nums[idx] = None
            return popped

        remove_and_inflate(min_heap, idx, num_removed)
        remove_and_inflate(min_heap, k - 1, num_removed)

    return min(min_heap)

def remove_and_inflate(heap, idx, num_removed):
    if len(heap) == 1 and heap[0] is None:
        del heap[idx]
        return

    val_to_remove = heap[idx]
    if val_to_remove is None:
        idx += 1
        val_to_remove = heap[idx]
    if idx == 0:
        del heap[idx]
        del num_removed[val_to_remove]
        heap.append(random.choice(nums))
        exploded = [num for num, cnt in num_removed.items() if cnt > 0]
        exploded.sort()
        for v in exploded:
            if v <= heap[-1]:
                num_removed[v] -= 1
            else:
                del num_removed[v]
                heap.append(v)
                if len(num_removed) == 0:
                    break
        return

    smallest = val_to_remove
    children = [heap[2 * idx + 1], heap[2 * idx + 2]]
    for child in children:
        if child is not None and child < smallest:
            smallest = child
    if smallest == val_to_remove:
        smallest = get_smallest(children)

    if smallest != val_to_remove:
        heap[idx] = smallest
    if idx < len(num_removed) and idx > 0:
        if num_removed[val_to_remove] > 1:
            num_removed[val_to_remove] -= 1
        else:
            del num_removed[val_to_remove]

    if smallest != val_to_remove:
        if value_to_remove := get_value_from_num_removed(smallest, num_removed):
            del num_removed[value_to_remove]

    if value_to_remove := get_value_from_num_removed(val_to_remove, num_removed):
