    def partition(l, r):
        pivot = random.choice(nums[l:r+1])
        i = l
        for j in range(l, r+1):
            if nums[j] < pivot:
                nums[i], nums[j] = nums[j], nums[i]
                i += 1
        nums[i], nums[l] = nums[l], nums[i]
        return i

    def quickselect(l, r, k):
        if l == r:
            return nums[l]
        pos = partition(l, r)
        if k == pos + 1:
            return nums[pos]
        if k < pos + 1:
            return quickselect(l, pos - 1, k)
        return quickselect(pos + 1, r, k - pos - 1)

    return quickselect(0, len(nums) - 1, k)
