def rabin_karp(haystack, needle):
    def rolling_hash(s, base, modulo):
        result = 0
        for char in s:
            result = (result * base + ord(char) - 97) % modulo
        return result

    def match(haystack, needle, target):
        n = len(needle)
        for i in range(len(haystack) - n + 1):
            window = haystack[i:i+n]
            if rolling_hash(window, base, modulo) == target:
                return i
        return -1

    base = 26
    modulo = 10**8 + 7
    needle_hash = rolling_hash(needle, base, modulo)
    needle_len = len(needle)
    haystack_hash = rolling_hash(haystack[:needle_len], base, modulo)

    if haystack_hash != needle_hash and len(haystack) < len(needle):
        return -1

    if haystack[:needle_len] == needle:
        return 0

    for i in range(1, len(haystack) - needle_len + 1):
        haystack_hash = (base * (haystack_hash - ord(haystack[i-1]) + 97) + ord(haystack[i+needle_len-1]) - 97) % modulo
        if haystack_hash != needle_hash and haystack_hash > 0:
            if i > len(haystack) - needle_len:
                haystack_hash = 0
            else:
                continue
        if haystack[i:i+needle_len] == needle:
