def RabinKarp(haystack, needle):
    def hash_string(s):
        hash_val = 0
        for char in s:
            hash_val = (hash_val * 31 + ord(char) - ord('a') + 1) % 2000000
        return hash_val

    def pow_31(n):
        if n == 0:
            return 1
        result = pow_31(n // 2)
        result *= result
        if n % 2 == 1:
            result *= 31
        return result % 2000000

    haystack_hash = hash_string(haystack)
    needle_hash = hash_string(needle)
    needle_power_hash = pow_31(len(needle) - 1)

    for i in range(len(haystack) - len(needle) + 1):
