class RabinKarp:
    def __init__(self, seed=0):
        self.seed = seed

    def _hash_str(self, s):
        hash_val = 0
        for c in s:
            hash_val = hash_val * self.seed + ord(c)
        return hash_val

    def find_pattern(self, haystack, needle):
        if not needle:
            return 0

        h_len, n_len = len(haystack), len(needle)
        if n_len > h_len:
            return -1

        self.seed = 31
        h = self._hash_str(haystack[:n_len])
        n = self._hash_str(needle)

        for i in range(h_len - n_len + 1):
            if h == n and haystack[i:i+n_len] == needle:
                return i
            if i + n_len < h_len:
                h = h - ord(haystack[i]) * (self.seed ** (n_len-1)) + ord(haystack[i+n_len])
                if h < 0:
                    h += 2 ** 32
        return -1


def solve(haystack, needle):
    return RabinKarp().find_pattern(haystack, needle)
