def expand_gen(bm):
    """Generate R NFA's with width len(bm)"""
    prev_link = [None] * (R + 1)
    length = 0
    for i, m in enumerate(bm):
        cur_link = [None] * (R + 1)
        for j in range(R + 1):
            cur_link[j] = prev_link[j]
        prev_link[j] = i + 1
        for d_o in range(26):
            idx = ord('a') + d_o
            prev_link[idx]  = cur_link[idx]
            cur_link[idx] = (i + 1, j) if m[d_o] == '1' and i + 1 < len(bm) else None
        length = i + 1
        yield cur_link, length

def search(haystack, needle):
    if len(needle) > len(haystack):
        return -1
    if not needle:
        return 0

    bm = [ '1' if ord(haystack[i]) == ord(needle[j]) else '0' for i in range(len(haystack)) for j in range(len(needle)) if i + len(needle) <= len(haystack)]
    bm = [bm[i:i + len(needle)] for i in range(0, len(haystack), len(needle))]

    res = len(haystack)
    nfa_gen = expand_gen(bm)

    trans = nfa_gen.__next__()
    pos = 0
    while pos < res:
        cursor = 0
        for i in range(len(trans[0])):
            if trans[0][i] != None and trans[0][i][1] == None:
                curr_link, length = list(nfa_gen.__next__()
            else:
                curr_link, length = trans[1]
            if trans[0][i] != None and trans[0][i][0] <= pos + length:
                cursor = trans[0][i][0]
                break
            else:
                if trans[0][i] != None and trans[0][i][0] < length:
                    curr_link, length = trans[0][i]
        res = min(res, cursor + length - 1)
        pos += 1
    return res if res < len(haystack) else -1
