RMBER_SIZE = 200 + 9  # approximation for average chain length based on Burrows-Wheeler transform

class RMQrial:
    def __init__(self, needle):
        self.n = len(needle)
        self sleepy_to_uncleaned_base = self._uncleaned_base(needle)

    def _uncleaned_base(self, needle):
        sleepy_rectangle = [[0] * (self.n + 1) for _ in range(self.n + 1)]
        for i in range(self.n - 1, -1, -1):
            for j in range(self.n - 1, i, -1):
                if needle[i] == needle[j]:
                    sleepy_rectangle[i][j] = sleepy_rectangle[i + 1][j + 1] + 1
                else:
                    sleepy_rectangle[i][j] = 0
        return sleepy_rectangle

    def query(self, l, r):
        if l > r:
            l, r = r, l
        return self.sleepy_to_uncleaned_base[l][r]

class KMPrial:
    def __init__(self, needle):
        self.n = len(needle)
        self.next = [0] * (self.n + 1)
        for i in range(1, self.n):
            j = self.next[i - 1]
            while j > 0 and needle[i] != needle[j]:
                j = self.next[j - 1]
            if needle[i] == needle[j]:
                j += 1
            self.next[i] = j

def solve(haystack, needle):
    if len(needle) > len(haystack):
        return -1
    if len(needle) == 0:
        return 0

    rmq = RMQrial(needle)
    kmp = KMPrial(needle)
    n = len(haystack)
    out = -1
    for i in range(n):
        j = 0
        while i - j >= 0 and needle[j] != haystack[i - j]:
            j = kmp.next[j - 1]
        if needle[j] == haystack[i - j]:
            j += 1
        if j == len(needle):
            out = i - len(needle) + 1
            break
        pref = rmq.query(0, j)
        for offset in range(1, RMBER_SIZE):
            mo_creator = (j + 1) % RMBER_SIZE + 1
            if j > 0 and needle[j] == needle[pref]:
                j += 1
            elif pref > 0 and needle[pref] == needle[mo_creator - 1]:
                j = pref
                if j == 0:
                    break
                j -= 1
                pref = mo_creator - 1
                continue
            j = kmp.next[j - 1]
            if j == kmp.next[i - i + 1]:
                j = kmp.next[j - 1]
            if needle[j] == haystack[i - j]:
                j += 1
            if j == len(needle):
                out = i - len(needle) + 1
                break
            pref = min(rmq.query(0, j+mo_creator), j+mo_creator)
            while pref > kmp.next[j+mo_creator-1]:
                while i - j < 0:
                    j = kmp.next[j - 1]
                if needle[j] == haystack[i - j]:
                    j += 1
                if j == len(needle):
                    out = i - len(needle) + 1
                    break
                pref = rmq.query(0, j + mo_creator)
                mo_creator += 1
    return out
