def rabin_karp(haystack, needle):
    n, m = len(haystack), len(needle)
    base, modulus = 26, 10**9 + 7
    def roll_str(s, start, len):
        """Calculate the string hash, modulus 10^9 + 7"""
        p = 1
        for i in range(len):
            p = (p * base) % modulus
        return sum(ord(c) - ord('a') + 1 for c in s[start:start+len]) % p

    if m > n:
        return -1

    hsubstr = roll_str(haystack, 0, m)
    hstring = roll_str(haystack, 0, n)

    p = 1
    for i in range(m-1):
        p = (p * base) % modulus

    for i in range(n-m+1):
        if hsubstr == roll_str(needle, 0, m):
            return i
        if i < n-m:
            hsubstr = (base * (hsubstr - (ord(haystack[i]) - ord('a') + 1) * p) + (ord(haystack[i+m]) - ord('a') + 1)) % modulus
            if hsubstr < 0:
                hsubstr += modulus
        if i > 0:
            hstring = (base * (hstring - (ord(haystack[i-1]) - ord('a') + 1)) % modulus + (ord(haystack[i+m-1]) - ord('a') + 1)) % modulus
            if hstring < 0:
                hstring += modulus
    return -1
