def precompute(needle):
    """Lazy preprocessing for the KMP algorithm."""
    next = [0] * len(needle)
    canJump = 0
    for j in range(1, len(needle)):
        if j <= canJump:
            next[j] = min(canJump - j + 1, next[j - canJump])
            while j + next[j] < len(needle) and needle[j + next[j]] == needle[next[j]]:
                next[j] += 1
            if next[j] + j > canJump:
                canJump = next[j] + j - 1
        else:
            next[j] = 0
            while j + next[j] < len(needle) and needle[j + next[j]] == needle[next[j]]:
                next[j] += 1
    return next


def solve(haystack, needle):
    """Finds the first position where needle occurs in haystack."""
    if len(needle) > len(haystack):
        return -1
    next = precompute(needle)
    for i in range(len(haystack)):
        j = 0
        while j < len(needle) and haystack[i + j] == needle[j]:
            j += 1
        if j == len(needle):
            return i
        elif i + j < len(needle):
            i += next[j]
    return -1
