            h = (h * 29 + ord(c) - ord('a') + 1) % (1 << 16)
        return h

    def rabin_karp(haystack, needle):
        n, m = len(haystack), len(needle)
        if m > n: return -1
        return rabin_karp_helper(hash_string(needle), needle, haystack)

