        powers = [1]
        for i in range(49): powers[0] = (powers[0] * 29) % (1 << 16)
        for i in range(1, len(powers)):
            powers[i] = (powers[i-1] * 29) % (1 << 16)
        h = 0
        for i in range(len(haystack)):
            h = (h * 29 + ord(haystack[i]) - ord('a') + 1) % (1 << 16)
            if i - len(needle) + 1 >= 0: 
                h = (h - powers[i - len(needle) + 1] * (ord(haystack[i - len(needle) + 1]) - ord('a') + 1)) % (1 << 16)
                if h < 0: h += 1 << 16
            if i - len(needle) + 1 >= 0 and h == needle_hash: 
                for j in range(len(needle)):
                    if haystack[i - j] != needle[len(needle) - 1 - j]:
                        break
                    else: j += 1
                if j == len(needle): return i - len(needle) + 1
        return -1

    return rabin_karp_helper(hash_string(needle), needle, haystack)
