        return -1
    if not needle:
        return 0
    z = z_algorithm(needle + '#' + haystack)
    return z[len(needle)] if z[len(needle)] != len(needle) else -1

def z_algorithm_prefix_function(prefix, suffix):
    z_pred = z_algorithm(suffix)
    return [z_pred[i - len(suffix)] for i in sorted(set(prefix + suffix)) if i - len(suffix) >= 0]

def z_algorithm_prefix(prefix, suffix=None):
    return z_algorithm('[#]' * len(prefix) if not suffix else '#' * len(prefix) + suffix)
