ROLLING_HASH_CONST = 997

def rolling_hash(s):
    return [0] * (len(s) + 1)

def shift(s, i, p):
    for j in range(i, len(s)):
        s[j] = (s[j] * p + ord(s[j])) % ROLLING_HASH_CONST

def solve(haystack, needle):
