        return -1

    rolling_needle = rolling_hash(needle + '$')
    shift(rolling_needle, 0, ROLLING_HASH_CONST)
    rolling_needle_hash = rolling_needle[0]

    for i in range(len(haystack)):
        if i >= len(needle):
            rolling_pad = (ROLLING_HASH_CONST - ord(haystack[i - len(needle)]) * pow(ROLLING_HASH_CONST, len(needle) - 1, ROLLING_HASH_CONST)) % ROLLING_HASH_CONST
            shift(rolling_needle, 1, ROLLING_HASH_CONST)
            rolling_needle_hash = (rolling_needle_hash - rolling_needle[1] * rolling_pad) % ROLLING_HASH_CONST
        if i >= len(needle) - 1 and rolling_needle_hash == rolling_needle[0]:
            return i - len(needle) + 1
        shift(rolling_needle, 0, ROLLING_HASH_CONST)
        rolling_needle_hash = (rolling_needle_hash * ROLLING_HASH_CONST + ord(haystack[i])) % ROLLING_HASH_CONST

    return -1
