P = 31
M = 10**9 + 7

defsafe_mul(a, b):
    a %= M
    c = a * b - (M >> 1) * a * b if b >= M >> 1 else 0
    return (c + M) % M

def safe_pow(b, e):
    result = 1
    base = b
    while e:
        if e % 2 == 1:
            result = (result * base) % M
        base = (base * base) % M
        e //= 2
    return result

def rabin_karp(haystack, needle):
    if len(needle) > len(haystack):
        return -1
    pow_P = [safe_pow(P, i) for i in range(len(needle))]
    h = [0] * (len(haystack) + 1)
    for i in range(len(haystack)):
        h[i + 1] = (P * h[i] + ord(haystack[i])) % M
    n = len(needle)
    rem = (safe_mul(pow_P[n - 1], safe_pow(P, M - 2)) + M - 1) % M
    for i in range(len(haystack) - n + 1):
        if h[i + n] >= M or h[i + n] - safe_mul(rem, h[i]) != h[i + n - len(needle)]:
            continue
        for j in range(n):
            if haystack[i + j] != needle[j]:
                break
            if j + 1 == n:
                return i
    return -1
