def roll_hash(string):
    """Compute the Rabin-Karp hash of a string."""
    hash_val = 0
    base = ord('a')
    for char in string:
        hash_val = (hash_val * 23 + ord(char) - base) % 101
    return hash_val

def solve(haystack, needle):
    """Return the index of the first occurrence of the needle in the haystack,
    or -1 if it's not found."""
    if len(needle) > len(haystack):
        return -1

    needle_hash = roll_hash(needle)
    haystack_hash = roll_hash(haystack[:len(needle)])

    for i in range(len(haystack) - len(needle) + 1):
        if haystack_hash == needle_hash and haystack[i:i+len(needle)] == needle:
            return i
        if i < len(haystack) - len(needle):
            haystack_hash = (haystack_hash * 23 + ord(haystack[i+len(needle)]) - ord(haystack[i]) + 101) % 101

    return -1
