class TwoPointer:
    def __init__(self, nums):
        self.nums = nums
        self.sorted = sorted(zip(nums, range(len(nums))))
        self.ptr1 = 0
        self.ptr2 = len(nums) - 1

    def move_ptrs(self, value):
        if self.ptr1 < self.ptr2 and value <= self.sorted[self.ptr2][0]:
            self.ptr2 -= 1
        elif self.ptr1 < self.ptr2 and value >= self.sorted[self.ptr1][0]:
            self.ptr1 += 1
        elif self.ptr1 < len(self.sorted) - 1 and self.ptr2 >= 0:
            while self.ptr1 < len(self.sorted) - 1 and self.ptr2 >= 0 and self.sorted[self.ptr1][0] + self.sorted[self.ptr2][0] <= value:
                self.ptr1 += 1
            while self.ptr1 < len(self.sorted) - 1 and self.ptr2 >= 0 and self.sorted[self.ptr1][0] + self.sorted[self.ptr2][0] >= value:
                self.ptr2 -= 1
        else:
            self.ptr1 += 1
            self.ptr2 -= 1

    def search(self, target):
        while self.ptr1 < self.ptr2:
            self.move_ptrs(target - self.sorted[self.ptr1][0])
            if self.sorted[self.ptr1][0] + self.sorted[self.ptr2][0] == target:
                return self.sorted[self.ptr2][1]
        return None

