def bisect(l, val):
    if l[-1] < val:
        raise ValueError("value out of bounds")
    if l[0] > val:
        return 0
    lo, hi = 0, len(l)
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if l[mid] <= val:
            lo = mid + 1
        else:
            hi = mid
    return lo

