def solve(n, edges):
    adjacency_list = [[j for j in range(n) if [i, j] in edges] for i in range(n)]
    visited = [False] * n

    def dfs(i):
        stack = [(i, None)]
        while stack:
            node, parent = stack.pop()
            if not visited[node]:
                visited[node] = True
                for neighbor in adjacency_list[node]:
                    if neighbor != parent and not visited[neighbor]:
                        stack.append((neighbor, node))
                    elif neighbor != parent and visited[neighbor]:
                        return False
        return True

    for i in range(n):
        if not visited[i]:
            if not dfs(i):
                return 0

    return sum(1 for i in range(n) if not visited[i]) + sum(1 for adj_list in adjacency_list if adj_list) 
