def solve(n, edges):
    parent = list(range(n))
    rank = [0] * n
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]
    def union(x, y):
        rootx, rooty = find(x), find(y)
        if rootx == rooty:
            return
        if rank[rootx] > rank[rooty]:
            parent[rooty] = rootx
        elif rank[rooty] > rank[rootx]:
            parent[rootx] = rooty
        else:
            parent[rooty] = rootx
            rank[rootx] += 1
    for x, y in edges:
        union(x, y)
    return len(set(find(x) for x in range(n)))
