        newOnCount, newOffCount = 0, 0
        if e.spos < 0:
            newOnCount = off + on
        elif e.color == 1:
            newOnCount = max(0, on - c)
        else:
            newOnCount = on
        if e.epos > 0:
            newOffCount = temp - newOnCount
        newOnCount += c
        off = temp - on
        on = newOnCount
        c = temp - off
        if dp and i > 0:
            if dp[i-1] <= dp[i]:
                dp.append(dp[i])
            else:
                dp.append(dp[i-1])
        else:
            dp.append(temp)
    ans = 0
    for (i, step) in enumerate(dp):
        mini = 0
        mini_n = i
        if i > 0:
            mini = step - dp[i-1]
