        return 0

    def can_attend_all_appointments(intervals):
        intervals.sort(key=lambda x: x[1])
        end = intervals[0][1]
        count = 1
        for i in range(1, len(intervals)):
            if intervals[i][0] >= end:
                count += 1
                end = intervals[i][1]
        return count == len(intervals)

    def f(intervals):
        start = 0
        end = sum([x[1] - x[0] for x in intervals]) + 1

        while start <= end:
            mid = start + (end - start) // 2
            for i in range(mid):
                new_intervals = [x for x in intervals if x[1] - x[0] <= i or (x[0] >= i and x[1] + i < sum(x[1] - x[0] for x in intervals))]
                if can_attend_all_appointments(new_intervals):
                    start = mid + 1
                    break
            else:
                end = mid - 1
        return len(intervals) - start

    intervals.sort(key=lambda x: x[0])
    return f(intervals)
