def solve(intervals):
    class UnionFind:
        def __init__(self, n):
            self.parent = list(range(n))
            self.rank = [0] * n
            self.max_end = [end for start, end in intervals]

        def find(self, x):
            if self.parent[x] != x:
                self.parent[x] = self.find(self.parent[x])
            return self.parent[x]

        def union(self, x, y):
            root_x, root_y = self.find(x), self.find(y)
            if root_x != root_y:
                if self.rank[root_x] > self.rank[root_y]:
                    root_x, root_y = root_y, root_x
                self.parent[root_x] = root_y
                self.rank[root_y] += self.rank[root_x] + 1

    intervals.sort(key=lambda x: x[1])
    intervals_merged = [[intervals[0][0], intervals[0][1]]]
    for start, end in intervals[1:]:
        if start >= intervals_merged[-1][1]:
            intervals_merged.append([start, end])

    uf = UnionFind(len(intervals_merged))
    for i in range(len(intervals_merged)):
        i_root = uf.find(i)
        to_merge = set()
        for j in range(i + 1, len(intervals_merged)):
            j_root = uf.find(j)
            if i_root == j_root:
                continue
            if uf.max_end[j] < uf.max_end[i_root]:
                to_merge.add(i_root)
            elif uf.max_end[j] >= uf.max_end[i_root]:
                uf.union(i_root, j_root)
                to_merge.add(j_root)
                if uf.rank[j_root] >= 2:
                    to_merge.add(i_root)
            else:
                uf.union(i_root, j_root)
                to_merge.add(i_root)
        for parent in to_merge:
            for i in range(len(intervals_merged)):
                if uf.find(i) == parent:
                    uf.max_end[i] = intervals_merged[i][1]
            uf.parent[parent] = parent
            for i in range(len(intervals_merged)):
                if uf.find(i) == parent:
                    uf.max_end[i] = uf.rank[parent] - 1

    count_moved = sum(uf.rank == 0 for uf in uf.parent)
    return count_moved
