def memo(f, n, cache):
    """Memoize the n-fold application of a function f."""
    if n in cache:
        return cache[n]
    c = f(n, {k: v for k, v in cache.items()})
    cache[n] = c
    return c

def itertools_repeat(f, n):
    """Repeat applying a function f n times, yielding the results."""
    cache = {}
    for _ in range(n):
        yield memo(f, len(cache), cache)

def solve_memo_iter(n):
    """Return the n-th Fibonacci number as an exact Python int."""
    return next(itertools_repeat(solve, n))

