    A = [a[0], a[1]]
    B = [b[0], b[1]]
    F = [[0, 0], [0, 0]]
    F[0][0] = A[0] * B[0] + A[1] * B[1]
    F[0][1] = A[0] * B[1] + A[1] * B[3]
    F[1][0] = A[2] * B[0] + A[3] * B[1]
    F[1][1] = A[2] * B[1] + A[3] * B[3]
