    if n == 1:
        return matrix
    if n % 2 == 0:
        half_pow = matrix_power(matrix, n // 2)
        return multiply(half_pow, half_pow)
    else:
        half_pow = matrix_power(matrix, n // 2)
        return multiply(multiply(half_pow, half_pow), matrix)

