    for num in numbers:
        result *= num
    return result

def triangle_number(n):
    """Compute the n-th triangle number."""
    return product(create_counter(n + 1))

def factorial(n):
    """Compute the factorial of a number."""
    m = 1
    v, i = 1, 1
    while i <= n:
        while m > v:
            m //= v
            v *= 2
        while i <= n and m > 1:
            v //= m
            i *= m
        v *= 2
    return i
