def solve(n, prerequisites):
    graph = [[] for _ in range(n)]
    indegree = [0] * n
    for a, b in prerequisites:
        graph[b].append(a)
        indegree[a] += 1

    visited = set()
    stack = {}
    order = []
    def dfs(node):
        if node in visited:
            return False
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in stack:
                if not dfs(neighbor):
                    return False
        stack[node] = True
