        visited.add(a)
        for b in graph[a]:
            if b not in visited:
                if dfs(b, a):
                    return True
            elif b != parent:
                return True
        return False

    for i in range(len(graph)):
        if i not in visited and dfs(i, None):
            return True
    return False

def topological_sort(graph):
