def solve(n, prerequisites):
    graph = defaultdict(list)
    is_valid = [True] * n
    dependencies = [0] * n

    for parent, child in prerequisites:
        graph[parent].append(child)
        is_valid[child] = False
        dependencies[parent] += 1

    queue = [(0, u) for u in range(n) if is_valid[u]]

