        visited = [0] * n
        for i in range(n):
            if not dfs(graph, i, visited):
                return False
        return True

    def dfs(graph, node, visited):
        if not visited[node]:
            visited[node] = 1
            for neighbor in graph[node]:
                if visited[neighbor] == 1:
                    return False
                if visited[neighbor] == 0 and not dfs(graph, neighbor, visited):
                    return False
            visited[node] = 2
        return True

