class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, i):
        if self.parent[i] != i:
            self.parent[i] = self.find(self.parent[i])
        return self.parent[i]

    def union(self, a, b):
        pa, pb = self.find(a), self.find(b)
        if pa != pb:
            if self.rank[pa] < self.rank[pb]:
                self.parent[pa] = pb
            elif self.rank[pa] > self.rank[pb]:
                self.parent[pb] = pa
            else:
                self.parent[pb] = pa
                self.rank[pa] += 1

def solve(n, prerequisites):
    edges = [[] for _ in range(n)]
    degrees = [0] * n
    for a, b in prerequisites:
        edges[b].append(a)
        degrees[a] += 1

    union_find = UnionFind(n)
    for i in range(n):
        for j in edges[i]:
            union_find.union(i, j)

    for i in range(n):
        for j in edges[i]:
            if union_find.find(i) == union_find.find(j):
                return []

    roots = set()
    for i in range(n):
        roots.add(union_find.find(i))

    if len(roots) == 1:  # indirect elections
        pre_order = []
        pre_order_helper = lambda i: None if degrees[i] == 0 else (pre_order.append(i), degrees[i] -= 1, pre_order_helper(i), degrees[i] += 1)
        for i in range(n):
            j = union_find.find(i)
            if degrees[j] == 0: pre_order_helper(j)
        return pre_order if len(pre_order) == n else []
    return []
