    graph = [[] for _ in range(n)]
    out_degree = [0] * n

    for a, b in prerequisites:
        graph[b].append(a)
        out_degree[a] += 1

    def recursion(index, path):
        if index < 0:
            return path
        for i in range(n):
            if graph[i] and all(i in path for i in graph[i]):
                path = recursion(index - 1, path + [i])
                break
        else:
            for i in range(n):
                if out_degree[i] == 0 and i not in path:
                    return recursion(index - 1, path + [i])
            return []

        if graph[index] and all(index in path for index in graph[index]) or index not in path:
            out_degree[index] -= 1
            if index:
                graph[index].sort()
            for i in graph[index]:
                out_degree[i] -= 1
                graph[i].sort()
        return recursion(index - 1, path + [index])

    return recursion(n - 1, []) if n <= len(prerequisites) else []
