def solve(intervals):
    if not intervals:
        return []

    root = get_node(intervals[0])

    for interval in intervals[1:]:
        _ = insert_node(root, get_node(interval))

    return to_intervals(root)

def insert_node(root: Node, node: Node) -> int:
    if not root:
        root = node
        return 0

    if node.start > root.end:
        new_root = Node(node.start, node.end)
        new_root.left = root
        return root

    if node.end < root.start:
        new_root = Node(node.start, node.end)
        new_root.right = root
        return new_root

    insert_node(root.left, node) or insert_node(root.right, node)

def in_order(root: Node, result: list) -> int:
    if not root:
        return 1

    found = in_order(root.left, result)
    if found:
        result.append([root.start, root.end])

    found = in_order(root.right, result)
    return found

def to_intervals(root: Node) -> list:
    result = []
    in_order(root, result)
    return result
