def cover_int(start, end, covered):
    """Check if interval [start, end] covers any already covered interval."""
    for i, (s, e) in enumerate(covered):
        if end < s or start > e:
            continue
        return False
    return True

def extend_last(covered):
    """Extend the last added interval if possible."""
    if not covered:
        return [0, 0]
    last_start, last_end = covered[-1]
    for i in range(len(covered) - 1, -1, -1):
        now_start, now_end = covered[i]
        if now_start <= last_end + 1 and now_end > last_end:
            covered[i] = (now_start, now_end)
            last_end = now_end
        else:
            break
    return covered

def solve(intervals):
    """Merge overlapping intervals."""
    covered = []
    for start, end in intervals:
        if cover_int(start, end, covered):
            continue
        if covered and covered[-1][1] >= start - 1:
            covered[-1] = (covered[-1][0], max(covered[-1][1], end))
        else:
            covered.append((start, end))
        covered = extend_last(covered)
    return covered
