        if end1 < start2:
            return start1, end1, start2, end2
        elif end2 < start1:
            return start1, end1, start2, end2
        else:
            return min(start1, start2), max(end1, end2), 0, 0

    def find_next_start(intervals):
        return min(start for start, end, _, _ in intervals if start >= 0)

    intervals = [(start, end, 1) for start, end in intervals]  # perfect intervals
    for i in range(len(intervals)):
        for j in range(i):
            if intervals[j][2] == 1:  # if an interval has been merged
                continue
            start1, end1, flag1 = intervals[i]
            start2, end2, flag2 = intervals[j]
            start1, end1, start2, end2 = merge_interval(start1, end1, start2, end2)  # merge the interval, the last field can not be used for intervals without splits
            intervals[i] = start1, end1, flag1 + flag2  # create a new interval with merge_intervals
            intervals[j] = start2, end2, flag2  # the j-th interval remains the same, in the condition with two perfect merging steps

        if intervals[i][2] == 1:  # pick intervals bigger than 0 and make them "perfect" and ready for next round
            intervals[i] = intervals[i][0], intervals[i][1], 1

        start, end, _ = intervals[i]
        if start < 0:
            intervals[i] = 0, end, _

    intervals = [(start, end) for start, end, _ in intervals if _ == 2]
    end = max(end for _, end in intervals)
    intervals += [(find_next_start(intervals), end)]
    return intervals
