class UnionFind:
    def __init__(self):
        self.parent = {}
        self.rank = {}

    def add(self, x):
        if x not in self.parent:
            self.parent[x] = x
            self.rank[x] = 0

    def find(self, x):
        root = x
        while self.parent[root] != root:
            root = self.parent[root]
        while x != root:
            self.parent[x], x = root, self.parent[x]
        return root

    def union(self, x, y):
        rootx, rooty = self.find(x), self.find(y)
        if rootx == rooty:
            return
        if self.rank[rootx] < self.rank[rooty]:
            self.parent[rootx] = rooty
        elif self.rank[rootx] > self.rank[rooty]:
            self.parent[rooty] = rootx
        else:
            self.parent[rooty] = rootx
            self.rank[rootx] += 1


def solve(intervals):
    P = [i << 16 ^ j for i, j in intervals]
    P.sort()
    res = []
    uf = UnionFind()

    for p in P:
        i, j = p >> 16, p & 0xFFFF
        root = uf.find(i)
        if root not in uf.parent or uf.find(j) != root:
            uf.add(j)
            if root:
                uf.union(root, j)
            else:
                root = j
        if root not in res:
            res.append([i, j])

    return res
