    for i, (start, end) in enumerate(intervals):
        events[i].start, events[i].end = start, end

    def merge_current():
        while sum(event.end - event.start for event in events) > 0:
            events.sort()
            current_start = events[0].start
            j = 0
            while j < len(events) - 1 and events[j].end >= events[j + 1].start:
                events[j].start = current_start
                current_start = min(events[j].end, events[j + 1].end)
                del events[j + 1]
                if j > 0:
                    j -= 1
            events[0].end = current_start
            del events[0]

    def merge_partition(start, end):
        if start >= end:
            return
        merge_current()
        mid = (start + end) // 2
        merge_partition(start, mid)
        merge_partition(mid + 1, end)

    merge_partition(0, len(events))
    return [[event.start, event.end] for event in events]
