def merge(intervals):
    x = int(100 * 1500 ** 0.5)

    def devide(unmerged):
        if len(unmerged) <= 1:
            return unmerged

        pivot = 0
        i = 1
        while i <= len(unmerged) and unmerged[i][0] - unmerged[pivot][0] <= x:
            i += 1
        i -= 1
        left = unmerged[:i]
        right = unmerged[i:]

        return left, right

    def combine(x, y):
        if not x or not y:
            return x or y
        return [min(x[0], y[0]), max(x[-1], y[-1])]

    while len(intervals) > 1:
        left, right = devide(intervals)
        intervals = []

        while left and right:
            merged = combine(left.pop(), right.pop())
            intervals.append(merged)

        intervals.extend(left)
        intervals.extend(right)

    def helper(unmerged):
        if not unmerged:
            return []
        if len(unmerged) == 1:
            return unmerged

        pivot = 0
        i = 1
        while i < len(unmerged):
            if unmerged[i][0] <= unmerged[pivot][0] and unmerged[i][1] > unmerged[pivot][1]:
                unmerged[pivot], unmerged[i] = unmerged[i], unmerged[pivot]
            else:
                i += 1
        left = unmerged[1:]
        min_end = float('-inf')
        right = []
        for v in left:
            if v[0] <= min_end:
                min_end = max(min_end, v[1])
            else:
                min_end = max(min_end, v[1])
                right.append([min_end+1,v[1]])
                min_end = v[0]
        if min_end != float('-inf'):
            right.append([min_end + 1, v[1]])
