def solve(intervals):
    def covered(start, end, other_start, other_end):
        return max(start, other_start) <= min(end, other_end)

    def mergeable(start, end, other_start, other_end):
        return covered(start, end, other_start, other_end) and max(start, other_start) != min(end, other_end)

    def iter_merge(intervals):
        start, end = intervals
        for i in iter_merge(intervals[1:]):
            if mergeable(start, end, *i):
                start = min(start, i[0])
                end = max(end, i[1])
                continue
            yield (start, end)
            start, end = i
        yield (start, end)

    return list(iter_merge(intervals))
