    if not intervals:
        return []

    # Initialize two sets to keep track of intervals that start and end on the current line
    starts = set()
    ends = set()

    # Visit all intervals in order by their end points
    for start, end in sorted(intervals, key=lambda x: x[1]):
        # Remove intervals that ended before the current interval starts, and add the current interval's start
        starts -= {x for x, _ in (starts | ends) if x < start}
        starts.add(start)

        # Add a new end point for all current start points that do not overlap with the current interval
        ends |= {x for x, _ in starts if x > end}

    # Return the merged intervals with their sorting and overlap checks
    result = []
    for x in sorted(starts | ends):
        if not result or result[-1][1] < x:
            result.append([x, (ends | {x} - starts).pop()])
