from typing import Dict

def solve(nums: list[int], k: int) -> list[int]:
    freqs: Counter[int] = Counter()
    for num in nums:
        freqs[num] += 1

    max_freq = max(freqs.values())
    most_common = freqs.most_common()

    def remove_element(frequency_dict: Dict[int, int], key: int, value: int) -> None:
        to_remove = {k: v for k, v in frequency_dict.items() if v == value}
        for k, v in to_remove.items():
            del frequency_dict[k]

    rank = 1
    for i, (_, f) in enumerate(most_common):
        if f == max_freq:
            remove_element(freqs, _, f)
            rank += 1
            if rank == k:
                return [int(_) for _, f in most_common[:i]]

    return []
