def solve(nums):
    if not nums:
        return 0

    def maximum(dp, val):
        for i, (prev, incr) in enumerate(dp):
            if val > prev and incr > dp[i][1]:
                dp[i] = (val, incr + 1)
                return max(dp, key=lambda x: x[1]) if dp else -1
        return max(dp, key=lambda x: x[1]) if dp else -1

    dp = [(float('-inf'), 1)]
    for num in nums:
        dp = [maximum(dp, num)] or [(float('-inf'), 1), (num, 1)]
    return max(dp, key=lambda x: x[1])[1] if dp else -1
