def solve(nums):
    if not nums:
        return 0

    m = [nums[0]]
    for num in nums[1:]:
        if num > m[-1]:
            m.append(num)
        else:
            idx = binary_search(m, num)
            m[idx] = num

    return len(m)

def binary_search(m, num):
    left, right = 0, len(m)
    while left < right:
        mid = (left + right) // 2
        if m[mid] < num:
            left = mid + 1
        else:
            right = mid
    return left
