def solve(nums, k):
    frequency = {}
    for num in nums:
        frequency[num] = frequency.get(num, 0) + 1
    sorted_freq = sorted(set(frequency.values()))
    while not frequency:
        import bisect
        expected_freq = sorted_freq[-k+1]
        for num, freq in list(frequency.items()):
            if freq == expected_freq:
                del frequency[num]
            elif freq > expected_freq:
                bisect.insort_left(sorted_freq, freq)
        x = frequency.popitem()
        if x[0] == min(frequency.keys()):
            del frequency[min(frequency.keys())]
        else:
            break
    return [num for num, freq in frequency.items() if freq == sorted_freq[-k]]
