def solve(nums, k):
    count = collections.Counter(nums)
    max_freq = max(count.values())
    most_freq = [x for x, y in count.items() if y == max_freq]
    mins = [max_freq - x + 1 for x in range(1, k)]
    heap = Heap()
    for x in most_freq:
        heap.append(max_freq - count[x])
        if len(heap.heaps) < k:
            continue
        mins[-1] = math.inf
        min_heap = []
        for val, freq in count.items():
            if -heap.pop() not in mins or freq + 1 >= mins[mins.index(-heap.pop())]:
                min_heap.append((freq, val))
        min_heap.sort()
        for j, freq in sorted(((i, -freq) for i, freq in enumerate(mins)), key=lambda x: x[1]):
            mins[j] = math.inf
            found = False
            for i, (f, val) in enumerate(min_heap):
                if f + 1 >= freq:
                    mins[j] = val
                    del min_heap[i]
                    if len(min_heap) == j - 1:
                        heapq.heapify(min_heap)
                    found = True
                    break
            if not found:
                j -= 1
        if -heap.pop() in mins:
            heap.pop()
        if len(heap.heaps) < k:
            continue
        for j, freq in sorted(((i, -freq) for i, freq in enumerate(mins)), key=lambda x: x[1]):
            if mins[j] not in heap.heaps and math.inf in heap.heaps:
                j = heap.heaps.index(math.inf)
            mins[j] = math.inf
            found = False
            for i in range(len(heap.heaps)):
                if heap.heaps[i] < freq:
                    found = True
                    break
            if found:
                if heap.heaps.index(freq) != j:
                    heap.heaps[j], heap.heaps[heap.heaps.index(freq)] = heap.heaps[heap.heaps.index(freq)], heap.heaps[j]
                    break
            for i, x in enumerate(heap.heaps):
                if x < freq:
                    heap.heaps[i] = math.inf
                    heap.heaps[j], heap.heaps[i] = heap.heaps[i], heap.heaps[j]
                    mins[j] = freq
                    break
    return most_freq
