def solve(nums, k):
    max_freq = {}
    for num in nums:
        max_freq[num] = max_freq.get(num, 0) + 1

    candidates = [(freq, num) for num, freq in max_freq.items()]
    n = len(nums)

    def check(i):
        return sum(1 for freq, num in candidates[:i+1] if freq > 0) >= n - k

    left, right = 0, k
    while left < right:
        mid = left + (right - left) // 2
        if check(mid):
            right = mid
        else:
            left = mid + 1
    return [num for _, num in candidates[:right+1]]
