    k_max, k_bucket = most_common_count(counts)

    for count in sorted(counts.values(), reverse=True):
        if count == k_max:
            for b in bucket_counts[count]:
                nums.insert(0, b)
                return nums[:k]
        elif count < k_max:
            most_frequent_tables = []
            for bucket_count in bucket_counts.values():
                for i, c in enumerate(bucket_count):
                    if c == k_max:
                        most_frequent_tables.append((c * (2**i), k_max))
            nums = []
            for i, (table, count) in enumerate(most_frequent_tables):
                for n in counts:
                    if counts[n] == count:
                        nums.extend([table[len(nums) % (2**i)]] * counts[n])
