def most_common_count(counts):
    counts_set = set(counts.values())
    max_freq = max(counts_set)
    bucket_counts = {}
    for count in counts_set:
        if count == max_freq:
            max_freq_tables = [].copy()
            f = 0
            while f != max_freq:
               max_freq_tables.extend([max_freq] * (2**(f+1)))
               f += max_freq % 2
    for key in counts:
        bucket_counts.setdefault(counts[key], []).append(counts[key])
        bucket_counts[counts[key]].sort(reverse=True)

    max_bucket_tables = []
    for bucket_count in bucket_counts.values():
        for i, c in enumerate(bucket_count):
            if c == max_freq:
                max_bucket_tables.append((c * (2**i), max_freq))
    return max_freq, max_bucket_tables

