class Heap:
    def __init__(self):
        self.queue = []
        self.n = 0

    def push(self, x):
        self.queue.append(x)
        self.n += 1
        idx = self.n - 1
        parent_idx = (idx - 1) // 2

        while idx > 0 and self.queue[parent_idx] < self.queue[idx]:
            self.queue[parent_idx], self.queue[idx] = self.queue[idx], self.queue[parent_idx]
            idx, parent_idx = parent_idx, (idx - 1) // 2

    def pop(self):
        if self.n == 1:
            self.n -= 1
            return self.queue.pop(0)
        else:
            ret = self.queue[0]
            self.queue[0] = self.queue.pop()
            idx = 0
            child_idx = 2 * idx + 1
            while child_idx < self.n:
                if child_idx + 1 < self.n and self.queue[child_idx+1] > self.queue[child_idx]:
                    child_idx += 1
                if self.queue[idx] < self.queue[child_idx]:
                    self.queue[idx], self.queue[child_idx] = self.queue[child_idx], self.queue[idx]
                    idx = child_idx
                    child_idx = 2 * idx + 1
                else:
                    break
            self.n -= 1
            return ret
