import bisect

def solve(nums, k):
    def findMajority(nums):
        count = defaultdict(int)
        for n in nums:
            count[n] += 1
        return max(count.items(), key=lambda x: x[1])

    def countOccurrences(nums, num):
        occurrences = bisect.bisect_right(nums, num)
        return nums.count(num) + occurrences - (occurrences * 2 - len(nums))

    most_common = findMajority(nums)
    max_count = most_common[1]
    heap = []
    for num in set(nums):
        c = countOccurrences(nums, num)
        if c == max_count and len(heap) < k - 1:
            heapq.heappush(heap, (-c, num))
        elif c > max_count:
            if len(heap) < k - 1:
                heapq.heappush(heap, (-c, num))
            elif heap[0][0] < -c:
                heapq.heappop(heap)
                heapq.heappush(heap, (-c, num))
    for i in range(k - 1, 0, -1):
        heapq.heappop(heap)
    else:
        return [n for _, n in heap]
    return [n for _, n in heap]
