    def smallest_factorization(n):
        if n == 1: return []
        result = []
        for i in range(2, int(n ** 0.5) + 1):
            while n % i == 0:
                result.append(i)
                n //= i
        if n > 1: result.append(n)
        return result
    def get_factors(n):
        factors = set()
        for i in range(1, int(n ** 0.5) + 1):
            if n % i == 0: factors.add(i); factors.add(n // i)
        return factors
    def get_nth_factorial_prime(n):
        factors = get_factors(n)
        primes = []
        for factor in factors:
            if factor > 1:
                is_prime = True
                for i in range(2, int(factor ** 0.5) + 1):
                    if factor % i == 0:
                        is_prime = False
                        break
                if is_prime: primes.append(factor)
        primes.sort()
        return primes[n - 1] if n <= len(primes) else None
    counter = sorted(Counter(nums).items(), key=lambda x: x[1], reverse=True)
    count = counter[0][1]
    deleted = set()
    most_frequent = [x[0] for x in counter if x[1] == count]
    stack = [(most_frequent, 0, list(most_frequent))]
    while k:
        k -= 1
        stack.append(([], 0, []))
        while stack:
            freq, i, lst = stack.pop()
            if i == len(lst):
                stack.pop()
                if freq: most_frequent.extend(freq)
            else:
                if (lst[i] not in deleted) and Counter(nums)[lst[i]] > count:
                    stack.append((freq, i, lst))
                    stack.append((freq + [lst[i]], i + 1, lst))
                else:
                    deleted.add(lst[i])
        count -= 1
    return most_frequent

