    nums = [1]
    factors = [0] * len(primes)
    for _ in range(n - 1):
        v = min([nums[i] * primes[i] for i in range(len(primes))])
        for i in range(len(primes)): factors[primes.index(nums[i] * primes[i])] += 1
        for i in range(len(primes)): while nums[factors[i]] == v: v = min([nums[j] * primes[i] for j in range(len(primes)) if j != i])
        nums.append(v)
    return nums[-1]

