from collections import defaultdict

def solve(nums, k):
    freq = defaultdict(int)
    for n in nums:
        freq[n] += 1

    def can(u, m):
        for key in freq:
            rs = freq[key]
            uu, mm = divmod(rs, u)
            if mm and uu + 1 < m:
                return False
        return True

    low, high = 1, (max(freq.values()) + 1) // k
    while low < high:
        mid = (low + high + 1) // 2
        if can(mid, k):
            low = mid
        else:
            high = mid - 1
    return [n for n, f in freq.items() if f >= low]
