def solve(nums, k):
    '''Returns the k-th smallest value in nums'''
    # Helper class to store values and their frequencies
    class Counter:
        def __init__(self, value, freq):
            self.value = value
            self.freq = freq

        def __lt__(self, other):
            return self.freq < other.freq

    # Count the frequencies of each value
    count_map = {}
    for num in nums:
        if num in count_map:
            count_map[num] += 1
        else:
            count_map[num] = 1

    # If k is larger than the number of distinct values, return None
    k = min(k, len(count_map))

    # Create a list of Counters and sort it
    counter_list = [Counter(val, freq) for val, freq in count_map.items()]
    counter_list.sort()

    # Return the k-th smallest element
    return counter_list[k-1].value
