    seen = sorted(set(nums))
    k_positions = bisect.bisect_left(seen, nums[k - 1])
    if k_positions == 0:
        return seen[0]
    elif k_positions == len(seen):
        return seen[-1]
    left_count = sum(1 for x in nums if x < seen[k_positions])
    right_count = sum(1 for x in nums if x > seen[k_positions])
    prev_k_positions = bisect.bisect_left(seen, seen[k_positions] - 1)
    if k_positions - prev_k_positions + 1 + left_count < k:
        return seen[k_positions]
    elif k_positions + right_count < k:
        return seen[k_positions + 1]
    else:
        prev_k_positions = bisect.bisect_left(seen, seen[k_positions - 1] + 1)
