    l_ = r = l
    val_ = res[l]
    while True:
        while l < r and res[l] < val_:
            l += 1
        while l < r and res[r] > val_:
            r -= 1
        if l == r:
            break
        res[l], res[r] = res[r], res[l]
    res[r], res[l] = res[l], res[r]
