    if l == r:
        return
    pivot = quickselect(l, r, r - l + 2)
    left_val = res[pivot + 1]
    right_val = res[r]
    if pivot != r - l:
        res[pivot], res[r - l] = res[r - l], res[pivot]
    left = r - l
    curr = r - l
    for i in range(l, pivot):
        if res[i] <= left_val:
            res[curr + 1], res[i] = res[i], res[curr + 1]
            curr += 1
    if pivot != r - l:
        res[curr], res[r - l] = res[r - l], res[curr]
        curr += 1
    for i in range(pivot+2, r+1):
        if res[i] <= right_val:
            res[i], res[curr] = res[curr], res[i]
            curr += 1
    res[curr:], res[r - l + 1:] = res[r - l + 1:], res[curr:]
    if curr == r - l + 1:
        sorting(l, curr - 1)
        sorting(curr + 1, r)
    return res

