def solve(nums, k):
    """Finds the k-th smallest value in the list nums."""

    def median_of_three(a, b, c):
        """Chooses a median from a, b, and c."""
        if a <= b <= c:
            return b
        if a <= c <= b:
            return c
        if b <= a <= c:
            return a
        if b <= c <= a:
            return c
        if c <= a <= b:
            return a
        return b

    def quickselect(nums, k):
        """Finds the k-th smallest element in nums using quickselect."""
        if len(nums) == 1:
            return nums[0]

        pivot = median_of_three(nums[0], nums[-1], nums[len(nums)//2])
        left = [x for x in nums[1:-1] if x < pivot]
        middle = [x for x in nums[1:-1] if x == pivot]
        right = [x for x in nums[1:-1] if x > pivot]

        if k <= len(left):
            return quickselect(left, k)
        elif k <= len(left) + len(middle):
            return middle[0]
        else:
            return quickselect(right, k - len(left) - len(middle))

    nums.sort()
    return quickselect(nums, k)
