class SortedList:
    def __init__(self, numbers):
        self.numbers = sorted(numbers)
        self.bisect = {}

        for i, n in enumerate(self.numbers):
            if n not in self.bisect:
                self.bisect[n] = []
            self.bisect[n].append(i)

    def insert(self, x):
        if x not in self.bisect:
            self.bisect[x] = []
        self.bisect[x].append(len(self.numbers))
        self.numbers.append(x)
        self.numbers.sort()

    def remove(self, x):
        if x in self.bisect:
            idx = self.bisect[x].pop()
            self.numbers.pop(idx)
            if self.bisect[x]:
                self.bisect[x][-1] += 1

    def bisect_left(self, x):
        for bisect_list in self.bisect.values():
            if bisect_list:
                if bisect_list[-1] > 0:
                    self.numbers.insert(bisect_list[-1], x)
                    bisect_list.append(bisect_list[-1])
                    bisect_list[-2] += 1
                    bisect_list.pop()
                    return bisect_list[-1]
                bisect_list[-1] += 1
        self.insert(x)
        return len(self.numbers)-1

    def bisect_right(self, x):
        for bisect_list in self.bisect.values():
            if bisect_list:
                if bisect_list[-1] < len(self.numbers)-1:
                    self.numbers.insert(bisect_list[-1]+1, x)
                    bisect_list.append(-1)
                    bisect_list[-2] -= 1
                    bisect_list.pop()
                    return bisect_list[-1]
                bisect_list[-1] -= 1
        self.insert(x)
        return len(self.numbers)-1

def get_kth_smallest(nums, k):
    sorted_list = SortedList(nums)
    for i in range(len(nums)-1):
        idx = sorted_list.bisect_left(nums[i+1])
        sorted_list.remove(nums[idx])
    return sorted_list.numbers[k-1]

def solve_efficient(nums, k):
    return get_kth_smallest(nums, k)

def solve_efficient_bruteforce(nums, k):
    return sorted(nums)[k-1]
