def solve(haystack, needle):
    def char_to_num(c):
        return ord(c) - ord('a')

    def containment(a, b):
        return all(a[i] <= b[i] for i in range(len(a)))

    def matching(i):
        j = 0
        while j < len(needle) and i + j < len(haystack) and haystack[i + j] == needle[j]:
            j += 1
        return j == len(needle)

    def bisect_left(a, x, lo = 0, hi = None):
        if hi is None:
            hi = len(a)
        while lo < hi:
            mid = (lo+hi)//2
            if containment(a[mid], (x,)):
                hi = mid
            else:
                lo = mid + 1
        return lo

    if not needle:
        return -1
    if len(needle) > len(haystack):
        return -1

    nums = [char_to_num(c) for c in needle]
    seen = set()
    for i in range(len(haystack)):
        subset = ( nums[ : bisect_left(nums, nums[0], i + 1)] if i + 1 >= len(nums) else 
                  nums[ : bisect_left(nums[nums[0]], nums[i + 1])]
                 )
        if subset not in seen and matching(i):
            seen.add(subset)
            return i

    return -1
