def solve(haystack, needle):
    def match(a, b):
        n = len(needle)
        m = len(haystack)
        same = [[0] * (n + 1) for _ in range(m + 1)]
        for i in range(m + 1):
            same[i].append(-1)
        curr_len = 0
        for i in range(m + 1):
            for j in range(n + 1):
                if a[i-1] == b[j-1]:
                    if j == 0:
                        same[i].append(1)
                    elif curr_len == 0 or a[i-1] == a[same[i-1][curr_len]-1]:
                        same[i].append(curr_len + 1)
                        curr_len += 1
                    else:
                        same[i].append(1)
                        curr_len = 1
                else:
                    if j > 0:
                        curr_len = same[i][curr_len]
        if curr_len == n:
            return True, same[m][n] - 1
        return False, -1

    def recursive_search(a, b):
        m = len(b)
        if m == 0:
            return 0
        res, pos = match(a, b)
        if res:
            return pos
        if len(a) >= 2 and a[:2] == b[:2]:
            return 2
        if len(a) == 1 and b[0] == a[0]:
            i = 1
            while i < m and a[0] == b[i]:
                i += 1
            if i == m:
                return 0
        while i + 1 < len(a) and 0 < i and (i == 1 or a[i] == a[i-2] or a[i] == b[i-1]):
            a = a[:i-2] + a[i+1:]
            i -= 1
        return recursive_search(a, b)

    return recursive_search(haystack, needle)
