def solve(haystack, needle):
    def rabin_karp(haystack, needle, base=256):
        n = len(haystack)
        m = len(needle)
        shift = 1
        for _ in range(m - 1):
            shift *= base

        d = ord('z') - ord('a') + 1
        p = 0
        pow = 1
        for _ in range(m):
            p = (p * base + ord(needle[-1 - _])) % d
            pow = (pow * base) % d

        h = 0
        for _ in range(m):
            h = (base * h + ord(haystack[n - 1 - _])) % d

        result = [-1] * n
        p = h
        for i in range(n - m + 1):
            if p == pow * int(h % d) and haystack[i:i + m] == needle:
                result[i + m - 1] = i
            if i < n - m:
                p = (base * (p - ord(haystack[i]) * pow) + ord(haystack[i + m])) % d
                if p < 0:
                    p += d

        return result

    return rabin_karp(haystack, needle).index(0) if 0 in rabin_karp(haystack, needle) else -1
