    def rolling_hash(s, size):
        n = ord('z') + 1
        hashes = {}
        cur_hash = 0
        for i in range(size):
            cur_hash = (cur_hash * 29 + ord(s[i]) - ord('a') + 1) % (n ** size)
        hashes[0] = cur_hash
        for i in range(1, size):
            mult = (n ** (i - 1)) % (n ** size)
            cur_hash = (cur_hash * mult + ord(s[i - 1]) - ord('a') + 1) % (n ** size) - (n ** (size - 1) + ord(s[i - 1]) - ord('a') + 1) % (n ** size) * mult
            cur_hash = (cur_hash % (n ** size) + n ** size) % (n ** size)
            hashes[i] = cur_hash
        return hashes

    n = ord('z') + 1
    needle_hsh = 0
    for c in needle:
        needle_hsh = (needle_hsh * 29 + ord(c) - ord('a') + 1) % (n ** len(needle))
