    m, n = len(needle), len(haystack)
    buckle_sort_pos = m - 1
    if m > n:
        return -1
    for i in range(n - m + 1):
        t = 0
        while t <= m - 1 and needle[t] == haystack[i + t]:
            t += 1
        if t == m:
            return i
        next_possible_pos = bad_char[ord(haystack[i + m]) - ord('a')]
        if m + next_possible_pos + 1 <= i + n:
            next_possible_pos = n - m
        buckle_sort_pos = max(buckle_sort_pos, i + m + next_possible_pos)
        i = buckle_sort_pos
    return -1

