def solve(n, edges):
    """Returns the number of connected components of an undirected graph."""

    parent = list(range(n))  # Parent of each node is itself, so each is in its own component
    rank = [0] * n  # Rank of each component for path compression

    def find(x):
        """Finds the root of the set containing x."""
        if parent[x] != x:
            parent[x] = find(parent[x])  # Path compression
        return parent[x]

    def union(x, y):
        """Merges the sets containing x and y into a single set."""
        rx, ry = find(x), find(y)
        if rx == ry:
            return  # x and y are already in the same set
        if rank[rx] < rank[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1

    for u, v in edges:
        union(u, v)

    return len(set(find(x) for x in range(n)))
