class DisjointSetUnion:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n
        self.num_sets = n

    def find(self, p):
        if p != self.parent[p]:
            self.parent[p] = self.find(self.parent[p])
        return self.parent[p]

    def union(self, p, q):
        prt, qrt = self.find(p), self.find(q)
        if prt == qrt:
            return
        if self.rank[prt] > self.rank[qrt]:
            self.parent[qrt] = prt
        elif self.rank[prt] < self.rank[qrt]:
            self.parent[prt] = qrt
        else:
            self.parent[prt] = qrt
            self.rank[qrt] += 1
        self.num_sets -= 1
