import bisect

def generalize_sort(nums, k):
    if not nums:
        return None

    return nums[k - 1]

def counting_sort(nums):
    unique_nums = sorted(set(nums))
    counts = [0] * len(unique_nums)
    for num in nums:
        i = bisect.bisect_right(unique_nums, num)
        counts[i - 1] += 1
    result = []
    for i in range(len(unique_nums)):
        result.extend([unique_nums[i]] * counts[i])
    return result

def constant_time_sort(nums):
    mid = len(nums) >> 1
    counts = [0] * len(nums)
    for num in nums:
        counts[num] += 1
    sorted_nums = [0] * len(nums)
    for i in range(len(nums)):
        total = 0
        for j in range(len(nums)):
            total += counts[j]
            if total < mid:
                sorted_nums[i] = j
            else:
                sorted_nums[i] = j + (-total + mid) % len(nums)
                break
    return sorted_nums

def solve(nums, k):
    sorted_nums = constant_time_sort(nums)
    return generalization_sort(sorted_nums, k)
